    private void initModernBankWindowWidgets(int left, int top, int right, int bottom) {
        OwnerPcBankDataPayload data = ClientOwnerPcData.getCurrentBankData();
        boolean dataReady = data != null && activeBankId != null && activeBankId.equals(data.bankId());
        int appW = Math.max(1, right - left);
        boolean compact = appW < 980;
        boolean modalOpen = isModernBankActionModalOpen()
                || isVaultRouteModalOpen()
                || isMarketDetailModalOpen()
                || (activeSection == Section.LENDING && pendingMarketAccept != null)
                || selectedAccountTransaction != null;
        int outerInset = ownerPcOuterInset(appW);
        int sidebarW = ownerPcSidebarWidth(appW, false);
        int sidebarX = left + outerInset;
        int sidebarY = top + 18;
        int sidebarH = Math.max(120, bottom - top - 36);
        int contentX = sidebarX + sidebarW + ownerPcSidebarGap(appW);
        int contentRight = right - outerInset;
        int headerY = top + 18;
        int headerH = 72;
        boolean sidebarCard = shouldShowOwnerPcSidebarCard(appW, sidebarW, sidebarH);
        int navPad = ownerPcSidebarInnerPad(sidebarW);

        navViewportX = sidebarX + navPad;
        navViewportY = sidebarY + (sidebarCard ? 202 : 78);
        navViewportW = Math.max(64, sidebarW - (navPad * 2));
        navViewportH = Math.max(40, sidebarY + sidebarH - navViewportY - 16);

        if (!BANK_NAV_SECTIONS.contains(activeSection)) {
            activeSection = Section.OVERVIEW;
        }
        int sectionH = appW < 620 ? 24 : (compact ? 26 : 28);
        int sectionGap = appW < 620 ? 5 : (compact ? 6 : 8);
        int totalNavHeight = (BANK_NAV_SECTIONS.size() * sectionH) + ((BANK_NAV_SECTIONS.size() - 1) * sectionGap);
        navMaxScroll = navScrollMax(totalNavHeight, navViewportH);
        navScroll = Math.max(0, Math.min(navScroll, navMaxScroll));
        int navY = navViewportY - navScroll;
        for (int i = 0; i < BANK_NAV_SECTIONS.size(); i++) {
            Section section = BANK_NAV_SECTIONS.get(i);
            int buttonY = navY + (i * (sectionH + sectionGap));
            String label = section == activeSection ? bankSectionLabel(section) + " *" : bankSectionLabel(section);
            DesktopButton button = addPcButton(
                    navViewportX,
                    buttonY,
                    navViewportW,
                    sectionH,
                    label,
                    section == activeSection ? ORDER_BOARD_CYAN : 0xFF7895B4,
                    btn -> {
                        VaultRouteEditorClientState.clear();
                        vaultRouteEditorScroll = 0;
                        vaultRouteDetailsScroll = 0;
                        activeSection = section;
                        bankActionModal = BankActionModal.NONE;
                        premiseDeleteState = OwnerPcPremiseDeleteLifecycle.closed();
                        overviewDetailOpen = false;
                        overviewDetailAction = "SHOW_INFO";
                        selectedAccountCard = null;
                        accountProfileOpen = false;
                        selectedAccountTransaction = null;
                        accountHistoryScroll = 0;
                        lendingMarketOpen = false;
                        pendingMarketAccept = null;
                        marketDetailOffer = null;
                        marketOfferCache.clear();
                        refreshMarketAfterNextResponse = false;
                        ClientOwnerPcData.clearActionOutput();
                        outputScroll = 0;
                        sectionScroll = 0;
                        rebuildWidgets();
                    }
            );
            button.setLabelOffset(6, 1).setIconOffset(1, 0);
            boolean visible = !modalOpen && buttonY >= navViewportY && (buttonY + sectionH) <= (navViewportY + navViewportH);
            button.visible = visible;
            button.active = visible;
        }

        int toolbarY = headerY + 20;
        int headerContentW = Math.max(1, contentRight - contentX);
        int toolbarButtonW = toolbarButtonWForRender(headerContentW, compact);
        boolean showPremiseClaim = dataReady
                && activeSection == Section.PREMISES
                && hasPremisePresentationPermission(data);
        PremiseHeaderActions headerActions = premiseHeaderActions(
                contentX, contentRight, headerY, toolbarY, toolbarButtonW, showPremiseClaim);
        DesktopButton refreshButton = addPcButton(
                        headerActions.refreshX(),
                        headerActions.refreshY(),
                        headerActions.refreshWidth(),
                        24,
                        "Refresh",
                        btn -> requestBankData(activeBankId))
                .setLabelOffset(4, 2);
        refreshButton.visible = !modalOpen;
        refreshButton.active = !modalOpen;
        if (showPremiseClaim) {
            DesktopButton claimButton = addPcButton(
                            headerActions.claimX(),
                            headerActions.claimY(),
                            headerActions.claimWidth(),
                            24,
                            "Claim Premise",
                            ORDER_BOARD_CYAN,
                            btn -> startPremiseClaimAndClose())
                    .setLabelOffset(4, 2);
            claimButton.visible = !modalOpen;
            claimButton.active = !modalOpen;
            if (claimButton.visible) {
                addBankHelpHitbox(
                        headerActions.claimX(),
                        headerActions.claimY(),
                        headerActions.claimWidth(),
                        24,
                        "Claim Premise",
                        "Close the Owner PC and start the in-world premise claim tool.");
            }
        }

        sectionViewportX = contentX;
        sectionViewportY = headerY + headerH + 18;
        int contentMinW = appW < 420 ? 72 : 120;
        sectionViewportW = Math.max(contentMinW, contentRight - contentX);
        sectionViewportH = Math.max(80, bottom - sectionViewportY - 18);
        outputPanelX = 0;
        outputPanelY = 0;
        outputPanelW = 0;
        outputPanelH = 0;

        int sectionContentW = Math.max(contentMinW, sectionViewportW - 32);
        int contentHeight = getModernBankSectionContentHeight(dataReady ? data : null, sectionContentW);
        if (dataReady && activeSection == Section.PREMISES) {
            OwnerPcPremisesPanelLayout.Layout premisesLayout = OwnerPcPremisesPanelLayout.layout(
                    sectionContentW, sectionViewportH, data.premises().size(), sectionScroll);
            sectionMaxScroll = premisesLayout.maxScroll();
            sectionScroll = premisesLayout.clampedScroll();
        } else {
            sectionMaxScroll = pixelScrollMax(contentHeight, sectionViewportH);
            sectionScroll = Math.max(0, Math.min(sectionScroll, sectionMaxScroll));
        }

        if (!dataReady) {
            addModernBankContentButton(
                    sectionViewportX + 16,
                    sectionViewportY + 16,
                    Math.min(220, sectionViewportW - 32),
                    28,
                    "Load Bank Data",
                    ORDER_BOARD_CYAN,
                    btn -> requestBankData(activeBankId)
            );
            return;
        }

        if (modalOpen) {
            if (isVaultRouteModalOpen()) {
                initVaultRouteModalWidgets(data);
            } else {
                initModernBankModalWidgets(data);
            }
        } else {
            initModernBankSectionWidgets(data, sectionViewportX, sectionViewportY, sectionViewportW);
        }
    }

    private void initModernBankSectionWidgets(OwnerPcBankDataPayload data, int x, int y, int width) {
        boolean ownerView = data != null && data.ownerView();
        int gap = 10;
        int innerX = x + 16;
        int innerW = Math.max(120, width - 32);
        switch (activeSection) {
            case OVERVIEW -> initModernBankOverviewWidgets(data, innerX, y, innerW, ownerView);
            case ACCOUNTS -> initModernBankAccountsWidgets(data, innerX, y, innerW, ownerView);
            case SAFE -> initModernBankSafeWidgets(data, innerX, y, innerW);
            case PREMISES -> initModernBankPremisesWidgets(data, innerX, y, innerW);
            case BRANDING -> initModernBankBrandingWidgets(data, innerX, y, innerW, ownerView);
            case LIMITS -> initModernBankLimitsWidgets(data, innerX, y, innerW, ownerView);
            case GOVERNANCE -> initModernBankGovernanceWidgets(innerX, y, innerW, ownerView);
            case STAFFING -> initModernBankStaffingWidgets(innerX, y, innerW, ownerView);
            case LENDING -> initModernBankLendingWidgets(innerX, y, innerW, ownerView);
            case COMPLIANCE -> initModernBankComplianceWidgets(innerX, y, innerW, ownerView);
            case BUSINESS, HOURS, PERMISSIONS -> {
            }
        }
    }

    private void initModernBankOverviewWidgets(OwnerPcBankDataPayload data, int x, int y, int width, boolean ownerView) {
        int gap = 10;
        int kpiCols = modernBankOverviewKpiColumns(width);
        int kpiH = modernBankOverviewKpiHeight(width);
        int kpiRows = (modernBankOverviewKpiCount(width) + kpiCols - 1) / kpiCols;
        int contentY = y + (kpiRows * (kpiH + gap)) + 6;
        boolean wide = modernBankOverviewUsesWidePanels(width);
        int reserveH = modernBankOverviewReservePanelHeight(width);
        int actionsH = modernBankOverviewQuickActionsHeight(width);
        int leftW = wide ? Math.max(300, ((width - gap) * 58) / 100) : width;
        int rightW = wide ? Math.max(220, width - leftW - gap) : width;
        if (wide && leftW + gap + rightW > width) {
            leftW = Math.max(260, width - gap - rightW);
        }
        int rightX = wide ? x + leftW + gap : x;
        int actionsX = wide ? rightX : x;
        int actionsY = wide ? contentY : contentY + reserveH + gap;
        int actionsW = wide ? rightW : width;
        int buttonX = actionsX + 14;
        int buttonW = Math.max(54, actionsW - 28);
        int buttonH = actionsW < 260 ? 22 : 24;
        int buttonGap = actionsW < 260 ? 8 : 10;
        int firstButtonY = actionsY + (actionsW < 260 ? 64 : 76);
        addModernBankContentButton(buttonX, firstButtonY, buttonW, buttonH, "Edit branding", ORDER_BOARD_CYAN,
                btn -> openModernBankModal(BankActionModal.BRANDING_MOTTO, ownerView));
        addModernBankContentButton(buttonX, firstButtonY + buttonH + buttonGap, buttonW, Math.max(24, buttonH), "Apply daily limit", 0xFF2F6BEE,
                btn -> openModernBankLimitModal("dailybank", data, ownerView));
        addModernBankContentButton(buttonX, firstButtonY + ((buttonH + buttonGap) * 2), buttonW, buttonH, "Submit compliance appeal", 0xFFE1A84E,
                btn -> openModernBankModal(BankActionModal.COMPLIANCE_APPEAL, ownerView));
        addModernBankActionButton(buttonX, firstButtonY + ((buttonH + buttonGap) * 3), buttonW,
                "Level roadmap", "BANK_LEVEL_ROADMAP", "", "", "", "", true);

        int lowerY = wide ? contentY + Math.max(reserveH, actionsH) + gap : actionsY + actionsH + gap;
        int tableY = lowerY;
        int lendingX = wide ? rightX : x;
        int lendingY = wide ? lowerY : tableY + 230;
        int lendingW = wide ? rightW : width;
        int lendingH = modernBankOverviewLendingHeight(width, wide);
        int lendingFooterY = lendingY + lendingH - (lendingW < 280 ? 32 : 52);
        addModernBankContentButton(lendingX + 16, lendingFooterY, Math.max(54, lendingW - 32), 24,
                "Open lending workspace", ORDER_BOARD_CYAN, btn -> {
                    activeSection = Section.LENDING;
                    bankActionModal = BankActionModal.NONE;
                    sectionScroll = 0;
                    rebuildWidgets();
                });
    }

    private void initModernBankAccountsWidgets(OwnerPcBankDataPayload data, int x, int y, int width, boolean ownerView) {
        if (!accountProfileOpen || selectedAccountCard == null) {
            return;
        }
        AccountDetailSnapshot detail = parseSelectedAccountDetail();
        int cardY = y + modernBankTopSummaryHeight(width) + 18;
        int actionY = cardY + 52;
        int gap = 8;
        int buttonW = Math.max(74, Math.min(130, (width - 32 - (gap * 5)) / 6));
        int buttonX = x + 16;
        addModernBankContentButton(buttonX, actionY, buttonW, 24, "Back", 0xFF7895B4, btn -> {
            accountProfileOpen = false;
            selectedAccountTransaction = null;
            accountHistoryScroll = 0;
            sectionScroll = 0;
            rebuildWidgets();
        });
        addModernBankContentButton(buttonX + (buttonW + gap), actionY, buttonW, 24, "Refresh", ORDER_BOARD_CYAN, btn -> {
            requestSelectedAccountDetail(0);
        });
        addModernBankContentButton(buttonX + ((buttonW + gap) * 2), actionY, buttonW, 24, "Copy ID", ORDER_BOARD_VIOLET, btn -> copySelectedAccountId());
        addModernBankContentButton(buttonX + ((buttonW + gap) * 3), actionY, buttonW, 24,
                detail != null && detail.frozen() ? "Unfreeze" : "Freeze",
                detail != null && detail.frozen() ? 0xFF67BC86 : ORDER_BOARD_RED,
                btn -> {
                    if (!ownerView) {
                        ClientOwnerPcData.setToast(false, "Only bank owners can change account freeze state.");
                        return;
                    }
                    if (detail != null && detail.frozen()) {
                        sendOwnerPcAction("ACCOUNT_UNFREEZE", selectedAccountCard.id(), "", "", "");
                    } else {
                        formValues.putIfAbsent(ACCOUNT_FREEZE_REASON_KEY, "");
                        openModernBankModal(BankActionModal.ACCOUNT_FREEZE, ownerView);
                    }
                });
        addModernBankContentButton(buttonX + ((buttonW + gap) * 4), actionY, buttonW, 24,
                "Temp limit", ORDER_BOARD_GOLD, btn -> {
                    if (!ownerView) {
                        ClientOwnerPcData.setToast(false, "Only bank owners can set temporary account limits.");
                        return;
                    }
                    ensureAccountTempLimitDefaults();
                    openModernBankModal(BankActionModal.ACCOUNT_TEMP_LIMIT, ownerView);
                });
        addModernBankActionButton(buttonX + ((buttonW + gap) * 5), actionY, buttonW,
                "Safe box", "SAFE_BOX_ASSIGN", selectedAccountCard.id(), "", "", "", ownerView);

    }

    private void initModernBankSafeWidgets(OwnerPcBankDataPayload data, int x, int y, int width) {
        formValues.putIfAbsent("safe.assign.account", "");
        if (data != null) {
            formValues.putIfAbsent("safe.policy.mode", data.safePolicyMode());
            formValues.putIfAbsent("safe.policy.amount", data.safePolicyAmount());
            formValues.putIfAbsent("safe.policy.period", data.safeRentPeriodTicks());
            formValues.putIfAbsent("safe.policy.overdue", data.safeOverdueTicks());
        }
        int safeY = y + modernBankSafeSetupHeight(data, width) + 12;
        int gap = 10;
        int moduleY = safeY + modernBankSafeKpiBlockHeight(width) + 12;
        int mainY = moduleY + modernBankSafeModuleRailHeight(width) + 12;
        initModernSafeModuleTabs(x, moduleY, width);
        if (safePanelTab != SafePanelTab.DEPOSIT_BOXES) {
            switch (safePanelTab) {
                case ACCESS_LOGS -> initModernSafeAccessLogWidgets(data, x, mainY, width);
                case ALARMS -> initModernSafeAlarmWidgets(data, x, mainY, width);
                case VAULT_STORAGE -> initModernVaultStorageWidgets(data, x, mainY, width);
                case DEPOSIT_BOXES -> {
                }
            }
            return;
        }
        boolean wide = width >= 820;
        int sideW = wide ? Math.max(250, (width - gap) * 31 / 100) : width;
        int mapW = wide ? Math.max(300, width - sideW - gap) : width;
        int sideX = wide ? x + mapW + gap : x;
        int actionY = wide ? mainY : mainY + modernBankSafeMapHeight(width) + gap;
        int actionH = 196;
        int policyY = actionY + actionH + gap;

        int accountInputY = actionY + 78;
        addModernBankInput("safe.assign.account", sideX + 16, accountInputY, Math.max(80, sideW - 32), "Account UUID");
        addModernBankActionButton(sideX + 16, actionY + 108, Math.max(74, sideW - 32),
                "Assign Box", "SAFE_BOX_ASSIGN", "@safe.assign.account", "", "", "", data != null);
        addModernBankContentButton(sideX + 16, actionY + 138, Math.max(74, sideW - 32), 24,
                "Claim Safe Area", ORDER_BOARD_CYAN, btn -> startSafeAreaClaimToolAndClose());
        addModernBankContentButton(sideX + 16, actionY + 168, Math.max(74, sideW - 32), 24,
                "Refresh", 0xFF7895B4, btn -> requestBankData(activeBankId));

        addModernBankContentButton(sideX + 16, policyY + 138, Math.max(74, sideW - 32), 24,
                "Pricing Policy", ORDER_BOARD_GOLD, btn -> openModernSafePolicyModal(data));

        int lowerY = wide
                ? mainY + Math.max(modernBankSafeMapHeight(width), actionH + gap + modernBankSafePolicyHeight()) + gap
                : policyY + modernBankSafePolicyHeight() + gap;
        boolean lowerWide = width >= 760;
        int areaW = lowerWide ? Math.max(300, (width - gap) / 2) : width;
        int queueX = lowerWide ? x + areaW + gap : x;
        int queueY = lowerWide ? lowerY : lowerY + modernBankSafeAreaStatusHeight(width) + gap;
        int queueW = lowerWide ? width - areaW - gap : width;
        int rowY = queueY + 76;
        int buttonW = Math.max(58, Math.min(88, queueW / 4));
        List<String> locked = data == null ? List.of() : data.safeLockedQueue();
        for (int i = 0; i < Math.min(4, locked.size()); i++) {
            String[] fields = splitSafeRow(locked.get(i));
            String accountId = safeRowField(fields, 2, "");
            String boxNumber = safeRowField(fields, 0, "Safety box");
            int currentY = rowY + (i * 31);
            addModernBankContentButton(queueX + queueW - 16 - buttonW, currentY + 2, buttonW, 22,
                    "Seize", ORDER_BOARD_RED, btn -> {
                        formValues.put("safe.seize.account", accountId);
                        formValues.put("safe.seize.box", boxNumber);
                        openModernBankModal(BankActionModal.SAFE_SEIZE_CONFIRM, true);
                    });
        }

        int lowerH = lowerWide
                ? Math.max(modernBankSafeAreaStatusHeight(width), modernBankSafeLockedQueueHeight(width))
                : modernBankSafeAreaStatusHeight(width) + gap + modernBankSafeLockedQueueHeight(width);
        int roomsY = lowerY + lowerH + gap;
        addModernBankContentButton(x + 16, roomsY + 42, Math.min(172, Math.max(104, width - 32)), 24,
                "Claim Viewing Room", ORDER_BOARD_CYAN, btn -> startViewingRoomClaimToolAndClose());

        List<OwnerPcViewingRoomPayload> rooms = data == null ? List.of() : data.viewingRooms();
        int roomColumns = width >= 760 ? 2 : 1;
        int roomGap = 10;
        int roomCardW = roomColumns == 2 ? Math.max(220, (width - roomGap) / 2) : width;
        int roomCardY = roomsY + 82;
        for (int index = 0; index < rooms.size(); index++) {
            OwnerPcViewingRoomPayload room = rooms.get(index);
            int col = index % roomColumns;
            int row = index / roomColumns;
            int cardX = x + col * (roomCardW + roomGap);
            int cardY = roomCardY + row * (modernViewingRoomCardHeight() + roomGap);
            String nameKey = "viewing.room.name." + room.roomId();
            formValues.putIfAbsent(nameKey, room.name());

            int renameW = Math.max(54, Math.min(76, roomCardW / 4));
            addModernBankInput(nameKey, cardX + 12, cardY + 58,
                    Math.max(72, roomCardW - 36 - renameW), "Room name");
            addModernBankContentButton(cardX + roomCardW - 12 - renameW, cardY + 58,
                    renameW, 22, "Rename", ORDER_BOARD_VIOLET,
                    btn -> sendOwnerPcAction("VIEWING_ROOM_RENAME", room.roomId(),
                            formValues.getOrDefault(nameKey, room.name()), "", ""));

            int anchorGap = 6;
            int anchorW = Math.max(48, (roomCardW - 24 - anchorGap * 2) / 3);
            addModernBankContentButton(cardX + 12, cardY + 88, anchorW, 22,
                    room.customerAnchor().isBlank() ? "Customer" : "Customer *", ORDER_BOARD_CYAN,
                    btn -> startViewingRoomAnchorAndClose(room.roomId(), "CUSTOMER"));
            addModernBankContentButton(cardX + 12 + anchorW + anchorGap, cardY + 88, anchorW, 22,
                    room.tellerAnchor().isBlank() ? "Teller" : "Teller *", ORDER_BOARD_CYAN,
                    btn -> startViewingRoomAnchorAndClose(room.roomId(), "TELLER"));
            addModernBankContentButton(cardX + 12 + (anchorW + anchorGap) * 2, cardY + 88, anchorW, 22,
                    room.displayAnchor().isBlank() ? "Box" : "Box *", ORDER_BOARD_CYAN,
                    btn -> startViewingRoomAnchorAndClose(room.roomId(), "DISPLAY"));

            int actionW = Math.max(48, (roomCardW - 24 - anchorGap * 2) / 3);
            boolean suspended = room.status().startsWith("SUSPENDED");
            addModernBankContentButton(cardX + 12, cardY + 118, actionW, 22,
                    "Copy ID", 0xFF7895B4,
                    btn -> copyTextToClipboard(room.roomId(), "Viewing-room ID copied."));
            addModernBankContentButton(cardX + 12 + actionW + anchorGap, cardY + 118, actionW, 22,
                    suspended ? "Reactivate" : "Suspend", suspended ? ORDER_BOARD_GREEN : ORDER_BOARD_GOLD,
                    btn -> sendOwnerPcAction("VIEWING_ROOM_SUSPEND", room.roomId(),
                            String.valueOf(!suspended), "", ""));
            addModernBankContentButton(cardX + 12 + (actionW + anchorGap) * 2, cardY + 118, actionW, 22,
                    "Delete", ORDER_BOARD_RED,
                    btn -> sendOwnerPcAction("VIEWING_ROOM_DELETE", room.roomId(), "", "", ""));
        }
    }

    private void initModernSafeModuleTabs(int x, int y, int width) {
        int columns = width >= 560 ? 4 : 2;
        int gap = 8;
        int buttonW = Math.max(54, (width - 28 - gap * (columns - 1)) / columns);
        SafePanelTab[] tabs = SafePanelTab.values();
        for (int index = 0; index < tabs.length; index++) {
            SafePanelTab tab = tabs[index];
            int col = index % columns;
            int row = index / columns;
            int buttonX = x + 14 + col * (buttonW + gap);
            int buttonY = y + 11 + row * 30;
            addModernBankContentButton(buttonX, buttonY, buttonW, 22, tab.label,
                    tab == safePanelTab ? ORDER_BOARD_CYAN : 0xFF7895B4,
                    button -> {
                        safePanelTab = tab;
                        sectionScroll = 0;
                        rebuildWidgets();
                    });
        }
    }

