    private String normalizeModernBankLimitType(String type) {
        String selected = type == null ? "" : type.trim().toLowerCase(Locale.ROOT);
        return switch (selected) {
            case "single", "transaction", "singletransaction" -> "single";
            case "dailyplayer", "playerdaily" -> "dailyplayer";
            case "teller", "tellercash", "cash", "withdrawal" -> "teller";
            default -> "dailybank";
        };
    }

    private String modernBankLimitTypeLabel(String type) {
        String selected = normalizeModernBankLimitType(type);
        return switch (selected) {
            case "single" -> "Single";
            case "dailyplayer" -> "Daily Player";
            case "teller" -> "Teller Cash";
            default -> "Daily Bank";
        };
    }

    private String modernBankCurrentLimitAmount(OwnerPcBankDataPayload data, String type) {
        String selected = normalizeModernBankLimitType(type);
        if (data == null) {
            return "";
        }
        return switch (selected) {
            case "single" -> data.singleLimit();
            case "dailyplayer" -> data.dailyPlayerLimit();
            case "teller" -> data.tellerLimit();
            default -> data.dailyBankLimit();
        };
    }

    private String modernBankLimitValue(String amount) {
        return amount == null || amount.isBlank() ? "Unset" : "$" + compactCurrency(amount);
    }

    private String modernBankLimitStatus(String amount, String configuredText, String unsetText) {
        return amount == null || amount.isBlank() ? unsetText : configuredText;
    }

    private void submitModernBankModalAction(String action, String arg1, String arg2, String arg3, String arg4) {
        sendOwnerPcAction(
                action,
                resolveArg(arg1),
                resolveArg(arg2),
                resolveArg(arg3),
                resolveArg(arg4)
        );
        bankActionModal = BankActionModal.NONE;
        outputScroll = 0;
        rebuildWidgets();
    }

    private DesktopButton addModernBankActionButton(int x,
                                                    int y,
                                                    int width,
                                                    String label,
                                                    String action,
                                                    String arg1,
                                                    String arg2,
                                                    String arg3,
                                                    String arg4,
                                                    boolean active) {
        int renderY = y - sectionScroll;
        DesktopButton button = addActionButton(x, renderY, width, label, action, arg1, arg2, arg3, arg4, active);
        boolean visible = renderY >= sectionViewportY && (renderY + 24) <= (sectionViewportY + sectionViewportH);
        button.visible = visible;
        button.active = visible && active;
        return button;
    }

    private DesktopEditBox addModernBankInput(String key, int x, int y, int width, String placeholder) {
        int renderY = y - sectionScroll;
        DesktopEditBox input = addFormInput(key, x, renderY, width, placeholder);
        boolean visible = renderY >= sectionViewportY && (renderY + 20) <= (sectionViewportY + sectionViewportH);
        input.visible = visible;
        input.active = visible;
        return input;
    }

    private void addModernBankLimitSelectors(int x, int y, int width) {
        String selected = formValues.getOrDefault("limits.type", "dailybank").toLowerCase(Locale.ROOT);
        if (!List.of("single", "dailyplayer", "dailybank", "teller").contains(selected)) {
            selected = "dailybank";
            formValues.put("limits.type", selected);
        } else {
            formValues.putIfAbsent("limits.type", selected);
        }
        String[] types = {"single", "dailyplayer", "dailybank", "teller"};
        String[] labels = {"Single", "Daily Player", "Daily Bank", "Teller Cash"};
        int gap = 8;
        int buttonW = Math.max(74, (width - (gap * 3)) / 4);
        for (int i = 0; i < types.length; i++) {
            String type = types[i];
            DesktopButton button = addModernBankContentButton(
                    x + (i * (buttonW + gap)),
                    y,
                    buttonW,
                    22,
                    selected.equals(type) ? labels[i] + " *" : labels[i],
                    selected.equals(type) ? ORDER_BOARD_CYAN : 0xFF7895B4,
                    btn -> {
                        formValues.put("limits.type", type);
                        rebuildWidgets();
                    }
            );
            button.active = button.visible && !selected.equals(type);
        }
    }

