                        addSectionActionButton(innerX, curY, btnW, "Role List", "SHOW_ROLES", "", "", "", "", true);
                        addSectionActionButton(innerX + btnW + gap, curY, btnW, "Add Cofounder", "COFOUNDER_ADD", "@gov.player", "", "", "", ownerView);
                        curY += 32;
