    private void initShopOrderCreateModalWidgets() {
        RectHitbox modal = getShopOrderCreateModalBounds();
        int modalX = modal.x();
        int modalY = modal.y();
        int modalW = modal.width();
        int innerX = modalX + 16;
        int innerW = Math.max(120, modalW - 32);
        int gap = 8;
        int fieldY = modalY + 116;
        int fieldW = Math.max(70, (innerW - (gap * 2)) / 3);
        addFormInput("shop.order.qty", innerX, fieldY, fieldW, "Quantity");
        addFormInput("shop.order.reward", innerX + fieldW + gap, fieldY, fieldW, "Reward $");
        addFormInput("shop.order.timeout", innerX + ((fieldW + gap) * 2), fieldY, fieldW, "Timeout min");

        int modeY = fieldY + 44;
        int half = Math.max(90, (innerW - gap) / 2);
        DesktopButton random = addPcButton(innerX, modeY, half, 22,
                shopOrderUseSpecificPallet ? "Use random pallet" : "Random pallet active",
                ORDER_BOARD_CYAN,
                btn -> {
                    shopOrderUseSpecificPallet = false;
                    rebuildWidgets();
                }).setLabelOffset(6, 1);
        random.active = shopOrderUseSpecificPallet;
        DesktopButton specific = addPcButton(innerX + half + gap, modeY, half, 22,
                shopOrderUseSpecificPallet ? "Specific pallet active" : "Use specific pallet",
                ORDER_BOARD_GREEN,
                btn -> {
                    shopOrderUseSpecificPallet = true;
                    rebuildWidgets();
                }).setLabelOffset(6, 1);
        specific.active = !shopOrderUseSpecificPallet || shopOrderSelectedPalletRef == null || shopOrderSelectedPalletRef.isBlank();

        int pickerY = modeY + 34;
        addPcButton(innerX, pickerY, half, 22, "Pick shelf item",
                ORDER_BOARD_CYAN,
                btn -> openShopOrderItemPickerFromShelves()).setLabelOffset(6, 1);
        addPcButton(innerX + half + gap, pickerY, half, 22, "Select pallet",
                ORDER_BOARD_GREEN,
                btn -> openShopOrderPalletPicker()).setLabelOffset(6, 1);

        int buttonY = modalY + modal.height() - 38;
        int actionW = Math.max(90, (innerW - gap) / 2);
        addPcButton(innerX, buttonY, actionW, 22, "Create order",
                ORDER_BOARD_GOLD,
                btn -> submitShopOrderCreate()).setLabelOffset(6, 1);
        addPcButton(innerX + actionW + gap, buttonY, actionW, 22, "Cancel",
                0xFF8CAAC6,
                btn -> closeShopOrderCreateModal()).setLabelOffset(6, 1);
    }

    private void initShopEmployeeDetailModalWidgets() {
        ShopEmployeeCardData employee = selectedShopEmployeeModal;
        if (employee == null) {
            return;
        }
        RectHitbox modal = getShopEmployeeModalBounds();
        int innerX = modal.x() + 16;
        int innerW = Math.max(120, modal.width() - 32);
        int gap = 8;
        int buttonY = modal.y() + modal.height() - 66;
        int cols = innerW >= 420 ? 3 : 2;
        int buttonW = Math.max(82, (innerW - (gap * (cols - 1))) / cols);

        addPcButton(innerX, buttonY, buttonW, 22, "Copy ID", ORDER_BOARD_CYAN, btn -> {
            Minecraft mc = this.minecraft != null ? this.minecraft : Minecraft.getInstance();
            if (mc != null && mc.keyboardHandler != null) {
                mc.keyboardHandler.setClipboard(employee.employeeId());
            }
            ClientOwnerPcData.setToast(true, "Copied employee ID " + employee.employeeId() + ".");
        }).setLabelOffset(6, 1);
        addPcButton(innerX + buttonW + gap, buttonY, buttonW, 22, "Link terminal", ORDER_BOARD_GREEN,
                btn -> startShopCashierLinkAndClose()).setLabelOffset(6, 1);
        int scanX = cols >= 3 ? innerX + ((buttonW + gap) * 2) : innerX;
        int scanY = cols >= 3 ? buttonY : buttonY + 32;
        addPcButton(scanX, scanY, buttonW, 22, "Scan cashiers", ORDER_BOARD_CYAN,
                btn -> sendShopDesktopAction("SHOP_SCAN_CASHIERS", "")).setLabelOffset(6, 1);

        int bottomY = buttonY + (cols >= 3 ? 32 : 64);
        int half = Math.max(90, (innerW - gap) / 2);
        addPcButton(innerX, bottomY, half, 22, "Fire cashier", ORDER_BOARD_RED, btn -> {
            sendShopDesktopAction("SHOP_FIRE_EMPLOYEE", employee.employeeId());
            ClientOwnerPcData.setToast(true, "Firing employee " + employee.employeeId() + "...");
            selectedShopEmployeeModal = null;
        }).setLabelOffset(6, 1);
        addPcButton(innerX + half + gap, bottomY, half, 22, "Close", 0xFF8CAAC6,
                btn -> closeShopEmployeeDetailModal()).setLabelOffset(6, 1);
    }

    private void initShopFinanceModalWidgets() {
        if (!isShopFinanceModalOverlayActive()) {
            return;
        }
        RectHitbox modal = getShopFinanceModalBounds();
        int innerX = modal.x() + 16;
        int innerW = Math.max(120, modal.width() - 32);
        int gap = 8;
        int buttonY = modal.y() + modal.height() - 34;
        if (shopSettlementPickerOpen) {
            int third = Math.max(80, (innerW - (gap * 2)) / 3);
            addPcButton(innerX, buttonY, third, 22, "Apply settlement", ORDER_BOARD_GREEN,
                    btn -> applyShopSettlementSelection()).setLabelOffset(6, 1);
            addPcButton(innerX + third + gap, buttonY, third, 22, "Refresh accounts", ORDER_BOARD_CYAN,
                    btn -> sendShopDesktopAction("SHOP_LIST_OWNER_ACCOUNTS", "")).setLabelOffset(6, 1);
            addPcButton(innerX + ((third + gap) * 2), buttonY, third, 22, "Close", 0xFF8CAAC6,
                    btn -> closeShopSettlementPicker()).setLabelOffset(6, 1);
            return;
        }
        if (shopVaultPlanEditOpen) {
            int buttonW = Math.max(82, (innerW - (gap * 2)) / 3);
            addPcButton(innerX, buttonY, buttonW, 22, "Withdraw selected", ORDER_BOARD_GOLD,
                    btn -> applyShopVaultPlanWithdrawal()).setLabelOffset(6, 1);
            addPcButton(innerX + buttonW + gap, buttonY, buttonW, 22, "Reset plan", ORDER_BOARD_CYAN,
                    btn -> {
                        java.util.Arrays.fill(shopVaultRequestedCounts, 0);
                        rebuildWidgets();
                    }).setLabelOffset(6, 1);
            addPcButton(innerX + ((buttonW + gap) * 2), buttonY, buttonW, 22, "Close", 0xFF8CAAC6,
                    btn -> {
                        shopVaultPlanEditOpen = false;
                        sendShopDesktopAction("SHOP_FINANCE_REPORT", "");
                        rebuildWidgets();
                    }).setLabelOffset(6, 1);
        }
    }

