        addPcButton(innerX, bottomY, half, 22, "Apply " + friendlyShopHoursDay(shopHoursModalDay), 0xFF22C55E,
                btn -> {
                    sendShopDesktopAction("SHOP_HOURS_SET",
                            normalizeShopHoursDayKey(shopHoursModalDay)
                                    + "|"
                                    + formValues.getOrDefault(SHOP_HOURS_OPEN_KEY, "").trim()
                                    + "|"
                                    + formValues.getOrDefault(SHOP_HOURS_CLOSE_KEY, "").trim());
                    shopHoursModalDay = "";
                }).setLabelOffset(6, 1);
