    private void initShopPermissionModalWidgets() {
        ShopPermissionMemberCardData player = selectedShopPermissionModal;
        if (player == null) {
            return;
        }
        RectHitbox modal = getShopPermissionModalBounds();
        int innerX = modal.x() + 16;
        int innerW = Math.max(120, modal.width() - 32);
        int gap = 8;
        String selectedRole = formValues.getOrDefault(SHOP_PERMISSIONS_ROLE_KEY, ShopService.SHOP_ROLE_MANAGER)
                .trim()
                .toUpperCase(Locale.ROOT);
        if (!ShopService.SHOP_PERMISSION_ROLES.contains(selectedRole)) {
            selectedRole = ShopService.SHOP_ROLE_MANAGER;
            formValues.put(SHOP_PERMISSIONS_ROLE_KEY, selectedRole);
        }
        int roleY = modal.y() + 142;
        int roleCols = innerW >= 420 ? 4 : 2;
        int roleW = Math.max(68, (innerW - (gap * (roleCols - 1))) / roleCols);
        for (int i = 0; i < ShopService.SHOP_PERMISSION_ROLES.size(); i++) {
            String role = ShopService.SHOP_PERMISSION_ROLES.get(i);
            int col = i % roleCols;
            int row = i / roleCols;
            DesktopButton roleButton = addPcButton(innerX + (col * (roleW + gap)),
                    roleY + (row * 30),
                    roleW,
                    22,
                    selectedRole.equals(role) ? role + " *" : role,
                    ORDER_BOARD_CYAN,
                    btn -> {
                        formValues.put(SHOP_PERMISSIONS_ROLE_KEY, role);
                        rebuildWidgets();
                    }).setLabelOffset(5, 1);
            roleButton.active = !selectedRole.equals(role);
        }
        int buttonY = modal.y() + modal.height() - 34;
        int third = Math.max(82, (innerW - (gap * 2)) / 3);
        addPcButton(innerX, buttonY, third, 22, "Grant / update", 0xFF22C55E, btn -> {
            String playerId = player.playerId() == null ? "" : player.playerId().trim();
            if (playerId.isBlank()) {
                ClientOwnerPcData.setToast(false, "Selected player has no UUID.");
                return;
            }
            sendShopDesktopAction("SHOP_PERMISSIONS_SET",
                    playerId + "|" + formValues.getOrDefault(SHOP_PERMISSIONS_ROLE_KEY, ShopService.SHOP_ROLE_MANAGER));
            selectedShopPermissionModal = null;
        }).setLabelOffset(6, 1);
        DesktopButton removeButton = addPcButton(innerX + third + gap, buttonY, third, 22, "Remove role", ORDER_BOARD_RED, btn -> {
            String playerId = player.playerId() == null ? "" : player.playerId().trim();
            if (playerId.isBlank()) {
                ClientOwnerPcData.setToast(false, "Selected player has no UUID.");
                return;
            }
            sendShopDesktopAction("SHOP_PERMISSIONS_REMOVE", playerId);
            selectedShopPermissionModal = null;
        }).setLabelOffset(6, 1);
        removeButton.active = !player.owner();
        addPcButton(innerX + ((third + gap) * 2), buttonY, third, 22, "Close", 0xFF8CAAC6,
                btn -> {
                    selectedShopPermissionModal = null;
                    rebuildWidgets();
                }).setLabelOffset(6, 1);
    }

    private void initShopDeleteModalWidgets() {
        if (!isShopDeleteModalOverlayActive()) {
            return;
        }
        RectHitbox modal = getShopDeleteModalBounds();
        int innerX = modal.x() + 16;
        int innerW = Math.max(120, modal.width() - 32);
        int inputY = modal.y() + 118;
        addFormInput("shop.settings.delete_confirm", innerX, inputY, innerW, "Type shop name to confirm");
        int buttonY = modal.y() + modal.height() - 34;
        int gap = 8;
        int half = Math.max(90, (innerW - gap) / 2);
        addPcButton(innerX, buttonY, half, 22, "Delete shop", ORDER_BOARD_RED, btn -> {
            String confirm = formValues.getOrDefault("shop.settings.delete_confirm", "").trim();
            if (confirm.isBlank()) {
                ClientOwnerPcData.setToast(false, "Type the current shop name before deleting.");
                return;
            }
            sendShopDesktopAction("SHOP_DELETE", confirm);
        }).setLabelOffset(6, 1);
        addPcButton(innerX + half + gap, buttonY, half, 22, "Cancel", 0xFF8CAAC6,
                btn -> {
                    shopDeleteModalOpen = false;
                    rebuildWidgets();
                }).setLabelOffset(6, 1);
    }

    private int getShopBusinessModalHeight() {
        if (!isShopBusinessActionModalOpen()) {
            return 0;
        }
        return switch (shopBusinessActionModal) {
            case PUBLISH_FRANCHISE_OFFER -> 238;
            case FRANCHISE_REQUIRED_ITEMS -> Math.max(260, Math.min(430, this.height - 70));
            case ACCEPT_FRANCHISE_OFFER, CANCEL_FRANCHISE_OFFER, CORPORATE_BRANCH -> 132;
            case FRANCHISE_MARKET_OFFER -> Math.max(340, Math.min(420, this.height - 60));
            case FRANCHISE_REQUIREMENTS_LIST -> Math.max(300, Math.min(460, this.height - 60));
            case FRANCHISE_CONTRACT_DATE -> Math.max(318, Math.min(390, this.height - 60));
            case PAY_SHOP_TYPE_FEES -> 118;
            case NONE -> 0;
        };
    }

    private RectHitbox getShopBusinessModalBounds() {
        int maxW = shopBusinessActionModal == ShopBusinessActionModal.FRANCHISE_REQUIREMENTS_LIST
                || shopBusinessActionModal == ShopBusinessActionModal.FRANCHISE_CONTRACT_DATE
                ? 560
                : 500;
        int modalW = Math.max(230, Math.min(maxW, this.width - 64));
        int modalH = getShopBusinessModalHeight();
        int modalX = Math.max(8, (this.width - modalW) / 2);
        int modalY = Math.max(8, (this.height - modalH) / 2);
        return new RectHitbox(modalX, modalY, modalW, modalH);
    }

    private int addShopTypeSelectors(int x, int y, int width) {
        String selected = formValues.getOrDefault("shop.settings.type", SHOP_TYPES.get(0)).toUpperCase(Locale.ROOT);
        if (!SHOP_TYPES.contains(selected)) {
            selected = SHOP_TYPES.get(0);
            formValues.put("shop.settings.type", selected);
        } else {
            formValues.putIfAbsent("shop.settings.type", selected);
        }

        int bottom;
        if (width < 420) {
            int currentY = y;
            for (String type : SHOP_TYPES) {
                String label = prettifyShopType(type);
                DesktopButton button = addSectionPcButton(
                        x,
                        currentY,
                        width,
                        24,
                        (selected.equals(type) ? "Selected: " : "") + label,
                        btn -> {
                            formValues.put("shop.settings.type", type);
                            rebuildWidgets();
                        }
                );
                button.active = !selected.equals(type);
                currentY += 30;
            }
            bottom = currentY;
        } else {
            int gap = 8;
            int buttonW = (width - (gap * 2)) / 3;
            int currentX = x;
            for (String type : SHOP_TYPES) {
                String label = prettifyShopType(type);
                DesktopButton button = addSectionPcButton(
                        currentX,
                        y,
                        buttonW,
                        24,
                        (selected.equals(type) ? "Selected: " : "") + label,
                        btn -> {
                            formValues.put("shop.settings.type", type);
                            rebuildWidgets();
                        }
                );
                button.active = !selected.equals(type);
                currentX += buttonW + gap;
            }
            bottom = y + 24;
        }
        return bottom;
    }

    private int addLimitTypeSelectors(int x, int y, int width) {
        String selected = formValues.getOrDefault("limits.type", "single").toLowerCase(Locale.ROOT);
        if (!List.of("single", "dailyplayer", "dailybank", "teller").contains(selected)) {
            selected = "single";
            formValues.put("limits.type", selected);
        } else {
            formValues.putIfAbsent("limits.type", selected);
        }

        String[] types = {"single", "dailyplayer", "dailybank", "teller"};
        String[] labels = {"Single", "Daily Player", "Daily Bank", "Teller Cash"};

        int rowBottom;
        if (width < 390) {
            int currentY = y;
            for (int i = 0; i < types.length; i++) {
                String type = types[i];
                DesktopButton button = addSectionPcButton(
                        x,
                        currentY,
                        width,
                        24,
                        (selected.equals(type) ? "Selected: " : "") + labels[i],
                        btn -> {
                            formValues.put("limits.type", type);
                            rebuildWidgets();
                        }
                ).setLabelOffset(6, 1);
                button.active = button.visible && !selected.equals(type);
                currentY += 28;
            }
            rowBottom = currentY;
        } else {
            int gap = 8;
            int buttonW = (width - (gap * 3)) / 4;
            for (int i = 0; i < types.length; i++) {
                String type = types[i];
                DesktopButton button = addSectionPcButton(
                        x + (i * (buttonW + gap)),
                        y,
                        buttonW,
                        24,
                        (selected.equals(type) ? "Selected: " : "") + labels[i],
                        btn -> {
                            formValues.put("limits.type", type);
                            rebuildWidgets();
                        }
                ).setLabelOffset(6, 1);
                button.active = button.visible && !selected.equals(type);
            }
            rowBottom = y + 28;
        }
        return rowBottom;
    }

    private DesktopEditBox addFormInput(String key, int x, int y, int width, String placeholder) {
        String translatedPlaceholder = tr(placeholder == null ? "" : placeholder);
        DesktopEditBox input = new DesktopEditBox(this.font, x, y, width, 20, Component.literal(translatedPlaceholder));
        input.setValue(formValues.getOrDefault(key, ""));
        input.setResponder(value -> formValues.put(key, value == null ? "" : value));
        input.setHint(Component.literal(translatedPlaceholder));
        input.setTextColor(0xFFFFFFFF);
        input.setTextColorUneditable(0xFFCFD8E3);
        DesktopEditBox widget = addRenderableWidget(input);
        activeFormInputs.put(key, widget);
        return widget;
    }

