                paintSaveModalOpen = false;
                paintDrawing = false;
                paintSavedSnapshotHash = Arrays.hashCode(paintPixels);
                paintControlsScroll = 0;
                paintControlsMaxScroll = 0;
                paintControlsX = 0;
                paintControlsY = 0;
                paintControlsW = 0;
