    private boolean tryHandleShopBusinessActionClick(double mouseX, double mouseY) {
        if (shopBusinessActionModal == ShopBusinessActionModal.FRANCHISE_REQUIRED_ITEMS) {
            for (FranchiseRequirementCardHitbox hitbox : visibleFranchiseRequirementCards) {
                if (!hitbox.contains(mouseX, mouseY)) {
                    continue;
                }
                handleFranchiseRequirementCardAction(hitbox);
                return true;
            }
        }
        for (ShopBusinessActionHitbox actionHitbox : visibleShopBusinessActions) {
            if (!actionHitbox.contains(mouseX, mouseY)) {
                continue;
            }
            if (!actionHitbox.enabled()) {
                showShopBusinessDisabledFeedback(actionHitbox);
                return true;
            }
            handleShopBusinessAction(actionHitbox.action());
            return true;
        }
        return false;
    }

    private void handleShopBusinessAction(String action) {
        String rawAction = action == null ? "" : action.trim();
        String normalized = rawAction.toUpperCase(Locale.ROOT);
        if (normalized.startsWith("OFFER_DETAILS:")) {
            shopBusinessSelectedOfferId = rawAction.substring("OFFER_DETAILS:".length()).trim();
            formValues.put("shop.franchise.offer_id", shopBusinessSelectedOfferId);
            shopBusinessActionModal = ShopBusinessActionModal.FRANCHISE_MARKET_OFFER;
            rebuildWidgets();
            return;
        }
        if (normalized.startsWith("CONTRACT_DATE_DAY:")) {
            selectFranchiseContractEndDate(rawAction.substring("CONTRACT_DATE_DAY:".length()).trim());
            rebuildWidgets();
            return;
        }
        if (normalized.startsWith("CONTRACT_DATE_QUICK:")) {
            int days = Math.max(1, parseIntMetricToken(rawAction.substring("CONTRACT_DATE_QUICK:".length()).trim()));
            setFranchiseContractEndDate(LocalDate.now().plusDays(days));
            rebuildWidgets();
            return;
        }
        switch (normalized) {
            case "REFRESH_TYPE" -> sendShopDesktopAction("SHOP_TYPE_REPORT", "");
            case "PAY_FEES", "PAY_FEES_MODAL" -> {
                ShopBusinessSnapshot snapshot = parseShopBusinessSnapshot(ClientOwnerPcData.getActionOutputLines());
                if (snapshot.payableCents() <= 0L) {
                    showShopBusinessDisabledFeedback("No shop-type fees are due right now.");
                    return;
                }
                shopBusinessActionModal = ShopBusinessActionModal.PAY_SHOP_TYPE_FEES;
                rebuildWidgets();
            }
            case "CHANGE_TYPE" -> {
                activeSection = Section.COMPLIANCE;
                outputScroll = 0;
                sectionScroll = 0;
                shopBusinessActionModal = ShopBusinessActionModal.NONE;
                sendShopDesktopAction(defaultShopActionForSection(activeSection), "");
                rebuildWidgets();
            }
            case "PUBLISH_MODAL" -> {
                shopBusinessActionModal = ShopBusinessActionModal.PUBLISH_FRANCHISE_OFFER;
                rebuildWidgets();
            }
            case "REQUIRED_ITEMS_MODAL" -> {
                shopBusinessActionModal = ShopBusinessActionModal.FRANCHISE_REQUIRED_ITEMS;
                franchiseRequirementScroll = 0;
                rebuildWidgets();
            }
            case "CONTRACT_DATE_MODAL" -> {
                ensureFranchiseContractDateDefaults();
                setFranchiseContractCalendarMonth(YearMonth.from(getFranchiseContractEndDateOrDefault()));
                shopBusinessActionModal = ShopBusinessActionModal.FRANCHISE_CONTRACT_DATE;
                rebuildWidgets();
            }
            case "CONTRACT_DATE_PREV_MONTH" -> {
                setFranchiseContractCalendarMonth(getFranchiseContractCalendarMonth().minusMonths(1));
                rebuildWidgets();
            }
            case "CONTRACT_DATE_NEXT_MONTH" -> {
                setFranchiseContractCalendarMonth(getFranchiseContractCalendarMonth().plusMonths(1));
                rebuildWidgets();
            }
            case "CONTRACT_DATE_CLEAR" -> {
                formValues.put(SHOP_FRANCHISE_CONTRACT_EXPIRES_KEY, "0");
                rebuildWidgets();
            }
            case "CONTRACT_DATE_SAVE", "CONTRACT_DATE_BACK" -> {
                shopBusinessActionModal = ShopBusinessActionModal.PUBLISH_FRANCHISE_OFFER;
                rebuildWidgets();
            }
            case "REQ_MODE_INVENTORY" -> {
                franchiseRequirementPickerMode = FranchiseRequirementPickerMode.INVENTORY;
                franchiseRequirementScroll = 0;
                rebuildWidgets();
            }
            case "REQ_MODE_SEARCH" -> {
                franchiseRequirementPickerMode = FranchiseRequirementPickerMode.SEARCH;
                franchiseRequirementScroll = 0;
                rebuildWidgets();
            }
            case "REQUIRED_ITEMS_DONE", "REQUIRED_ITEMS_BACK" -> {
                shopBusinessActionModal = ShopBusinessActionModal.PUBLISH_FRANCHISE_OFFER;
                rebuildWidgets();
            }
            case "SHOW_SELECTED_REQUIREMENTS" -> {
                ShopBusinessSnapshot snapshot = parseShopBusinessSnapshot(ClientOwnerPcData.getActionOutputLines());
                ShopFranchiseOfferData offer = selectedFranchiseOffer(snapshot);
                if (offer == null || offer.requirements().isEmpty()) {
                    showShopBusinessDisabledFeedback("This offer has no brand-required shelf items.");
                    return;
                }
                shopBusinessActionModal = ShopBusinessActionModal.FRANCHISE_REQUIREMENTS_LIST;
                franchiseRequirementDetailScroll = 0;
                rebuildWidgets();
            }
            case "REQUIREMENTS_LIST_BACK" -> {
                shopBusinessActionModal = ShopBusinessActionModal.FRANCHISE_MARKET_OFFER;
                rebuildWidgets();
            }
            case "ACCEPT_MODAL" -> {
                shopBusinessActionModal = ShopBusinessActionModal.ACCEPT_FRANCHISE_OFFER;
                rebuildWidgets();
            }
            case "CANCEL_MODAL" -> {
                shopBusinessActionModal = ShopBusinessActionModal.CANCEL_FRANCHISE_OFFER;
                rebuildWidgets();
            }
            case "BRANCH_MODAL" -> {
                shopBusinessActionModal = ShopBusinessActionModal.CORPORATE_BRANCH;
                rebuildWidgets();
            }
            case "PUBLISH_CONFIRM" -> {
                shopBusinessActionModal = ShopBusinessActionModal.NONE;
                sendShopDesktopAction(
                        "SHOP_FRANCHISE_PUBLISH_OFFER",
                        String.join("|",
                                formValues.getOrDefault("shop.franchise.brand", "").trim(),
                                formValues.getOrDefault("shop.franchise.upfront", "").trim(),
                                formValues.getOrDefault("shop.franchise.royalty", "").trim(),
                                formValues.getOrDefault("shop.franchise.marketing", "").trim(),
                                formValues.getOrDefault("shop.franchise.rules", "").trim(),
                                formValues.getOrDefault("shop.franchise.direct", "").trim(),
                                formValues.getOrDefault(SHOP_FRANCHISE_CONTRACT_EXPIRES_KEY, "0").trim()
                        ),
                        encodeFranchiseRequirementDrafts()
                );
                franchiseRequirementScroll = 0;
                rebuildWidgets();
            }
            case "ACCEPT_CONFIRM" -> {
                shopBusinessActionModal = ShopBusinessActionModal.NONE;
                sendShopDesktopAction("SHOP_FRANCHISE_ACCEPT_OFFER",
                        formValues.getOrDefault("shop.franchise.offer_id", "").trim());
                rebuildWidgets();
            }
            case "ACCEPT_SELECTED_OFFER" -> {
                String offerId = shopBusinessSelectedOfferId == null ? "" : shopBusinessSelectedOfferId.trim();
                if (offerId.isBlank()) {
                    ClientOwnerPcData.setToast(false, "Select a franchise offer first.");
                    return;
                }
                shopBusinessActionModal = ShopBusinessActionModal.NONE;
                formValues.put("shop.franchise.offer_id", offerId);
                sendShopDesktopAction("SHOP_FRANCHISE_ACCEPT_OFFER", offerId);
                shopBusinessSelectedOfferId = "";
                rebuildWidgets();
            }
            case "COPY_SELECTED_OFFER_ID" -> {
                String offerId = shopBusinessSelectedOfferId == null ? "" : shopBusinessSelectedOfferId.trim();
                if (offerId.isBlank()) {
                    ClientOwnerPcData.setToast(false, "No franchise offer ID is selected.");
                    return;
                }
                Minecraft mc = this.minecraft != null ? this.minecraft : Minecraft.getInstance();
                if (mc != null && mc.keyboardHandler != null) {
                    mc.keyboardHandler.setClipboard(offerId);
                }
                ClientOwnerPcData.setToast(true, "Copied offer ID " + shortUuid(offerId) + ".");
            }
            case "CANCEL_OFFER_CONFIRM" -> {
                shopBusinessActionModal = ShopBusinessActionModal.NONE;
                sendShopDesktopAction("SHOP_FRANCHISE_CANCEL_OFFER",
                        formValues.getOrDefault("shop.franchise.offer_id", "").trim());
                rebuildWidgets();
            }
            case "PAY_FEES_CONFIRM" -> {
                shopBusinessActionModal = ShopBusinessActionModal.NONE;
                sendShopDesktopAction("SHOP_TYPE_PAY_FEES", "");
                rebuildWidgets();
            }
            case "CORPORATE_ADD_CONFIRM" -> {
                shopBusinessActionModal = ShopBusinessActionModal.NONE;
                sendShopDesktopAction("SHOP_CORPORATE_ADD_BRANCH",
                        formValues.getOrDefault("shop.corporate.branch_id", "").trim());
                rebuildWidgets();
            }
            case "CORPORATE_REMOVE_CONFIRM" -> {
                shopBusinessActionModal = ShopBusinessActionModal.NONE;
                sendShopDesktopAction("SHOP_CORPORATE_REMOVE_BRANCH",
                        formValues.getOrDefault("shop.corporate.branch_id", "").trim());
                rebuildWidgets();
            }
            case "MODAL_CLOSE" -> {
                shopBusinessActionModal = ShopBusinessActionModal.NONE;
                shopBusinessSelectedOfferId = "";
                rebuildWidgets();
            }
            default -> {
            }
        }
    }

