    private void cycleShopLightingMode(String formKey, String action) {
        String[] modes = {"ON", "OFF", "OPEN_HOURS", "INVERTED"};
        String current = formValues.getOrDefault(formKey, "OPEN_HOURS").trim().toUpperCase(Locale.ROOT);
        int index = 2;
        for (int i = 0; i < modes.length; i++) {
            if (modes[i].equals(current)) {
                index = i;
                break;
            }
        }
        String next = modes[(index + 1) % modes.length];
        formValues.put(formKey, next);
        sendShopDesktopAction(action, next);
        rebuildWidgets();
    }

    private String formatShopInventoryFilterMode(ShopInventoryFilterMode mode) {
        if (mode == null) {
            return "All";
        }
        return switch (mode) {
            case ALL -> "All";
            case LOW_STOCK -> "Low Stock";
            case OUT_OF_STOCK -> "Out of Stock";
        };
    }

    private String formatShopInventorySortMode(ShopInventorySortMode mode) {
        if (mode == null) {
            return "Shelf";
        }
        return switch (mode) {
            case SHELF_SLOT -> "Shelf";
            case STOCK_ASC -> "Stock Asc";
            case STOCK_DESC -> "Stock Desc";
            case VELOCITY_DESC -> "Velocity";
            case NAME_ASC -> "Name";
        };
    }

