    private void applyForcedGuiScale() {
        // The PC app must follow the player's Minecraft GUI scale. Older builds
        // forced scale 2 here, which made small-screen layouts diverge from the
        // rest of the client and cut off responsive panels.
        restoreForcedGuiScale();
    }

    private void restoreForcedGuiScale() {
        if (!forcedGuiScaleActive) {
            return;
        }
        Minecraft mc = this.minecraft != null ? this.minecraft : Minecraft.getInstance();
        if (mc != null && mc.options != null && mc.options.guiScale() != null && previousGuiScale != null) {
            Integer current = mc.options.guiScale().get();
            if (current == null || !current.equals(previousGuiScale)) {
                mc.options.guiScale().set(previousGuiScale);
                mc.resizeDisplay();
            }
        }
        forcedGuiScaleActive = false;
        previousGuiScale = null;
    }

    @Override
    public void render(GuiGraphics graphics, int mouseX, int mouseY, float partialTicks) {
        applyForcedGuiScale();
        if (configureVirtualScale()) {
            rebuildWidgets();
        }
        applyPendingFormInputFocus();

        int localMouseX = (int) toLocalX(mouseX);
        int localMouseY = (int) toLocalY(mouseY);
        visibleScrollbars.clear();
        if (useVirtualScale) {
            graphics.pose().pushPose();
            graphics.pose().scale(virtualScaleX, virtualScaleY, 1.0F);
        }
        for (int y = 0; y < this.height; y++) {
            float ratio = (float) y / (float) Math.max(1, this.height - 1);
            int row = lerpColor(ORDER_BOARD_BG, ORDER_BOARD_ROW, ratio);
            graphics.fill(0, y, this.width, y + 1, row);
        }

        for (int y = 0; y < this.height; y += 24) {
            graphics.fill(0, y, this.width, y + 1, 0x241F4668);
        }
        for (int x = 0; x < this.width; x += 24) {
            graphics.fill(x, 0, x + 1, this.height, 0x18244A6D);
        }

        int left = PAD;
        int top = PAD;
        int right = this.width - PAD;
        int bottom = this.height - PAD;

        graphics.fill(left - 2, top - 2, right + 2, bottom + 2, 0xCC020811);
        graphics.fill(left - 1, top - 1, right + 1, bottom + 1, ORDER_BOARD_BORDER_HI);
        graphics.fill(left, top, right, bottom, ORDER_BOARD_BG);

        int headerBottom = top + TOPBAR_HEIGHT;
        for (int y = top; y < headerBottom; y++) {
            float ratio = (float) (y - top) / (float) Math.max(1, TOPBAR_HEIGHT - 1);
            int row = lerpColor(ORDER_BOARD_CARD, ORDER_BOARD_PANEL, ratio);
            graphics.fill(left, y, right, y + 1, row);
        }

        int taskbarTop = bottom - TASKBAR_HEIGHT;
        for (int y = taskbarTop; y < bottom; y++) {
            float ratio = (float) (y - taskbarTop) / (float) Math.max(1, TASKBAR_HEIGHT - 1);
            int row = lerpColor(ORDER_BOARD_PANEL, ORDER_BOARD_ROW, ratio);
            graphics.fill(left, y, right, y + 1, row);
        }

        graphics.drawString(this.font, tr("UBS Commerce Desktop"), left + 10, top + 9, ORDER_BOARD_TEXT, false);
        int desktopAppCount = ClientOwnerPcData.getApps().size() + DESKTOP_UTILITY_APPS.size();
        int ownedShopCount = countOwnedShopApps();
        graphics.drawString(this.font,
                tr("Apps: ") + desktopAppCount + "   " + tr("Banks: ")
                        + ClientOwnerPcData.getOwnedCount() + "/" + ClientOwnerPcData.getMaxBanks()
                        + "   " + tr("Shops: ") + ownedShopCount + "/" + MAX_SHOPS_PER_PLAYER,
                left + 130,
                top + 9,
                ORDER_BOARD_MUTED,
                false);

        if (!desktopAuthenticated) {
            drawAuthLockScreen(graphics, left, top, right, bottom);
        } else if (activeWindow == WindowMode.BANK_APP) {
            drawBankWindowFrame(graphics);
        } else if (activeWindow == WindowMode.CREATE_BANK) {
            drawCreateWindowFrame(graphics);
        } else if (activeWindow == WindowMode.CREATE_SHOP) {
            drawCreateShopWindowFrame(graphics);
        } else if (activeWindow == WindowMode.UTILITY_APP) {
            drawUtilityWindowFrame(graphics);
        } else {
            drawDesktopHints(graphics);
        }

        boolean businessModalOverlayActive = isShopBusinessModalOverlayActive()
                || isShopOrderCreateModalOverlayActive()
                || isShopEmployeeModalOverlayActive()
                || isShopFinanceModalOverlayActive()
                || isShopHoursModalOverlayActive()
                || isShopPermissionModalOverlayActive()
                || isShopDeleteModalOverlayActive();
        boolean shopOrderCreateModalOverlayActive = isShopOrderCreateModalOverlayActive();
        boolean bankModalOverlayActive = isVaultRouteModalOpen()
                || isModernBankActionModalOpen()
                || isMarketDetailModalOpen()
                || (activeWindow == WindowMode.BANK_APP
                && !isActiveShopApp()
                && activeSection == Section.LENDING
                && pendingMarketAccept != null)
                || (activeWindow == WindowMode.BANK_APP
                && !isActiveShopApp()
                && activeSection == Section.ACCOUNTS
                && selectedAccountTransaction != null);
        boolean orderBoardModalOverlayActive = isOrderBoardModalOverlayActive();
        boolean webshopModalOverlayActive = isWebshopModalOverlayActive();
        if (shopOrderCreateModalOverlayActive) {
            drawShopOrderCreateModalOverlay(graphics);
            renderOnlyWidgetsInside(graphics, localMouseX, localMouseY, partialTicks, getShopOrderCreateModalBounds());
        } else if (webshopModalOverlayActive) {
            super.render(graphics, localMouseX, localMouseY, partialTicks);
            graphics.flush();
            graphics.pose().pushPose();
            graphics.pose().translate(0.0F, 0.0F, HOVER_TOOLTIP_Z + 120.0F);
            try {
                drawFinalWebshopOverlay(graphics);
                renderOnlyWidgetsInsideAny(graphics, localMouseX, localMouseY, partialTicks, visibleWebshopModalWidgetBounds);
            } finally {
                graphics.pose().popPose();
            }
        } else {
            super.render(graphics, localMouseX, localMouseY, partialTicks);
        }
        if (!businessModalOverlayActive && !bankModalOverlayActive && !orderBoardModalOverlayActive && !webshopModalOverlayActive) {
            drawSectionTextLabels(graphics);
            drawViewportMasks(graphics);
            drawTaskbarClockAndPower(graphics, localMouseX, localMouseY);
            drawKpiHoverTooltip(graphics, localMouseX, localMouseY);
            drawShopInventoryActionHoverTooltip(graphics, localMouseX, localMouseY);
            drawShopOperationsHoverTooltip(graphics, localMouseX, localMouseY);
            drawOrderBoardKpiHoverTooltip(graphics, localMouseX, localMouseY);
            drawOrderBoardHoverTooltip(graphics, localMouseX, localMouseY);
            drawWebshopKpiHoverTooltip(graphics, localMouseX, localMouseY);
            drawWebshopCardHoverTooltip(graphics, localMouseX, localMouseY);
            drawWebshopControlHoverTooltip(graphics, localMouseX, localMouseY);
        }
        if (!shopOrderCreateModalOverlayActive && !webshopModalOverlayActive) {
            drawShopBusinessHoverTooltip(graphics, localMouseX, localMouseY);
            drawBankHoverTooltip(graphics, localMouseX, localMouseY);
        }
        drawFinalBankMarketOverlay(graphics);
        drawFinalAccountTransactionOverlay(graphics);
        drawFinalOrderBoardOverlay(graphics);
        if (!webshopModalOverlayActive) {
            drawFinalWebshopOverlay(graphics);
        }
        if (useVirtualScale) {
            graphics.pose().popPose();
        }
    }

    private void renderOnlyWidgetsInside(GuiGraphics graphics, int mouseX, int mouseY, float partialTicks, RectHitbox bounds) {
        List<WidgetRenderState> states = new ArrayList<>();
        int padding = 18;
        for (var renderable : this.renderables) {
            if (renderable instanceof AbstractWidget widget) {
                states.add(new WidgetRenderState(widget, widget.visible, widget.active));
                boolean inside = widget.getX() >= bounds.x() - padding
                        && widget.getY() >= bounds.y() - padding
                        && widget.getX() + widget.getWidth() <= bounds.x() + bounds.width() + padding
                        && widget.getY() + widget.getHeight() <= bounds.y() + bounds.height() + padding;
                widget.visible = widget.visible && inside;
                widget.active = widget.active && inside;
            }
        }
        try {
            super.render(graphics, mouseX, mouseY, partialTicks);
        } finally {
            for (WidgetRenderState state : states) {
                state.widget().visible = state.visible();
                state.widget().active = state.active();
            }
        }
    }

    private void renderOnlyWidgetsInsideAny(GuiGraphics graphics,
                                            int mouseX,
                                            int mouseY,
                                            float partialTicks,
                                            List<RectHitbox> allowedBounds) {
        List<WidgetRenderState> states = new ArrayList<>();
        for (var renderable : this.renderables) {
            if (renderable instanceof AbstractWidget widget) {
                states.add(new WidgetRenderState(widget, widget.visible, widget.active));
                boolean allowed = isWidgetInsideAny(widget, allowedBounds);
                widget.visible = widget.visible && allowed;
                widget.active = widget.active && allowed;
            }
        }
        try {
            super.render(graphics, mouseX, mouseY, partialTicks);
        } finally {
            for (WidgetRenderState state : states) {
                state.widget().visible = state.visible();
                state.widget().active = state.active();
            }
        }
    }

    private boolean isWidgetInsideAny(AbstractWidget widget, List<RectHitbox> bounds) {
        if (widget == null || bounds == null || bounds.isEmpty()) {
            return false;
        }
        for (RectHitbox bound : bounds) {
            if (bound == null) {
                continue;
            }
            if (widget.getX() >= bound.x()
                    && widget.getY() >= bound.y()
                    && widget.getX() + widget.getWidth() <= bound.x() + bound.width()
                    && widget.getY() + widget.getHeight() <= bound.y() + bound.height()) {
                return true;
            }
        }
        return false;
    }

    private boolean isInsideAnyWebshopModalWidget(double mouseX, double mouseY) {
        if (visibleWebshopModalWidgetBounds.isEmpty()) {
            return false;
        }
        for (RectHitbox bound : visibleWebshopModalWidgetBounds) {
            if (bound != null && bound.contains(mouseX, mouseY)) {
                return true;
            }
        }
        return false;
    }

