    private void drawModernBankWindowFrame(GuiGraphics graphics, int left, int top, int right, int bottom) {
        visibleAccountCards.clear();
        visibleAccountTransactions.clear();
        visibleKpiCards.clear();
        visibleBankRuntimeHelp.clear();
        visibleVaultStorageMarkers.clear();
        visibleMarketActions.clear();
        accountProfileCopyIdHitbox = null;
        marketConfirmAcceptHitbox = null;
        marketConfirmCancelHitbox = null;
        clearMarketDetailHitboxes();

        OwnerPcBankDataPayload data = ClientOwnerPcData.getCurrentBankData();
        boolean dataReady = data != null && activeBankId != null && activeBankId.equals(data.bankId());
        int appW = Math.max(1, right - left);
        boolean compact = appW < 980;
        int outerInset = ownerPcOuterInset(appW);
        int sidebarW = ownerPcSidebarWidth(appW, false);
        int sidebarX = left + outerInset;
        int sidebarY = top + 18;
        int sidebarH = Math.max(120, bottom - top - 36);
        int contentX = sidebarX + sidebarW + ownerPcSidebarGap(appW);
        int contentRight = right - outerInset;
        int headerY = top + 18;
        int headerH = 72;
        boolean sidebarCard = shouldShowOwnerPcSidebarCard(appW, sidebarW, sidebarH);

        graphics.fill(left - 2, top - 2, right + 2, bottom + 2, 0xEE07111F);
        graphics.fill(left, top, right, bottom, 0xFF07111F);
        graphics.fill(left + 1, top + 1, right - 1, bottom - 1, 0xFF0B1727);
        graphics.fill(left + 1, top + 1, right - 1, top + 2, 0x884A7EA8);

        drawModernBankPanel(graphics, sidebarX, sidebarY, sidebarW, sidebarH, 0xFF0B1727, 0xFF1F3D5E);
        int sidebarTextX = sidebarX + ownerPcSidebarInnerPad(sidebarW);
        graphics.drawString(this.font, fitToWidth(tr("UBS Bank"), sidebarW - (ownerPcSidebarInnerPad(sidebarW) * 2)), sidebarTextX, sidebarY + 22, 0xFFFFFFFF, false);
        graphics.drawString(this.font, fitToWidth(tr("Owner PC bank app"), sidebarW - (ownerPcSidebarInnerPad(sidebarW) * 2)), sidebarTextX, sidebarY + 42, 0xFF9FB8D2, false);
        if (sidebarCard) {
            int cardX = sidebarX + 18;
            int cardY = sidebarY + 92;
            int cardW = sidebarW - 36;
            drawModernBankPanel(graphics, cardX, cardY, cardW, 82, 0xFF102238, 0xFF234C73);
            String bankName = dataReady ? data.bankName() : "Bank unavailable";
            graphics.drawString(this.font, fitToWidth(tr(bankName), cardW - 24), cardX + 12, cardY + 18, 0xFFFFFFFF, false);
            String ownerLine = dataReady ? data.ownershipModel() + " | " + data.ownerName() : "Waiting for server";
            graphics.drawString(this.font, fitToWidth(tr(ownerLine), cardW - 24), cardX + 12, cardY + 36, 0xFF9FB8D2, false);
            drawModernStatusChip(graphics, cardX + 12, cardY + 56, dataReady ? data.status() : "LOADING");
        }

        drawModernBankPanel(graphics, contentX, headerY, contentRight - contentX, headerH, 0xFF0F2035, 0xFF244B73);
        String title = dataReady
                ? (activeSection == Section.OVERVIEW ? data.bankName() + " overview" : bankSectionTitle(activeSection))
                : "Loading bank console";
        String subtitle = bankSectionSubtitle(activeSection);
        int contentW = Math.max(1, contentRight - contentX);
        int headerButtonW = toolbarButtonWForRender(contentW, compact);
        boolean showPremiseClaim = dataReady
                && activeSection == Section.PREMISES
                && hasPremisePresentationPermission(data);
        PremiseHeaderActions headerActions = premiseHeaderActions(
                contentX, contentRight, headerY, headerY + 20, headerButtonW, showPremiseClaim);
        int titleAvailable;
        if (showPremiseClaim) {
            titleAvailable = headerActions.textRight() - contentX - 28;
        } else {
            int reservedHeaderW = contentW >= 560 ? 390 : Math.max(140, headerButtonW + 54);
            titleAvailable = contentRight - contentX - reservedHeaderW;
        }
        if (titleAvailable >= 32) {
            graphics.drawString(this.font, fitToWidth(tr(title), titleAvailable),
                    contentX + 28, headerY + 18, 0xFFFFFFFF, false);
            graphics.drawString(this.font, fitToWidth(tr(subtitle), Math.max(1, titleAvailable - 2)),
                    contentX + 30, headerY + 39, 0xFF9FB8D2, false);
        }
        if (dataReady && !showPremiseClaim && contentW >= 640) {
            int refreshX = contentRight - headerButtonW - 14;
            String depositsLine = tr("Deposits") + " $" + compactCurrency(data.deposits());
            int depositW = Math.min(112, Math.max(72, this.font.width(depositsLine)));
            int chipW = modernStatusChipWidth(data.status());
            int metaW = chipW + 12 + depositW;
            int metaX = refreshX - metaW - 30;
            if (metaX > contentX + 250) {
                drawModernStatusChip(graphics, metaX, headerY + 26, data.status());
                graphics.drawString(this.font, fitToWidth(depositsLine, depositW),
                        metaX + chipW + 12, headerY + 31, 0xFFD5E2F1, false);
            }
        }

        if (!dataReady) {
            drawModernBankPanel(graphics, sectionViewportX, sectionViewportY, sectionViewportW, Math.min(160, sectionViewportH),
                    0xFF102238, 0xFF244B73);
            graphics.drawString(this.font, tr("Bank data is not loaded."), sectionViewportX + 18, sectionViewportY + 22, 0xFFFFFFFF, false);
            graphics.drawString(this.font, tr("Use Load Bank Data or Refresh to request the current state from the server."),
                    sectionViewportX + 18, sectionViewportY + 42, 0xFFB7CBE3, false);
            return;
        }

        enableScaledScissor(graphics, sectionViewportX, sectionViewportY, sectionViewportX + sectionViewportW, sectionViewportY + sectionViewportH);
        drawModernBankSection(graphics, data, sectionViewportX + 16, sectionViewportY - sectionScroll, Math.max(120, sectionViewportW - 32));
        graphics.disableScissor();
        if (sectionMaxScroll > 0) {
            drawVerticalScrollbar(
                    graphics,
                    ScrollbarTarget.SECTION,
                    true,
                    sectionViewportX + sectionViewportW - 4,
                    sectionViewportY + 2,
                    3,
                    Math.max(10, sectionViewportH - 4),
                    sectionScroll,
                    sectionMaxScroll
            );
        }
        if (isVaultRouteModalOpen()) {
            drawVaultRouteModalOverlay(graphics, data);
        } else if (isModernBankActionModalOpen()) {
            drawModernBankModalOverlay(graphics, data);
        }
    }

    private void drawModernBankSection(GuiGraphics graphics, OwnerPcBankDataPayload data, int x, int y, int width) {
        switch (activeSection) {
            case OVERVIEW -> drawModernBankOverview(graphics, data, x, y, width);
            case ACCOUNTS -> drawModernBankAccounts(graphics, data, x, y, width);
            case SAFE -> drawModernBankSafe(graphics, data, x, y, width);
            case PREMISES -> drawModernBankPremises(graphics, data, x, y, width);
            case BRANDING -> drawModernBankBranding(graphics, data, x, y, width);
            case LIMITS -> drawModernBankLimits(graphics, data, x, y, width);
            case GOVERNANCE -> drawModernBankGovernance(graphics, data, x, y, width);
            case STAFFING -> drawModernBankStaffing(graphics, data, x, y, width);
            case LENDING -> drawModernBankLending(graphics, data, x, y, width);
            case COMPLIANCE -> drawModernBankCompliance(graphics, data, x, y, width);
            case BUSINESS, HOURS, PERMISSIONS -> {
            }
        }
    }

    private void drawModernBankPremises(GuiGraphics graphics,
                                        OwnerPcBankDataPayload data,
                                        int x,
                                        int y,
                                        int width) {
        List<OwnerPcPremisePayload> premises = data.premises();
        OwnerPcPremisesPanelLayout.Layout layout = OwnerPcPremisesPanelLayout.layout(
                width, sectionViewportH, premises.size(), sectionScroll);
        drawModernPremisesSummary(graphics, premises, x, y, width);

        int viewportBottom = sectionViewportY + sectionViewportH;
        for (OwnerPcPremisesPanelLayout.Card card : layout.cards()) {
            int cardY = y + card.y();
            if (cardY + card.height() < sectionViewportY || cardY > viewportBottom) {
                continue;
            }
            drawModernPremiseCard(
                    graphics,
                    premises.get(card.index()),
                    x + card.x(),
                    cardY,
                    card.width(),
                    card.height()
            );
        }
    }

    private void drawModernPremisesSummary(GuiGraphics graphics,
                                           List<OwnerPcPremisePayload> premises,
                                           int x,
                                           int y,
                                           int width) {
        int ready = (int) premises.stream()
                .filter(premise -> premise.status() == OwnerPcPremisePayload.Status.READY)
                .count();
        int publicCount = (int) premises.stream()
                .filter(premise -> premise.mode() == SafePremiseMode.PUBLIC)
                .count();
        int blocked = (int) premises.stream()
                .filter(premise -> !premise.deleteBlockers().isEmpty())
                .count();
        int migrationBacked = (int) premises.stream()
                .filter(OwnerPcPremisePayload::migrationBacked)
                .count();
        int viewingRooms = premises.stream().mapToInt(OwnerPcPremisePayload::viewingRoomCount).sum();
        int readyViewingRooms = premises.stream().mapToInt(OwnerPcPremisePayload::readyViewingRoomCount).sum();

        drawModernBankPanel(
                graphics,
                x,
                y,
                width,
                OwnerPcPremisesPanelLayout.SUMMARY_HEIGHT,
                ORDER_BOARD_PANEL,
                ORDER_BOARD_BORDER
        );
        int accent = premises.isEmpty() ? ORDER_BOARD_GOLD : ORDER_BOARD_CYAN;
        graphics.fill(x + 1, y + 1, x + 5, y + OwnerPcPremisesPanelLayout.SUMMARY_HEIGHT - 1, accent);
        graphics.drawString(this.font, tr("Premises"), x + 16, y + 14, ORDER_BOARD_TEXT, false);
        graphics.drawString(
                this.font,
                fitToWidth(tr("Bank location registry, access modes, exits, and deletion state."), width - 32),
                x + 16,
                y + 32,
                ORDER_BOARD_MUTED,
                false
        );
        String totals = premises.size() + " locations | " + ready + " ready | " + publicCount + " public";
        graphics.drawString(this.font, fitToWidth(tr(totals), width - 32), x + 16, y + 52,
                ready == premises.size() && !premises.isEmpty() ? ORDER_BOARD_GREEN : ORDER_BOARD_GOLD, false);
        String constraints = premises.isEmpty()
                ? "No premises are registered."
                : readyViewingRooms + " of " + viewingRooms + " viewing rooms ready | "
                + blocked + " deletion blocked | " + migrationBacked + " migrated";
        graphics.drawString(this.font, fitToWidth(tr(constraints), width - 32), x + 16, y + 69,
                blocked == 0 ? ORDER_BOARD_GREEN : ORDER_BOARD_RED, false);
    }

    private void drawModernPremiseCard(GuiGraphics graphics,
                                       OwnerPcPremisePayload premise,
                                       int x,
                                       int y,
                                       int width,
                                       int height) {
        boolean ready = premise.status() == OwnerPcPremisePayload.Status.READY;
        int accent = ready ? ORDER_BOARD_GREEN : ORDER_BOARD_GOLD;
        int textX = x + 12;
        int textWidth = Math.max(40, width - 24);
        drawModernBankPanel(graphics, x, y, width, height, ORDER_BOARD_CARD, ORDER_BOARD_BORDER_HI);
        graphics.fill(x + 1, y + 1, x + 5, y + height - 1, accent);
        graphics.drawString(this.font,
                fitToWidth(tr("Premise " + shortUuid(premise.premiseId())), textWidth),
                textX, y + 12, ORDER_BOARD_TEXT, false);
        String state = premise.status().name() + " | " + premise.mode().name();
        graphics.drawString(this.font, fitToWidth(tr(state), textWidth), textX, y + 29, accent, false);

        List<String> details = List.of(
                "Dimension: " + premise.dimension(),
                "Bounds min: " + premise.minX() + ", " + premise.minY() + ", " + premise.minZ(),
                "Bounds max: " + premise.maxX() + ", " + premise.maxY() + ", " + premise.maxZ(),
                "Exit dimension: " + premise.exitDimension(),
                "Exit: " + premise.exitX() + ", " + premise.exitY() + ", " + premise.exitZ()
                        + " | yaw " + String.format(Locale.ROOT, "%.1f", premise.exitYaw()),
                "Children: safe areas " + premise.safeAreaCount() + " | vaults " + premise.vaultCount(),
                "Vault readiness: " + premise.readyVaultCount() + " of " + premise.vaultCount() + " ready",
                "Migration: " + (premise.migrationBacked() ? "MIGRATION_BACKED" : "NATIVE")
        );
        int lineY = y + 48;
        for (String detail : details) {
            graphics.drawString(this.font, fitToWidth(tr(detail), textWidth), textX, lineY, ORDER_BOARD_MUTED, false);
            lineY += LINE_HEIGHT;
        }

        graphics.drawString(this.font, tr("Deletion blockers"), textX, y + 143, ORDER_BOARD_TEXT, false);
        int blockerY = y + 159;
        if (premise.deleteBlockers().isEmpty()) {
            graphics.drawString(this.font, tr("None - deletion eligible"), textX, blockerY,
                    ORDER_BOARD_GREEN, false);
        } else {
            for (OwnerPcPremisePayload.DeleteBlocker blocker : premise.deleteBlockers()) {
                String label = "- " + premiseDeleteBlockerLabel(blocker);
                graphics.drawString(this.font, fitToWidth(tr(label), textWidth), textX, blockerY,
                        ORDER_BOARD_RED, false);
                blockerY += LINE_HEIGHT;
            }
        }

        OwnerPcPremisesPanelLayout.Controls controls = OwnerPcPremisesPanelLayout.controls(width, height);
        int controlLabelY = y + controls.publicMode().y() - 14;
        graphics.drawString(this.font, tr("Access mode and actions"), textX, controlLabelY,
                ORDER_BOARD_TEXT, false);
    }

    private String premiseDeleteBlockerLabel(OwnerPcPremisePayload.DeleteBlocker blocker) {
        return switch (blocker) {
            case NON_EMPTY -> "NON_EMPTY - child records remain";
            case MIGRATION_BACKED -> "MIGRATION_BACKED - compatibility record";
            case ASSIGNED -> "ASSIGNED - deposit boxes assigned";
            case ROUTED -> "ROUTED - teller route references it";
            case ACTIVE -> "ACTIVE - live escort or session";
        };
    }

    private void drawModernBankOverview(GuiGraphics graphics, OwnerPcBankDataPayload data, int x, int y, int width) {
        int gap = 10;
        BigDecimal reserve = parseDecimal(data.reserve());
        BigDecimal deposits = parseDecimal(data.deposits());
        BigDecimal minReserve = parseDecimal(data.minReserve());
        BigDecimal dailyCap = parseDecimal(data.dailyCap());
        BigDecimal dailyUsed = parseDecimal(data.dailyUsed());
        float reserveCoverage = minReserve.signum() <= 0 ? 1.0F : reserve.divide(minReserve, 4, RoundingMode.HALF_EVEN).floatValue();
        float dailyUsage = dailyCap.signum() <= 0 ? 0.0F : dailyUsed.divide(dailyCap, 4, RoundingMode.HALF_EVEN).floatValue();
        int kpiCols = modernBankOverviewKpiColumns(width);
        int kpiW = kpiCols <= 1 ? width : Math.max(120, (width - (gap * (kpiCols - 1))) / kpiCols);
        int kpiH = modernBankOverviewKpiHeight(width);
        String[] labels = {"Bank Level", "Reserve", "Deposits", "Reserve Ratio", "Daily Used", "Federal Rate"};
        String[] values = {
                "Level " + data.bankLevel(),
                "$" + compactCurrency(data.reserve()),
                "$" + compactCurrency(data.deposits()),
                data.reserveRatio() + "%",
                "$" + compactCurrency(data.dailyUsed()) + " / $" + compactCurrency(data.dailyCap()),
                data.federalFundsRate() + "%"
        };
        String[] subs = {
                "Safe rows " + data.safeRowCapacity(),
                "Minimum $" + compactCurrency(data.minReserve()),
                data.accountsCount() + " active accounts",
                reserve.compareTo(minReserve) < 0 ? "Below requirement" : "Requirement met",
                dailyCap.signum() <= 0 ? "No daily cap active" : "$" + compactCurrency(data.dailyRemaining()) + " remaining",
                "Loan pricing baseline"
        };
        int[] accents = {0xFF22C55E, ORDER_BOARD_RED, ORDER_BOARD_CYAN, ORDER_BOARD_RED, ORDER_BOARD_GOLD, ORDER_BOARD_VIOLET};
        int visibleKpis = Math.min(labels.length, modernBankOverviewKpiCount(width));
        for (int i = 0; i < visibleKpis; i++) {
            int col = i % kpiCols;
            int row = i / kpiCols;
            drawModernKpiCard(graphics, x + (col * (kpiW + gap)), y + (row * (kpiH + gap)), kpiW, kpiH,
                    labels[i], values[i], subs[i], accents[i]);
        }

        int contentY = y + (((visibleKpis + kpiCols - 1) / kpiCols) * (kpiH + gap)) + 6;
        boolean wide = modernBankOverviewUsesWidePanels(width);
        int leftW = wide ? Math.max(300, ((width - gap) * 58) / 100) : width;
        int rightW = wide ? Math.max(220, width - leftW - gap) : width;
        if (wide && leftW + gap + rightW > width) {
            leftW = Math.max(260, width - gap - rightW);
        }
        int rightX = wide ? x + leftW + gap : x;

        int reserveH = modernBankOverviewReservePanelHeight(width);
        int actionsH = modernBankOverviewQuickActionsHeight(width);
        drawModernBankPanel(graphics, x, contentY, leftW, reserveH, 0xFF102238, 0xFF244B73);
        graphics.drawString(this.font, tr("Reserve health"), x + 18, contentY + 20, 0xFFFFFFFF, false);
        graphics.drawString(this.font, tr("Immediate solvency and reserve cushion."), x + 18, contentY + 38, 0xFF9FB8D2, false);
        drawModernProgress(graphics, x + 18, contentY + 72, leftW - 36, "Reserve cushion",
                "$" + compactCurrency(data.reserve()) + " vs minimum $" + compactCurrency(data.minReserve()),
                reserveCoverage, reserve.compareTo(minReserve) >= 0 ? 0xFF22C55E : ORDER_BOARD_RED);
        drawModernProgress(graphics, x + 18, contentY + 122, leftW - 36, "Daily utilization",
                "$" + compactCurrency(data.dailyUsed()) + " used today", dailyUsage, ORDER_BOARD_CYAN);
        int alertY = contentY + reserveH - 38;
        graphics.fill(x + 18, alertY, x + leftW - 18, alertY + 24, 0x882B1020);
        graphics.fill(x + 18, alertY, x + leftW - 18, alertY + 1, ORDER_BOARD_RED);
        String alert = reserve.compareTo(minReserve) < 0
                ? "Reserve is below the configured minimum. Add reserve or reduce exposure."
                : "Reserve is above the configured minimum.";
        graphics.drawString(this.font, fitToWidth(tr(alert), leftW - 48), x + 28, alertY + 8, 0xFFFFDDE5, false);

        int actionsX = wide ? rightX : x;
        int actionsY = wide ? contentY : contentY + reserveH + gap;
        int actionsW = wide ? rightW : width;
        drawModernQuickActionsPanel(graphics, actionsX, actionsY, actionsW, actionsH);

        int lowerY = wide ? contentY + Math.max(reserveH, actionsH) + gap : actionsY + actionsH + gap;
        if (wide) {
            drawModernRecentAccounts(graphics, data, x, lowerY, leftW, 220, "Recent accounts");
            drawModernLendingSummary(graphics, data, rightX, lowerY, rightW, modernBankOverviewLendingHeight(width, true));
            int roadmapY = lowerY + Math.max(220, modernBankOverviewLendingHeight(width, true)) + gap;
            drawModernBankLevelRoadmap(graphics, data, x, roadmapY, width, modernBankLevelRoadmapHeight(width));
            drawModernActionFeedback(graphics, x, roadmapY + modernBankLevelRoadmapHeight(width) + gap, width);
        } else {
            drawModernRecentAccounts(graphics, data, x, lowerY, width, 220, "Recent accounts preview");
            drawModernLendingSummary(graphics, data, x, lowerY + 230, width, modernBankOverviewLendingHeight(width, false));
            int roadmapY = lowerY + 230 + modernBankOverviewLendingHeight(width, false) + gap;
            drawModernBankLevelRoadmap(graphics, data, x, roadmapY, width, modernBankLevelRoadmapHeight(width));
            drawModernActionFeedback(graphics, x, roadmapY + modernBankLevelRoadmapHeight(width) + gap, width);
        }
    }

