    private void drawModernBankLimits(GuiGraphics graphics, OwnerPcBankDataPayload data, int x, int y, int width) {
        String singleLimit = data.singleLimit();
        String dailyPlayerLimit = data.dailyPlayerLimit();
        String dailyBankLimit = data.dailyBankLimit();
        String tellerLimit = data.tellerLimit();
        String[] labels = {"Single Withdrawal", "Daily Player", "Daily Bank"};
        String[] values = {
                modernBankLimitValue(singleLimit),
                modernBankLimitValue(dailyPlayerLimit),
                modernBankLimitValue(dailyBankLimit)
        };
        String[] subs = {
                modernBankLimitStatus(singleLimit, "Configured per transaction", "Per transaction ceiling"),
                modernBankLimitStatus(dailyPlayerLimit, "Configured per player", "Per player daily ceiling"),
                modernBankLimitStatus(dailyBankLimit, "Configured bank-wide", "Bank daily ceiling")
        };
        int[] accents = {
                singleLimit == null || singleLimit.isBlank() ? ORDER_BOARD_CYAN : 0xFF22C55E,
                dailyPlayerLimit == null || dailyPlayerLimit.isBlank() ? ORDER_BOARD_VIOLET : 0xFF22C55E,
                dailyBankLimit == null || dailyBankLimit.isBlank() ? ORDER_BOARD_GOLD : 0xFF22C55E
        };
        drawModernSectionKpiBand(graphics, x, y, width, labels, values, subs, accents);

        int tableY = y + modernSectionKpiBlockHeight(width, 3) + 18;
        int tableH = modernLimitsTableHeight(width);
        drawModernBankPanel(graphics, x, tableY, width, tableH, 0xFF102238, 0xFF244B73);
        graphics.drawString(this.font, tr("Configured limits"), x + 18, tableY + 20, 0xFFFFFFFF, false);
        graphics.drawString(this.font, tr("Choose a row to edit the amount or clear the limit."),
                x + 18, tableY + 38, 0xFF9FB8D2, false);

        int rowY = tableY + 78;
        int rowH = modernLimitsRowHeight(width);
        int rowW = Math.max(80, width - 32);
        drawModernLimitConfigRow(graphics, x + 16, rowY, rowW, rowH,
                "Single withdrawal",
                modernBankLimitValue(singleLimit),
                modernBankLimitStatus(singleLimit, "Per-transaction ceiling configured", "No ceiling configured"),
                false);
        drawModernLimitConfigRow(graphics, x + 16, rowY + rowH, rowW, rowH,
                "Daily player",
                modernBankLimitValue(dailyPlayerLimit),
                modernBankLimitStatus(dailyPlayerLimit, "Per-player daily ceiling configured", "Fallback rules apply"),
                false);
        drawModernLimitConfigRow(graphics, x + 16, rowY + (rowH * 2), rowW, rowH,
                "Daily bank",
                modernBankLimitValue(dailyBankLimit),
                modernBankLimitStatus(dailyBankLimit, "Bank-wide daily ceiling configured", "No bank-wide ceiling configured"),
                false);
        drawModernLimitConfigRow(graphics, x + 16, rowY + (rowH * 3), rowW, rowH,
                "Teller limit",
                modernBankLimitValue(tellerLimit),
                modernBankLimitStatus(tellerLimit, "NPC teller cash ceiling configured", "NPC teller fallback rules apply"),
                false);
        drawModernLimitConfigRow(graphics, x + 16, rowY + (rowH * 4), rowW, rowH,
                "Card issue fee", "$" + compactCurrency(data.cardIssueFee()), "Charged when issuing new cards", false);
        drawModernLimitConfigRow(graphics, x + 16, rowY + (rowH * 5), rowW, rowH,
                "Card replacement fee", "$" + compactCurrency(data.cardReplacementFee()), "Charged when replacing cards", false);

        drawModernActionFeedback(graphics, x, tableY + tableH + 20, width);
    }

