    private int countSafeAccessEmployees(OwnerPcBankDataPayload data) {
        int count = 0;
        for (OwnerPcPlayerEmployeePayload employee : data.playerEmployees()) {
            if (employee.safeAccess()) {
                count++;
            }
        }
        return count;
    }

