        graphics.drawString(this.font, tr("Borrowing"), x + 16, cardY + 18, 0xFFFFFFFF, false);
        graphics.drawString(this.font, tr("Request bank funds without leaving the lending workspace."),
                x + 16, cardY + 42, 0xFF9FB8D2, false);
        int offerX = wide ? x + half + gap : x;
        int offerY = wide ? cardY : cardY + 150;
        int offerW = wide ? width - half - gap : width;
        drawModernBankPanel(graphics, offerX, offerY, offerW, 140, 0xFF102238, 0xFF244B73);
        graphics.drawString(this.font, tr("Market offer"), offerX + 16, offerY + 18, 0xFFFFFFFF, false);
        graphics.drawString(this.font, tr("Publish amount, APR, and term as one offer."),
                offerX + 16, offerY + 42, 0xFF9FB8D2, false);
        int productY = wide ? cardY + 198 : cardY + 300;
        drawModernBankPanel(graphics, x, productY, width, 166, 0xFF102238, 0xFF244B73);
        graphics.drawString(this.font, tr("Loan product builder"), x + 16, productY + 18, 0xFFFFFFFF, false);
