    private int getModernLendingMarketHeight(int width) {
        List<MarketOfferData> offers = getSortedMarketOffers();
        int cols = width >= 760 ? 2 : 1;
        int cardH = width >= 760 ? 104 : 112;
        int gap = 10;
        int controlsH = width >= 640 ? 34 : 92;
        int rows = offers.isEmpty() ? 1 : (offers.size() + cols - 1) / cols;
        return 104 + controlsH + (rows * cardH) + (Math.max(0, rows - 1) * gap) + 18;
    }

    private void drawModernLendingMarketContainer(GuiGraphics graphics,
                                                  OwnerPcBankDataPayload data,
                                                  int x,
                                                  int y,
                                                  int width,
                                                  int height) {
        drawModernBankPanel(graphics, x, y, width, height, 0xFF102238, 0xFF244B73);
        graphics.fill(x + 1, y + 1, x + 5, y + height - 1, ORDER_BOARD_GREEN);

        List<MarketOfferData> offers = getSortedMarketOffers();
        String search = formValues.getOrDefault("lend.market.search", "").trim();
        String marketState = "Offers " + offers.size()
                + " | " + marketFilterLabel(marketFilter)
                + " | Sort " + marketSortLabel(marketSort)
                + " " + (marketSortDescending ? "high-low" : "low-high");
        graphics.drawString(this.font, tr("Interbank Market"), x + 16, y + 18, 0xFFFFFFFF, false);
        graphics.drawString(this.font, fitToWidth(tr("Browse open bank offers, filter them, and inspect exact terms before accepting."),
                width - 32), x + 16, y + 38, 0xFF9FB8D2, false);
        graphics.drawString(this.font, fitToWidth(tr(marketState), width - 32), x + 16, y + 58, 0xFFBDE6D6, false);

        int controlsY = y + 84;
        graphics.drawString(this.font, fitToWidth(tr("Search") + (search.isBlank() ? "" : ": " + search), width - 32),
                x + 16, controlsY - 12, 0xFFB7CBE3, false);
        graphics.drawString(this.font, fitToWidth(tr(marketFilterDescription(marketFilter)), Math.max(80, width - 32)),
                x + 16, controlsY + (width >= 640 ? 24 : 84), 0xFF9FB8D2, false);

        int listY = y + 104 + (width >= 640 ? 34 : 92);
        int listX = x + 16;
        int listW = Math.max(80, width - 32);
        int cardGap = 10;
        boolean waitingForMarket = ClientOwnerPcData.getActionOutputLines().isEmpty() && marketOfferCache.isEmpty();
        if (offers.isEmpty()) {
            int emptyH = Math.max(92, height - (listY - y) - 18);
            graphics.fill(listX, listY, listX + listW, listY + emptyH, 0x6618324E);
            graphics.fill(listX, listY, listX + listW, listY + 1, 0x887FB8E8);
            String title = waitingForMarket ? "Market not loaded" : "No offers match";
            String body = waitingForMarket
                    ? "Press Refresh to request open interbank offers from the server."
                    : "Adjust search, filter, or sort to broaden the market list.";
            graphics.drawString(this.font, tr(title), listX + 14, listY + 18, 0xFFFFFFFF, false);
            graphics.drawString(this.font, fitToWidth(tr(body), listW - 28), listX + 14, listY + 38, 0xFFB7CBE3, false);
            return;
        }

        int cols = listW >= 760 ? 2 : 1;
        int cardW = Math.max(120, (listW - (cardGap * (cols - 1))) / cols);
        int cardH = cols >= 2 ? 104 : 112;
        for (int i = 0; i < offers.size(); i++) {
            int row = i / cols;
            int col = i % cols;
            int cardX = listX + (col * (cardW + cardGap));
            int cardY = listY + (row * (cardH + cardGap));
            drawModernLendingMarketCard(graphics, data, offers.get(i), cardX, cardY, cardW, cardH);
        }
    }

    private void drawModernLendingMarketCard(GuiGraphics graphics,
                                             OwnerPcBankDataPayload data,
                                             MarketOfferData offer,
                                             int x,
                                             int y,
                                             int width,
                                             int height) {
        graphics.fill(x, y, x + width, y + height, 0xFF2F5479);
        graphics.fill(x + 1, y + 1, x + width - 1, y + height - 1, 0xDA102A45);
        graphics.fill(x + 1, y + 1, x + 5, y + height - 1, ORDER_BOARD_CYAN);

        String lender = offer.lender().isBlank() ? "Unknown lender" : offer.lender();
        graphics.drawString(this.font, fitToWidth(tr(lender), width - 94), x + 14, y + 12, 0xFFFFFFFF, false);
        int badgeW = Math.min(78, Math.max(48, this.font.width(shortMarketOfferId(offer)) + 12));
        graphics.fill(x + width - badgeW - 10, y + 8, x + width - 10, y + 21, 0x994E84B2);
        graphics.drawCenteredString(this.font, fitToWidth(shortMarketOfferId(offer), badgeW - 8),
                x + width - 10 - (badgeW / 2), y + 11, 0xFFDDF0FF);

        int metricY = y + 34;
        int metricW = Math.max(40, (width - 34) / 3);
        drawModernMarketMetric(graphics, x + 14, metricY, metricW, "Amount", offer.amountText(), ORDER_BOARD_GREEN);
        drawModernMarketMetric(graphics, x + 14 + metricW + 6, metricY, metricW, "APR", offer.aprText(), ORDER_BOARD_GOLD);
        drawModernMarketMetric(graphics, x + 14 + ((metricW + 6) * 2), metricY, metricW, "Term", offer.termText(), ORDER_BOARD_VIOLET);

        int btnY = y + height - 24;
        int btnGap = 6;
        int btnW = Math.max(48, (width - 28 - (btnGap * 2)) / 3);
        int detailsX = x + 14;
        int acceptX = detailsX + btnW + btnGap;
        int copyX = acceptX + btnW + btnGap;
        boolean ownerView = data != null && data.ownerView();
        drawInlineActionButton(graphics, detailsX, btnY, btnW, 17, "Details", ORDER_BOARD_CYAN);
        drawInlineActionButton(graphics, acceptX, btnY, btnW, 17, ownerView ? "Accept" : "Locked", ownerView ? 0xFF67BC86 : 0xFF7895B4);
        drawInlineActionButton(graphics, copyX, btnY, btnW, 17, "Copy ID", ORDER_BOARD_VIOLET);
        visibleMarketActions.add(new MarketActionHitbox(detailsX, btnY, btnW, 17, "DETAILS", offer));
        visibleMarketActions.add(new MarketActionHitbox(acceptX, btnY, btnW, 17, "ACCEPT", offer));
        visibleMarketActions.add(new MarketActionHitbox(copyX, btnY, btnW, 17, "COPY", offer));
    }

