    private void drawModernBankCompliance(GuiGraphics graphics, OwnerPcBankDataPayload data, int x, int y, int width) {
        BigDecimal reserve = parseDecimal(data.reserve());
        BigDecimal minReserve = parseDecimal(data.minReserve());
        boolean reserveFailing = reserve.compareTo(minReserve) < 0;
        String[] labels = {"Status", "Reserve Audit", "Appeals"};
        String[] values = {data.status(), reserveFailing ? "Failing" : "Passing", "0"};
        String[] subs = {"Bank is operating", reserveFailing ? "Below configured minimum" : "Reserve requirement met", "No open appeals"};
        int[] accents = {statusColor(data.status()), reserveFailing ? ORDER_BOARD_RED : 0xFF22C55E, ORDER_BOARD_CYAN};
        drawModernSectionKpiBand(graphics, x, y, width, labels, values, subs, accents);

        int contentY = y + modernSectionKpiBlockHeight(width, 3) + 18;
        int gap = 10;
        boolean wide = width >= 760;
        int actionW = wide ? Math.max(230, (width - gap) * 32 / 100) : width;
        int timelineW = wide ? width - actionW - gap : width;
        int actionX = wide ? x + timelineW + gap : x;
        int actionY = wide ? contentY : contentY + modernComplianceTimelineHeight(width) + gap;
        drawModernComplianceTimeline(graphics, data, x, contentY, timelineW, modernComplianceTimelineHeight(width), reserveFailing);
        drawModernComplianceAppealPanel(graphics, actionX, actionY, actionW, modernComplianceActionHeight(width));
        drawModernActionFeedback(graphics, x, actionY + modernComplianceActionHeight(width) + 20, width);
    }

    private void drawModernSectionKpiBand(GuiGraphics graphics,
                                          int x,
                                          int y,
                                          int width,
                                          String[] labels,
                                          String[] values,
                                          String[] subs,
                                          int[] accents) {
        int count = Math.min(Math.min(labels.length, values.length), Math.min(subs.length, accents.length));
        int cols = modernSectionKpiColumns(width, count);
        int gap = 10;
        int cardW = cols <= 1 ? width : Math.max(120, (width - (gap * (cols - 1))) / cols);
        for (int i = 0; i < count; i++) {
            int col = i % cols;
            int row = i / cols;
            drawModernKpiCard(graphics, x + (col * (cardW + gap)), y + (row * 86), cardW, 76,
                    labels[i], values[i], subs[i], accents[i]);
        }
    }

    private int modernSectionKpiBlockHeight(int width, int count) {
        int cols = modernSectionKpiColumns(width, count);
        int rows = (Math.max(1, count) + cols - 1) / cols;
        return (rows * 76) + (Math.max(0, rows - 1) * 10);
    }

    private int modernSectionKpiColumns(int width, int count) {
        if (width >= 760) {
            return Math.min(Math.max(1, count), 3);
        }
        if (width >= 420) {
            return Math.min(Math.max(1, count), 2);
        }
        return 1;
    }

