    private int statusColor(String status) {
        String normalized = status == null ? "" : status.toUpperCase(Locale.ROOT);
        if (normalized.contains("ACTIVE") || normalized.contains("OPEN")) {
            return 0xFF22C55E;
        }
        if (normalized.contains("SUSPENDED") || normalized.contains("REVOKED") || normalized.contains("LOCK")) {
            return ORDER_BOARD_RED;
        }
        return ORDER_BOARD_GOLD;
    }

