    private List<OwnerPcSafeAccessLogPayload> filteredSafeAccessLogs(OwnerPcBankDataPayload data) {
        if (data == null) return List.of();
        if (safeLogFilter == SafeLogFilter.ALL) return data.safeAccessLogs();
        return data.safeAccessLogs().stream()
                .filter(entry -> safeLogFilter.name().equalsIgnoreCase(entry.category()))
                .toList();
    }

    private int safeLogAccent(OwnerPcSafeAccessLogPayload entry) {
        if ("DENIED".equalsIgnoreCase(entry.outcome())) return ORDER_BOARD_RED;
        return switch (entry.category().toUpperCase(Locale.ROOT)) {
            case "BOX_ACCESS" -> ORDER_BOARD_CYAN;
            case "ASSIGNMENT" -> ORDER_BOARD_GOLD;
            case "SECURITY" -> ORDER_BOARD_RED;
            case "STORAGE" -> ORDER_BOARD_GREEN;
            default -> ORDER_BOARD_VIOLET;
        };
    }

    private String formatSafeLogTimestamp(long occurredAtMillis) {
        if (occurredAtMillis <= 0L) return "Unknown time";
        return LocalDateTime.ofInstant(Instant.ofEpochMilli(occurredAtMillis), ZoneId.systemDefault())
                .format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm"));
    }

    private static String humanizeSafeLogToken(String raw) {
        if (raw == null || raw.isBlank()) return "Activity";
        String[] words = raw.trim().toLowerCase(Locale.ROOT).split("[_\\s]+", -1);
        StringBuilder result = new StringBuilder();
        for (String word : words) {
            if (word.isBlank()) continue;
            if (!result.isEmpty()) result.append(' ');
            result.append(Character.toUpperCase(word.charAt(0))).append(word.substring(1));
        }
        return result.isEmpty() ? "Activity" : result.toString();
    }

    private String vaultStorageTooltip(OwnerPcVaultStorageMarkerPayload marker) {
        return marker.locationSummary() + " | Press to see details";
    }

    private int toolbarButtonWForRender(int headerContentW, boolean compact) {
        if (!compact) {
            return 86;
        }
        return Math.max(36, Math.min(70, (Math.max(1, headerContentW) - 38) / 3));
    }

    private int ownerPcSidebarWidth(int appWidth, boolean shopApp) {
        int safeWidth = Math.max(1, appWidth);
        if (safeWidth < 360) {
            return Math.max(88, Math.min(shopApp ? 116 : 108, Math.max(1, safeWidth / 3)));
        }
        if (safeWidth < 520) {
            return Math.max(112, Math.min(shopApp ? 148 : 140, safeWidth / 3));
        }
        if (safeWidth < 760) {
            return Math.max(142, Math.min(shopApp ? 178 : 168, safeWidth / 4));
        }
        int preferred = shopApp ? 220 : 210;
        int max = shopApp ? 250 : 240;
        return Math.min(max, Math.max(preferred, safeWidth / 5));
    }

    private int ownerPcSidebarGap(int appWidth) {
        return appWidth < 420 ? 6 : (appWidth < 640 ? 10 : (appWidth < 980 ? 16 : 24));
    }

    private int ownerPcOuterInset(int appWidth) {
        return appWidth < 420 ? 8 : (appWidth < 520 ? 10 : 16);
    }

    private int ownerPcSidebarInnerPad(int sidebarWidth) {
        return sidebarWidth < 120 ? 6 : (sidebarWidth < 150 ? 8 : 14);
    }

    private boolean shouldShowOwnerPcSidebarCard(int appWidth, int sidebarWidth, int sidebarHeight) {
        return appWidth >= 700 && sidebarWidth >= 180 && sidebarHeight >= 270;
    }

    private int scrollableContentHeight(int contentHeight, int viewportHeight) {
        int safeContent = Math.max(0, contentHeight);
        int safeViewport = Math.max(1, viewportHeight);
        if (safeContent <= safeViewport) {
            return safeContent;
        }
        return safeContent + PANEL_SCROLL_BOTTOM_PADDING;
    }

    private int pixelScrollMax(int contentHeight, int viewportHeight) {
        return Math.max(0, scrollableContentHeight(contentHeight, viewportHeight) - Math.max(1, viewportHeight));
    }

    private int navScrollMax(int contentHeight, int viewportHeight) {
        int safeContent = Math.max(0, contentHeight);
        int safeViewport = Math.max(1, viewportHeight);
        if (safeContent <= safeViewport) {
            return 0;
        }
        return Math.max(0, safeContent + NAV_SCROLL_BOTTOM_PADDING - safeViewport);
    }

    private int modernBankOverviewContentHeight(int width) {
        int kpiCols = modernBankOverviewKpiColumns(width);
        int kpiRows = (modernBankOverviewKpiCount(width) + kpiCols - 1) / kpiCols;
        int contentY = (kpiRows * (modernBankOverviewKpiHeight(width) + 10)) + 6;
        boolean wide = modernBankOverviewUsesWidePanels(width);
        int topPanels = wide
                ? Math.max(modernBankOverviewReservePanelHeight(width), modernBankOverviewQuickActionsHeight(width))
                : modernBankOverviewReservePanelHeight(width) + 10 + modernBankOverviewQuickActionsHeight(width);
        int feedback = modernBankActionFeedbackHeight();
        if (wide) {
            return contentY + topPanels + 10 + Math.max(220, modernBankOverviewLendingHeight(width, true))
                    + 10 + modernBankLevelRoadmapHeight(width) + (feedback == 0 ? 0 : 10 + feedback);
        }
        return contentY + topPanels + 10 + 220 + 10 + modernBankOverviewLendingHeight(width, false)
                + 10 + modernBankLevelRoadmapHeight(width) + (feedback == 0 ? 0 : 10 + feedback);
    }

    private int modernBankOverviewKpiCount(int width) {
        return 6;
    }

    private int modernBankOverviewKpiColumns(int width) {
        if (width >= 1040) {
            return 6;
        }
        if (width >= 900) {
            return 5;
        }
        if (width >= 650) {
            return 3;
        }
        if (width >= 380) {
            return 2;
        }
        return 1;
    }

    private boolean modernBankOverviewUsesWidePanels(int width) {
        return width >= 760;
    }

    private int modernBankOverviewKpiHeight(int width) {
        return width < 380 ? 74 : 86;
    }

    private int modernBankOverviewReservePanelHeight(int width) {
        return width < 420 ? 206 : 190;
    }

    private int modernBankOverviewQuickActionsHeight(int width) {
        return width < 420 ? 206 : 224;
    }

    private int modernBankOverviewLendingHeight(int width, boolean wide) {
        if (wide) {
            return width < 900 ? 232 : 220;
        }
        return width < 280 ? 230 : 220;
    }

    private int modernBankLevelRoadmapHeight(int width) {
        return width < 460 ? 220 : 204;
    }

    private int modernBankLimitsContentHeight(int width) {
        return modernSectionKpiBlockHeight(width, 3) + 18 + modernLimitsTableHeight(width) + 20;
    }

    private int modernBankGovernanceContentHeight(int width) {
        int main = width >= 760
                ? Math.max(modernGovernanceRosterHeight(width), modernGovernanceActionHeight(width))
                : modernGovernanceRosterHeight(width) + 10 + modernGovernanceActionHeight(width);
        return modernSectionKpiBlockHeight(width, 3) + 18 + main + 20;
    }

    private int modernBankComplianceContentHeight(int width) {
        int main = width >= 760
                ? Math.max(modernComplianceTimelineHeight(width), modernComplianceActionHeight(width))
                : modernComplianceTimelineHeight(width) + 10 + modernComplianceActionHeight(width);
        return modernSectionKpiBlockHeight(width, 3) + 18 + main + 20;
    }

    private int modernBankActionFeedbackHeight() {
        return ClientOwnerPcData.getActionOutputLines().isEmpty() ? 0 : 92;
    }

    private int getModernBankSectionContentHeight(OwnerPcBankDataPayload data, int width) {
        if (data == null) {
            return 180;
        }
        int summaryBlock = modernBankTopSummaryHeight(width) + 18;
        int feedback = modernBankActionFeedbackHeight();
        return switch (activeSection) {
            case OVERVIEW -> modernBankOverviewContentHeight(width);
            case ACCOUNTS -> accountProfileOpen && selectedAccountCard != null
                    ? summaryBlock + (width >= 740 ? 780 : 1030) + feedback
                    : summaryBlock + (width >= 760 ? 350 : 592) + feedback;
            case SAFE -> modernBankSafeContentHeight(data, width) + feedback;
            case PREMISES -> OwnerPcPremisesPanelLayout.layout(
                    width, 0, data.premises().size(), 0).contentHeight();
            case BRANDING -> summaryBlock + 230 + feedback;
            case LIMITS -> modernBankLimitsContentHeight(width) + feedback;
            case GOVERNANCE -> modernBankGovernanceContentHeight(width) + feedback;
            case STAFFING -> modernBankStaffingContentHeight(data, width) + feedback;
            case LENDING -> summaryBlock + (width >= 520 ? 384 : 486) + getModernLendingMarketHeight(width) + 44 + feedback;
            case COMPLIANCE -> modernBankComplianceContentHeight(width) + feedback;
            case BUSINESS, HOURS, PERMISSIONS -> 260;
        };
    }

    private void drawModernShopWindowFrame(GuiGraphics graphics, int left, int top, int right, int bottom) {
        OwnerPcBankAppSummary app = getActiveShopAppSummary();
        int appW = Math.max(1, right - left);
        boolean compact = appW < 980;
        int outerInset = ownerPcOuterInset(appW);
        int sidebarW = ownerPcSidebarWidth(appW, true);
        int sidebarX = left + outerInset;
        int sidebarY = top + 18;
        int sidebarH = Math.max(120, bottom - top - 36);
        int contentX = sidebarX + sidebarW + ownerPcSidebarGap(appW);
        int contentRight = right - outerInset;
        int headerY = top + 18;
        int headerH = 72;
        int contentW = Math.max(1, contentRight - contentX);
        boolean sidebarCard = shouldShowOwnerPcSidebarCard(appW, sidebarW, sidebarH);

        graphics.fill(left - 2, top - 2, right + 2, bottom + 2, 0xEE06111D);
        graphics.fill(left, top, right, bottom, 0xFF07111F);
        graphics.fill(left + 1, top + 1, right - 1, bottom - 1, 0xFF0A1625);
        graphics.fill(left + 1, top + 1, right - 1, top + 2, 0x884A7EA8);

        drawModernBankPanel(graphics, sidebarX, sidebarY, sidebarW, sidebarH, 0xFF0B1727, 0xFF1F3D5E);
        int sidebarTextX = sidebarX + ownerPcSidebarInnerPad(sidebarW);
        int sidebarTextW = sidebarW - (ownerPcSidebarInnerPad(sidebarW) * 2);
        graphics.drawString(this.font, fitToWidth(tr("UBS Shop"), sidebarTextW), sidebarTextX, sidebarY + 22, 0xFFFFFFFF, false);
        graphics.drawString(this.font, fitToWidth(tr("Owner PC shop app"), sidebarTextW), sidebarTextX, sidebarY + 42, 0xFF9FB8D2, false);
        if (sidebarCard) {
            int cardX = sidebarX + 18;
            int cardY = sidebarY + 92;
            int cardW = sidebarW - 36;
            drawModernBankPanel(graphics, cardX, cardY, cardW, 82, 0xFF102238, 0xFF234C73);
            String shopName = app == null || app.bankName() == null || app.bankName().isBlank()
                    ? "Shop unavailable"
                    : app.bankName();
            graphics.drawString(this.font, fitToWidth(tr(shopName), cardW - 24), cardX + 12, cardY + 18, 0xFFFFFFFF, false);
            String role = app == null || app.roleLabel() == null || app.roleLabel().isBlank()
                    ? "Waiting for server"
                    : app.roleLabel();
            String id = activeBankId == null ? "--------" : shortUuid(activeBankId.toString());
            graphics.drawString(this.font, fitToWidth(role + " | " + id, cardW - 24), cardX + 12, cardY + 36, 0xFF9FB8D2, false);
            drawModernStatusChip(graphics, cardX + 12, cardY + 56, app == null ? "LOADING" : app.status());
        }

        drawModernBankPanel(graphics, contentX, headerY, contentW, headerH, 0xFF0F2035, 0xFF244B73);
        int toolbarButtonW = toolbarButtonWForRender(contentW, compact);
        int toolbarGroupW = (toolbarButtonW * 3) + 16;
        int toolbarGroupLeft = contentRight - toolbarGroupW - 14;
        int titleAvailable = Math.max(80, toolbarGroupLeft - contentX - 28);
        graphics.drawString(this.font, fitToWidth(tr(shopSectionTitle(activeSection)), titleAvailable),
                contentX + 28, headerY + 18, 0xFFFFFFFF, false);
        graphics.drawString(this.font, fitToWidth(tr(shopSectionSubtitle(activeSection)), titleAvailable),
                contentX + 30, headerY + 39, 0xFF9FB8D2, false);
        if (app != null && contentW >= 760 && toolbarGroupLeft - contentX > 420) {
            int chipW = modernStatusChipWidth(app.status());
            int metaX = toolbarGroupLeft - chipW - 14;
            if (metaX > contentX + 260) {
                drawModernStatusChip(graphics, metaX, headerY + 17, app.status());
            }
        }

        this.outputPanelX = sectionViewportX;
        this.outputPanelY = sectionViewportY;
        this.outputPanelW = sectionViewportW;
        this.outputPanelH = sectionViewportH;
        clearShopInteractiveHitboxesForRedesign();
        enableScaledScissor(graphics, sectionViewportX, sectionViewportY, sectionViewportX + sectionViewportW, sectionViewportY + sectionViewportH);
        drawFigmaShopSection(graphics, sectionViewportX, sectionViewportY, sectionViewportW, sectionViewportH, compact);
        graphics.disableScissor();

        if (navMaxScroll > 0) {
            drawVerticalScrollbar(
                    graphics,
                    ScrollbarTarget.NAV,
                    true,
                    navViewportX + navViewportW - 4,
                    navViewportY + 1,
                    3,
                    Math.max(10, navViewportH - 2),
                    navScroll,
                    navMaxScroll
            );
        }
        if (sectionMaxScroll > 0) {
            drawVerticalScrollbar(
                    graphics,
                    ScrollbarTarget.SECTION,
                    true,
                    sectionViewportX + sectionViewportW - 4,
                    sectionViewportY + 1,
                    3,
                    Math.max(10, sectionViewportH - 2),
                    sectionScroll,
                    sectionMaxScroll
            );
        }
        if (isShopBusinessFullscreenSection() && isShopBusinessActionModalOpen()) {
            drawShopBusinessModalOverlay(graphics, parseShopBusinessSnapshot(ClientOwnerPcData.getActionOutputLines()));
        }
        if (isShopEmployeeModalOverlayActive()) {
            drawShopEmployeeDetailModalOverlay(graphics);
        }
        if (isShopFinanceModalOverlayActive()) {
            drawShopFinanceModalOverlay(graphics);
        }
        if (isShopHoursModalOverlayActive()) {
            drawShopHoursModalOverlay(graphics);
        }
        if (isShopPermissionModalOverlayActive()) {
            drawShopPermissionModalOverlay(graphics);
        }
        if (isShopDeleteModalOverlayActive()) {
            drawShopDeleteModalOverlay(graphics);
        }
    }

