    private void drawFigmaShopCheckout(GuiGraphics graphics, int x, int y, int width, int height) {
        ShopDashboardSnapshot s = parseShopDashboardSnapshot(ClientOwnerPcData.getActionOutputLines());
        boolean snapshotLoaded = s != null;
        boolean cashierLinked = snapshotLoaded && s.linkedCashiers() > 0;
        boolean terminalBound = snapshotLoaded && s.checkoutTerminalBound();
        int shoppingBags = snapshotLoaded ? Math.max(0, s.shoppingBags()) : 0;
        boolean shopOpen = snapshotLoaded && s.shopOpen();
        boolean settlementReady = snapshotLoaded && s.settlementAccountReady();
        String settlementLabel = snapshotLoaded && s.settlementAccountLabel() != null && !s.settlementAccountLabel().isBlank()
                ? s.settlementAccountLabel()
                : "-";
        boolean bagsReady = snapshotLoaded && shoppingBags > 0;
        int laneH = shopCheckoutLaneHeight(width);
        drawFigmaShopPanel(graphics, x, y, width, laneH, "Checkout lane map",
                "Payment must move through cashier, terminal, settlement account, and bag stock.", ORDER_BOARD_CYAN);
        int gap = 12;
        int nodeCols = width >= 560 ? 4 : width >= 360 ? 2 : 1;
        int nodeW = Math.max(80, (width - 36 - (gap * (nodeCols - 1))) / nodeCols);
        int nodeH = 34;
        int nodeY = y + 42;
        String[][] nodes = {
                {"Cashier NPC", cashierLinked ? "linked" : "missing", cashierLinked ? "OK" : "risk"},
                {"Payment terminal", terminalBound ? "bound" : "unbound", terminalBound ? "OK" : "risk"},
                {"Settlement acct", settlementReady ? settlementLabel : (snapshotLoaded ? "missing" : "unknown"), settlementReady ? "OK" : "risk"},
                {"Shopping bags", bagsReady ? shoppingBags + " ready" : (snapshotLoaded ? "none" : "unknown"), bagsReady ? "OK" : "risk"}
        };
        for (int i = 0; i < nodes.length; i++) {
            int row = i / nodeCols;
            int col = i % nodeCols;
            int nx = x + 18 + (col * (nodeW + gap));
            int ny = nodeY + (row * (nodeH + 10));
            int accent = "OK".equals(nodes[i][2]) ? 0xFF22C55E : ("warn".equals(nodes[i][2]) ? ORDER_BOARD_VIOLET : ORDER_BOARD_RED);
            drawModernBankPanel(graphics, nx, ny, nodeW, nodeH, 0xFF102238, accent);
            graphics.drawString(this.font, fitToWidth(nodes[i][0], nodeW - 12), nx + 6, ny + 6, 0xFFFFFFFF, false);
            graphics.drawString(this.font, fitToWidth(nodes[i][1], nodeW - 12), nx + 6, ny + 18, accent, false);
            if (nodeCols == 4 && i < nodes.length - 1) {
                graphics.fill(nx + nodeW + 2, ny + 16, nx + nodeW + gap - 2, ny + 18, 0x887FB8E8);
            }
        }

        boolean wide = width >= 840;
        int panelY = y + laneH + 14;
        int panelW = wide ? (width - (gap * 2)) / 3 : width;
        int panelH = shopCheckoutPanelHeight(width);
        drawFigmaShopPanel(graphics, x, panelY, panelW, panelH, "Lane readiness checklist", "", 0xFF22C55E);
        String[] checks = {
                (terminalBound ? "[x] " : "[ ] ") + "Checkout terminal is valid",
                (cashierLinked ? "[x] " : "[ ] ") + "Cashier linked to terminal",
                (settlementReady ? "[x] " : "[ ] ") + "Settlement account can receive",
                (bagsReady ? "[x] " : "[ ] ") + "Shopping bags in stockroom",
                (shopOpen ? "[x] " : "[ ] ") + "Shop hours currently open"
        };
        int cy = panelY + 42;
        for (String check : checks) {
            graphics.drawString(this.font, fitToWidth(check, panelW - 24), x + 14, cy, check.contains("[x]") ? 0xFF8DEFA8 : ORDER_BOARD_GOLD, false);
            cy += 20;
        }

        int testX = wide ? x + panelW + gap : x;
        int testY = wide ? panelY : panelY + panelH + gap;
        drawFigmaShopPanel(graphics, testX, testY, panelW, panelH, "Checkout activity", "", ORDER_BOARD_CYAN);
        int testCardW = Math.max(60, (panelW - 34) / 2);
        long checkoutTx = snapshotLoaded ? Math.max(0L, s.cashTxCount()) + Math.max(0L, s.terminalTxCount()) : 0L;
        String basketValue = snapshotLoaded
                ? MoneyText.abbreviateWithDollar(BigDecimal.valueOf(Math.max(0.0D, s.aov())).setScale(2, RoundingMode.HALF_UP))
                : "No scan";
        String bagEstimate = snapshotLoaded ? String.valueOf(shoppingBags) : "Unknown";
        drawMetricCard(graphics, testX + 12, testY + 44, testCardW, 46, "Avg basket", basketValue, 0xFF22C55E);
        drawMetricCard(graphics, testX + 22 + testCardW, testY + 44, testCardW, 46, "Checkout tx", String.valueOf(checkoutTx), ORDER_BOARD_GOLD);
        String checkoutState;
        int checkoutAccent;
        if (!snapshotLoaded) {
            checkoutState = "Refresh checkout data";
            checkoutAccent = ORDER_BOARD_GOLD;
        } else if (!terminalBound) {
            checkoutState = "Checkout terminal missing";
            checkoutAccent = ORDER_BOARD_RED;
        } else if (!cashierLinked) {
            checkoutState = "Cashier terminal link missing";
            checkoutAccent = ORDER_BOARD_RED;
        } else if (!settlementReady) {
            checkoutState = "Settlement account missing";
            checkoutAccent = ORDER_BOARD_RED;
        } else if (!bagsReady) {
            checkoutState = "Shopping bags missing";
            checkoutAccent = ORDER_BOARD_RED;
        } else if (!shopOpen) {
            checkoutState = "Shop is closed";
            checkoutAccent = ORDER_BOARD_GOLD;
        } else {
            checkoutState = "Checkout lane ready";
            checkoutAccent = 0xFF22C55E;
        }
        String hoursText = snapshotLoaded
                ? "Hours: " + (s.shopHoursLabel() == null || s.shopHoursLabel().isBlank() ? "-" : s.shopHoursLabel())
                : "Hours: unknown";
        graphics.drawString(this.font, fitToWidth("Shopping bags: " + bagEstimate + " | " + hoursText, panelW - 28), testX + 14, testY + 98, 0xFFC8DAEC, false);
        drawFigmaShopPill(graphics, testX + 14, testY + 116, Math.max(80, panelW - 28), checkoutState, checkoutAccent);
        graphics.drawString(this.font, fitToWidth("Use diagnostics when the lane state looks wrong.", panelW - 28),
                testX + 14, testY + 146, 0xFF9FB8D2, false);

        int diagX = wide ? testX + panelW + gap : x;
        int diagY = wide ? panelY : testY + panelH + gap;
        drawFigmaShopPanel(graphics, diagX, diagY, panelW, panelH, "Failure diagnostics", "", ORDER_BOARD_RED);
        List<String[]> failures = new ArrayList<>();
        if (!snapshotLoaded) {
            failures.add(new String[]{"No live checkout data - press Refresh", "warn"});
        } else {
            if (!terminalBound) {
                failures.add(new String[]{"No valid checkout terminal - set checkout terminal", "risk"});
            }
            if (!cashierLinked) {
                failures.add(new String[]{"No cashier-terminal link - link a cashier", "risk"});
            }
            if (!settlementReady) {
                failures.add(new String[]{"No settlement account - set one in Finance", "risk"});
            }
            if (!bagsReady) {
                failures.add(new String[]{"No shopping bags - restock stockroom", "warn"});
            }
            if (!shopOpen) {
                failures.add(new String[]{"Shop is closed - update hours or wait", "warn"});
            }
            if (s.outOfStockSlots() > 0) {
                failures.add(new String[]{"Out-of-stock shelves - scan inventory", "warn"});
            }
        }
        if (failures.isEmpty()) {
            failures.add(new String[]{"No checkout blockers detected", "ok"});
        }
        int fy = diagY + 44;
        for (int i = 0; i < failures.size(); i++) {
            String failure = failures.get(i)[0];
            String kind = failures.get(i)[1];
            int accent = "ok".equals(kind) ? 0xFF22C55E : ("risk".equals(kind) ? ORDER_BOARD_RED : ORDER_BOARD_GOLD);
            graphics.fill(diagX + 14, fy - 3, diagX + panelW - 14, fy + 15, 0x6618324E);
            graphics.fill(diagX + 14, fy - 3, diagX + 17, fy + 15, accent);
            graphics.drawString(this.font, fitToWidth(failure, panelW - 38), diagX + 24, fy, 0xFFD6E6F8, false);
            fy += 26;
        }
    }

    private void drawFigmaShopInventory(GuiGraphics graphics, int x, int y, int width, int height) {
        List<String> raw = ClientOwnerPcData.getActionOutputLines();
        List<ShopInventoryShelfCardData> shelves = parseShopInventoryCards(raw);
        List<ShopStockroomItemCardData> stockroomItems = parseShopStockroomCards(raw);
        boolean payloadLoaded = hasShopInventoryPayload(raw);
        boolean stockroomLoaded = hasShopStockroomPayload(raw);
        int toolbarH = width >= 860 ? 100 : 166;
        drawFigmaShopPanel(graphics, x, y, width, toolbarH, "Inventory toolbar",
                "Filter low, sort velocity, search shelf slots, scan shelves, and inspect stockroom sources.", 0xFF22C55E);
        int liveShelves = shelves.size();
        int liveItemRows = 0;
        for (ShopInventoryShelfCardData shelf : shelves) {
            liveItemRows += shelf.items() == null ? 0 : shelf.items().size();
        }
        String payloadLabel = payloadLoaded
                ? "Live scan payload: " + liveShelves + " shelves / " + liveItemRows
                + " item rows / " + stockroomItems.size() + " stockroom rows"
                : "No live scan payload loaded yet";
        int payloadColor = payloadLoaded ? 0xFF8DEFA8 : 0xFFFFB4C2;
        graphics.drawString(this.font, fitToWidth(payloadLabel, Math.max(40, width - 32)),
                x + 14, y + toolbarH - 18, payloadColor, false);

        boolean wide = width >= 860;
        int gap = 12;
        int mapY = y + toolbarH + 16;
        int mapW = wide ? Math.max(280, (width - gap) / 2) : width;
        int mapH = wide ? 352 : 330;
        drawFigmaShopPanel(graphics, x, mapY, mapW, mapH, "Store shelf map",
                "Click a shelf card to inspect and target restock actions.", 0xFF22C55E);
        int cols = Math.max(3, Math.min(5, mapW / 74));
        int cellW = Math.max(48, (mapW - 32 - ((cols - 1) * 8)) / cols);
        int cellH = 30;
        int gridX = x + 16;
        int gridY = mapY + 52;
        int gridW = Math.max(40, mapW - 32);
        int gridH = Math.max(64, mapH - 104);
        shopInventoryMapViewportHitbox = new RectHitbox(gridX, gridY, gridW, gridH);
        int totalRows = shelves.isEmpty() ? 1 : ((shelves.size() + cols - 1) / cols);
        int gridContentH = Math.max(gridH, (totalRows * cellH) + (Math.max(0, totalRows - 1) * 8));
        shopInventoryMapMaxScroll = pixelScrollMax(gridContentH, gridH);
        shopInventoryMapScroll = Math.max(0, Math.min(shopInventoryMapScroll, shopInventoryMapMaxScroll));
        if (!useVirtualScale) {
            enableScaledScissor(graphics, gridX, gridY, gridX + gridW, gridY + gridH);
        }
        if (shelves.isEmpty()) {
            String message = payloadLoaded
                    ? "No shelves match the current filter/search."
                    : "No real shelf payload loaded. Press Scan shelves.";
            graphics.fill(gridX, gridY, gridX + gridW, Math.min(gridY + gridH, gridY + 54), 0x6618324E);
            graphics.fill(gridX, gridY, gridX + 3, Math.min(gridY + gridH, gridY + 54), payloadLoaded ? ORDER_BOARD_GOLD : ORDER_BOARD_RED);
            graphics.drawString(this.font, fitToWidth(message, mapW - 42), gridX + 12, gridY + 10, 0xFFEAF5FF, false);
            graphics.drawString(this.font, fitToWidth("The map only shows shelves returned by the latest server scan.", mapW - 42),
                    gridX + 12, gridY + 26, 0xFF9FB8D2, false);
        }
        for (int i = 0; i < shelves.size(); i++) {
            int row = i / cols;
            int col = i % cols;
            int cellX = gridX + (col * (cellW + 8));
            int cellY = gridY + (row * (cellH + 8)) - shopInventoryMapScroll;
            if (cellY > gridY + gridH || cellY + cellH < gridY) {
                continue;
            }
            ShopInventoryShelfCardData shelf = shelves.get(i);
            int accent = shelf.outOfStock() > 0 ? ORDER_BOARD_RED : shelf.lowStock() > 0 ? ORDER_BOARD_GOLD : 0xFF22C55E;
            graphics.fill(cellX, cellY, cellX + cellW, cellY + cellH, 0x6618324E);
            graphics.fill(cellX, cellY, cellX + cellW, cellY + 1, accent);
            graphics.drawString(this.font, "#" + shelf.index(), cellX + 5, cellY + 5, 0xFFFFFFFF, false);
            String state = shelf.outOfStock() > 0 ? "OUT" : shelf.lowStock() > 0 ? "LOW" : shelf.configuredSlots() <= 0 ? "EMPTY" : "OK";
            graphics.drawString(this.font, state, cellX + 5, cellY + 17, accent, false);
            if (shelf.shelfTarget() != null && !shelf.shelfTarget().isBlank()) {
                visibleShopInventoryShelfCards.add(new ShopInventoryShelfSelectHitbox(cellX, cellY, cellW, cellH, shelf));
            }
        }
        if (!useVirtualScale) {
            graphics.disableScissor();
        }
        drawOutputScrollbar(graphics, gridX, gridY, gridW, gridH, shopInventoryMapScroll, shopInventoryMapMaxScroll);
        int actionStripY = mapY + mapH - 46;
        graphics.fill(x + 12, actionStripY - 4, x + mapW - 12, mapY + mapH - 10, 0xDD102236);

        int detailX = wide ? x + mapW + gap : x;
        int detailY = wide ? mapY : mapY + mapH + gap;
        int detailW = wide ? width - mapW - gap : width;
        int detailH = wide ? mapH : 260;
        drawFigmaShopPanel(graphics, detailX, detailY, detailW, detailH, "Selected shelf details",
                "Position, item model, price, shop-mode stock, and stockroom pickup status.", ORDER_BOARD_CYAN);
        ShopInventoryShelfCardData selected = selectedShopInventoryShelf(shelves);
        if (selected == null && !shelves.isEmpty()) {
            selected = shelves.get(0);
        }
        if (selected == null) {
            graphics.drawString(this.font, "No shop-mode shelf data loaded. Scan shelves to populate the map.",
                    detailX + 14, detailY + 52, 0xFFBBD2EA, false);
        } else {
            graphics.drawString(this.font, fitToWidth("Shelf #" + selected.index() + "  " + selected.dimension() + " " + selected.position(), detailW - 28),
                    detailX + 14, detailY + 50, 0xFFEAF5FF, false);
            int itemY = detailY + 72;
            List<ShopInventoryItemCardData> items = selected.items() == null ? List.of() : selected.items();
            if (items.isEmpty()) {
                graphics.fill(detailX + 14, itemY, detailX + detailW - 14, itemY + 46, 0x6618324E);
                graphics.fill(detailX + 14, itemY, detailX + 17, itemY + 46, ORDER_BOARD_GOLD);
                graphics.drawString(this.font, fitToWidth("This real shelf has no shop-mode item rows.", detailW - 42),
                        detailX + 24, itemY + 10, 0xFFEAF5FF, false);
                graphics.drawString(this.font, fitToWidth("Set a display to shop mode and scan shelves again.", detailW - 42),
                        detailX + 24, itemY + 24, 0xFF9FB8D2, false);
            } else {
                for (int i = 0; i < Math.min(4, items.size()); i++) {
                    ShopInventoryItemCardData item = items.get(i);
                    int rowH = 62;
                    graphics.fill(detailX + 14, itemY, detailX + detailW - 14, itemY + rowH, 0x6618324E);
                    graphics.fill(detailX + 14, itemY, detailX + 17, itemY + rowH, item.stock() == 0 ? ORDER_BOARD_RED : 0xFF22C55E);
                    ItemStack stack = resolveShopInventoryIcon(item.itemId());
                    if (!stack.isEmpty()) {
                        graphics.renderItem(stack, detailX + 22, itemY + 8);
                    }
                    int textX = detailX + 48;
                    int actionButtonW = 50;
                    int actionGap = 4;
                    int removeX = detailX + detailW - actionButtonW - 22;
                    int restockX = removeX - actionButtonW - actionGap;
                    int textW = Math.max(40, restockX - textX - 8);
                    graphics.drawString(this.font, fitToWidth(item.itemName(), textW), textX, itemY + 6, 0xFFFFFFFF, false);
                    graphics.drawString(this.font, fitToWidth(item.itemId(), textW), textX, itemY + 18, 0xFF9FB8D2, false);
                    String stockText = item.stock() < 0 ? "INF" : String.valueOf(Math.max(0, item.stock()));
                    String priceLabel = item.priceCents() <= 0L
                            ? "Free"
                            : MoneyText.abbreviateWithDollar(BigDecimal.valueOf(item.priceCents(), 2));
                    graphics.drawString(this.font,
                            fitToWidth("Slot " + item.slotIndex() + " | " + priceLabel + " | Stock " + stockText
                                    + " | Target " + item.minTarget() + "-" + item.maxTarget(), textW),
                            textX,
                            itemY + 31,
                            0xFFC6DEF6,
                            false);
                    graphics.drawString(this.font,
                            fitToWidth("Stockroom " + (item.stockroomAvailable() < 0 ? "-" : Math.max(0, item.stockroomAvailable()))
                                    + " | Vel " + String.format(Locale.ROOT, "%.2f", Math.max(0.0D, item.velocityPerDay())) + "/d", textW),
                            textX,
                            itemY + 44,
                            0xFFB8D2EA,
                            false);
                    int topButtonY = itemY + 6;
                    int adjustY = itemY + 30;
                    boolean canRestock = item.restockable() && item.targetKey() != null && !item.targetKey().isBlank();
                    boolean canRemove = item.targetKey() != null && !item.targetKey().isBlank() && !selected.creative();
                    drawInlineActionButton(graphics, restockX, topButtonY, actionButtonW, 14,
                            canRestock ? "Restock" : (item.stock() < 0 ? "INF" : "N/A"),
                            canRestock ? 0xFF67BC86 : 0xFF5C7896);
                    drawInlineActionButton(graphics, removeX, topButtonY, actionButtonW, 14,
                            "Remove", canRemove ? 0xFFE09090 : 0xFF5C7896);
                    visibleShopInventoryActions.add(new ShopInventoryActionHitbox(restockX, topButtonY, actionButtonW, 14, "RESTOCK", item, canRestock));
                    visibleShopInventoryActions.add(new ShopInventoryActionHitbox(removeX, topButtonY, actionButtonW, 14, "REMOVE", item, canRemove));
                    boolean canAdjustTargets = !selected.creative() && item.targetKey() != null && !item.targetKey().isBlank();
                    int microW = 14;
                    int minMinusX = restockX;
                    int minPlusX = minMinusX + microW + 2;
                    int maxMinusX = minPlusX + microW + 8;
                    int maxPlusX = maxMinusX + microW + 2;
                    drawInlineActionButton(graphics, minMinusX, adjustY, microW, 12, "-", canAdjustTargets ? 0xFF6BAED6 : 0xFF5C7896);
                    drawInlineActionButton(graphics, minPlusX, adjustY, microW, 12, "+", canAdjustTargets ? 0xFF6BAED6 : 0xFF5C7896);
                    drawInlineActionButton(graphics, maxMinusX, adjustY, microW, 12, "-", canAdjustTargets ? 0xFF8C9DE0 : 0xFF5C7896);
                    drawInlineActionButton(graphics, maxPlusX, adjustY, microW, 12, "+", canAdjustTargets ? 0xFF8C9DE0 : 0xFF5C7896);
                    visibleShopInventoryActions.add(new ShopInventoryActionHitbox(minMinusX, adjustY, microW, 12, "MIN_DEC", item, canAdjustTargets));
                    visibleShopInventoryActions.add(new ShopInventoryActionHitbox(minPlusX, adjustY, microW, 12, "MIN_INC", item, canAdjustTargets));
                    visibleShopInventoryActions.add(new ShopInventoryActionHitbox(maxMinusX, adjustY, microW, 12, "MAX_DEC", item, canAdjustTargets));
                    visibleShopInventoryActions.add(new ShopInventoryActionHitbox(maxPlusX, adjustY, microW, 12, "MAX_INC", item, canAdjustTargets));
                    itemY += rowH + 8;
                }
                if (items.size() > 4) {
                    graphics.drawString(this.font, fitToWidth("Showing 4 of " + items.size() + " item rows. Use search/filter to narrow.", detailW - 28),
                            detailX + 14, Math.min(detailY + detailH - 18, itemY + 2), 0xFF9FB8D2, false);
                }
            }
        }

        int stockY = wide ? mapY + mapH + 16 : detailY + detailH + 16;
        int stockH = Math.max(520, height - (stockY - y));
        drawFigmaShopPanel(graphics, x, stockY, width, stockH, "Stockroom sources",
                "Search live stockroom inventory from claimed source containers and pallets.", ORDER_BOARD_GREEN);
        String stockPayloadLabel = stockroomLoaded
                ? "Live stockroom payload: " + stockroomItems.size() + " item rows"
                : "No stockroom payload in the latest scan. Press Scan shelves or Refresh stockroom.";
        graphics.drawString(this.font, fitToWidth(stockPayloadLabel, Math.max(40, width - 28)),
                x + 14, stockY + 72, stockroomLoaded ? 0xFF8DEFA8 : 0xFFFFB4C2, false);
        int listY = stockY + 92;
        int listH = Math.max(140, stockH - 106);
        drawShopStockroomCardsInSection(graphics, stockroomItems, x + 14, listY, Math.max(80, width - 28), listH,
                stockroomLoaded ? "No stockroom items match the current search." : "Press Scan shelves or Refresh stockroom to load real stockroom data.");
    }

    private boolean hasShopStockroomPayload(List<String> lines) {
        if (lines == null || lines.isEmpty()) {
            return false;
        }
        for (String raw : lines) {
            if (raw == null) {
                continue;
            }
            String line = raw.trim();
            if (line.startsWith("@stockroom.count=") || line.startsWith("@stockroom_item=")) {
                return true;
            }
        }
        return false;
    }

    private int drawShopStockroomCardsInSection(GuiGraphics graphics,
                                                List<ShopStockroomItemCardData> items,
                                                int x,
                                                int y,
                                                int width,
                                                int height,
                                                String emptyMessage) {
        shopStockroomViewportHitbox = new RectHitbox(x, y, width, height);
        int rowHeight = 54;
        int rowGap = 6;
        int contentHeight = getShopStockroomCardsContentHeight(width, height, items == null ? 0 : items.size());
        shopStockroomPanelMaxScroll = pixelScrollMax(contentHeight, height);
        shopStockroomPanelScroll = Math.max(0, Math.min(shopStockroomPanelScroll, shopStockroomPanelMaxScroll));
        if (items == null || items.isEmpty()) {
            graphics.fill(x, y, x + width, y + Math.min(54, height), 0x6618324E);
            graphics.fill(x, y, x + 3, y + Math.min(54, height), ORDER_BOARD_GOLD);
            graphics.drawString(this.font,
                    fitToWidth(emptyMessage == null || emptyMessage.isBlank()
                            ? "No stockroom inventory entries found."
                            : emptyMessage, Math.max(40, width - 24)),
                    x + 12,
                    y + 10,
                    0xFFEAF5FF,
                    false);
            shopStockroomPanelMaxScroll = 0;
            shopStockroomPanelScroll = 0;
            return height;
        }
        if (!useVirtualScale) {
            enableScaledScissor(graphics, x + 1, y + 1, x + width - 1, y + height - 1);
        }
        int cardY = y + 4 - shopStockroomPanelScroll;
        int cardX = x + 5;
        int cardW = Math.max(220, width - 10);
        for (ShopStockroomItemCardData item : items) {
            if (cardY > (y + height) || (cardY + rowHeight) < y) {
                cardY += rowHeight + rowGap;
                continue;
            }
            graphics.fill(cardX - 1, cardY - 1, cardX + cardW + 1, cardY + rowHeight + 1, ORDER_BOARD_BORDER_HI);
            graphics.fill(cardX, cardY, cardX + cardW, cardY + rowHeight, ORDER_BOARD_ROW);
            graphics.fill(cardX, cardY, cardX + cardW, cardY + 2, ORDER_BOARD_GREEN);

            ItemStack iconStack = resolveShopInventoryIcon(item.itemId());
            if (!iconStack.isEmpty()) {
                graphics.renderItem(iconStack, cardX + 8, cardY + 8);
            } else {
                graphics.fill(cardX + 8, cardY + 8, cardX + 24, cardY + 24, 0x663A5578);
            }

            int buttonW = 54;
            int buttonH = 16;
            int locateX = cardX + cardW - buttonW - 10;
            int locateY = cardY + 18;
            drawInlineActionButton(graphics, locateX, locateY, buttonW, buttonH, "Locate", 0xFF67BC86);
            visibleShopStockroomLocateActions.add(new ShopStockroomLocateHitbox(locateX, locateY, buttonW, buttonH, item));

            int textW = Math.max(40, locateX - (cardX + 30) - 8);
            String itemName = item.itemName() == null || item.itemName().isBlank() ? item.itemId() : item.itemName();
            graphics.drawString(this.font, fitToWidth(itemName, textW), cardX + 30, cardY + 6, 0xFFEAF5FF, false);
            graphics.drawString(this.font, fitToWidth("Count " + item.count() + " | Slot " + item.slot() + "/" + item.totalSlots(), textW),
                    cardX + 30, cardY + 17, 0xFFC6DEF6, false);
            graphics.drawString(this.font, fitToWidth(item.inventoryType(), textW), cardX + 30, cardY + 28, 0xFFB8D2EA, false);
            graphics.drawString(this.font, fitToWidth(item.dimension() + " " + item.position(), textW), cardX + 30, cardY + 39, 0xFFB2CAE3, false);
            cardY += rowHeight + rowGap;
        }
        if (!useVirtualScale) {
            graphics.disableScissor();
        }
        drawOutputScrollbar(graphics, x, y, width, height, shopStockroomPanelScroll, shopStockroomPanelMaxScroll);
        return contentHeight;
    }

    private ShopInventoryShelfCardData selectedShopInventoryShelf(List<ShopInventoryShelfCardData> shelves) {
        if (shelves == null || shelves.isEmpty() || shopInventorySelectedShelfTarget == null || shopInventorySelectedShelfTarget.isBlank()) {
            return null;
        }
        for (ShopInventoryShelfCardData shelf : shelves) {
            if (shelf.shelfTarget() != null && shelf.shelfTarget().equalsIgnoreCase(shopInventorySelectedShelfTarget)) {
                return shelf;
            }
        }
        return null;
    }

    private void drawFigmaShopOrders(GuiGraphics graphics, int x, int y, int width, int height) {
        List<String> raw = ClientOwnerPcData.getActionOutputLines();
        if (shopOrderPickerOpen) {
            List<ShopOrderPickCardData> picks = filterShopOrderPickCards(parseShopOrderPickCards(raw));
            int pickerHeaderH = width >= 760 ? 148 : 178;
            drawFigmaShopPanel(graphics, x, y, width, pickerHeaderH, "Shelf item picker",
                    "Choose which shop-mode shelf item should be requested by the courier board.", ORDER_BOARD_CYAN);
            String selected = shopOrderSelectedItemName == null || shopOrderSelectedItemName.isBlank()
                    ? "Selected item: none"
                    : "Selected item: " + shopOrderSelectedItemName;
            graphics.drawString(this.font, fitToWidth(selected, Math.max(40, width - 28)),
                    x + 14, y + pickerHeaderH - 20, 0xFFFFD166, false);
            drawShopOrderManagerCards(graphics, List.of(), List.of(), picks, parseOrderBoardSummary(raw),
                    x, y + pickerHeaderH + 12, width, Math.max(80, height - pickerHeaderH - 18));
            return;
        }
        if (shopOrderPalletPickerOpen) {
            List<ShopOrderPalletCardData> pallets = parseShopOrderPalletCards(raw);
            int pickerHeaderH = width >= 760 ? 116 : 146;
            drawFigmaShopPanel(graphics, x, y, width, pickerHeaderH, "Delivery pallet picker",
                    "Select a labelled pallet for specific-order targeting.", ORDER_BOARD_GREEN);
            String selected = shopOrderSelectedPalletRef == null || shopOrderSelectedPalletRef.isBlank()
                    ? "Selected pallet: none"
                    : "Selected pallet: " + shortUuid(shopOrderSelectedPalletRef);
            graphics.drawString(this.font, fitToWidth(selected, Math.max(40, width - 28)),
                    x + 14, y + pickerHeaderH - 18, 0xFFFFD166, false);
            drawShopOrderManagerCards(graphics, List.of(), pallets, List.of(), parseOrderBoardSummary(raw),
                    x, y + pickerHeaderH + 12, width, Math.max(80, height - pickerHeaderH - 18));
            return;
        }
        if (shopOrderCreateModalOpen) {
            drawFigmaShopPanel(graphics, x, y, width, Math.max(120, height),
                    "Order board paused",
                    "Finish or cancel the delivery-order modal before changing the live courier board.",
                    ORDER_BOARD_GOLD);
            return;
        }

        List<ShopOrderCardData> orders = parseShopOrderCards(raw);
        List<ShopOrderPalletCardData> pallets = parseShopOrderPalletCards(raw);
        int builderH = width >= 760 ? 116 : 148;
        drawFigmaShopPanel(graphics, x, y, width, builderH, "Order launchpad",
                "Create orders in a focused modal, then bind or recover pallet routes below.", ORDER_BOARD_GOLD);
        int selectedY = y + (width >= 760 ? 92 : 122);
        String selectedItemPreview = shopOrderSelectedItemName == null || shopOrderSelectedItemName.isBlank()
                ? "No shelf item selected"
                : shopOrderSelectedItemName;
        String selectedPalletPreview = shopOrderUseSpecificPallet
                ? (shopOrderSelectedPalletRef == null || shopOrderSelectedPalletRef.isBlank()
                ? "Specific pallet: not selected"
                : "Specific pallet: " + shortUuid(shopOrderSelectedPalletRef))
                : "Pallet mode: random available";
        graphics.drawString(this.font,
                fitToWidth(selectedItemPreview + " | " + selectedPalletPreview, Math.max(40, width - 28)),
                x + 14,
                selectedY,
                0xFFFFD166,
                false);

        boolean wide = width >= 900;
        int gap = 12;
        int boardY = y + builderH + gap;
        int colW = wide ? (width - (gap * 2)) / 3 : width;
        int colH = wide ? 178 : Math.max(178,
                Math.max(shopOrderColumnHeight(orders, "OPEN"), shopOrderColumnHeight(orders, "ACTIVE")));
        drawFigmaShopPanel(graphics, x, boardY, colW, colH, "Order setup summary",
                "The create modal owns quantity, reward, timeout, and pallet mode.", ORDER_BOARD_GOLD);
        int setupY = boardY + 46;
        String selectedItem = shopOrderSelectedItemName == null || shopOrderSelectedItemName.isBlank()
                ? "No shelf item selected"
                : shopOrderSelectedItemName;
        String selectedId = shopOrderSelectedItemId == null || shopOrderSelectedItemId.isBlank()
                ? "Use Pick shelf item"
                : shopOrderSelectedItemId;
        graphics.fill(x + 12, setupY, x + colW - 12, setupY + 44, 0x6618324E);
        graphics.fill(x + 12, setupY, x + 15, setupY + 44,
                shopOrderSelectedItemId == null || shopOrderSelectedItemId.isBlank() ? ORDER_BOARD_RED : 0xFF22C55E);
        graphics.drawString(this.font, fitToWidth(selectedItem, colW - 38), x + 22, setupY + 8, 0xFFEAF5FF, false);
        graphics.drawString(this.font, fitToWidth(selectedId, colW - 38), x + 22, setupY + 22, 0xFF9FB8D2, false);
        String modeText = shopOrderUseSpecificPallet
                ? (shopOrderSelectedPalletRef == null || shopOrderSelectedPalletRef.isBlank()
                ? "Specific pallet: not selected"
                : "Specific pallet: " + shopOrderSelectedPalletRef)
                : "Pallet mode: any labeled pallet";
        graphics.drawString(this.font, fitToWidth(modeText, colW - 28), x + 14, setupY + 58, 0xFFFFD166, false);
        int openX = wide ? x + colW + gap : x;
        int openY = wide ? boardY : boardY + colH + gap;
        drawFigmaOrderColumn(graphics, openX, openY, colW, colH, "Open courier board", orders, "OPEN");
        int activeX = wide ? openX + colW + gap : x;
        int activeY = wide ? boardY : openY + colH + gap;
        drawFigmaOrderColumn(graphics, activeX, activeY, colW, colH, "Active and recovery", orders, "ACTIVE");

        int railY = wide ? boardY + colH + gap : activeY + colH + gap;
        int railH = wide ? 284 : (width < 520 ? 392 : 348);
        drawFigmaShopPanel(graphics, x, railY, width, railH, "Pallet routing and recovery",
                "Select an order and a pallet, then bind, clear, cancel, or refresh the board from one place.", ORDER_BOARD_GREEN);
        int assigned = 0;
        int full = 0;
        for (ShopOrderPalletCardData pallet : pallets) {
            if (pallet.assigned()) assigned++;
            if (pallet.full()) full++;
        }
        int statY = railY + 42;
        String[] statLabels = {
                "Ready " + Math.max(0, pallets.size() - full),
                "Full " + full,
                "Assigned " + assigned
        };
        int[] statColors = {0xFF22C55E, full > 0 ? ORDER_BOARD_RED : 0xFF22C55E, ORDER_BOARD_CYAN};
        int statCols = width >= 520 ? 3 : 1;
        int statGap = 8;
        int statW = Math.max(80, (width - 28 - (statGap * (statCols - 1))) / statCols);
        for (int i = 0; i < statLabels.length; i++) {
            int sx = x + 14 + ((i % statCols) * (statW + statGap));
            int sy = statY + ((i / statCols) * 22);
            drawFigmaShopPill(graphics, sx, sy, statW, statLabels[i], statColors[i]);
        }
        String selected = shopOrderSelectedId == null || shopOrderSelectedId.isBlank()
                ? "Selected order: none"
                : "Selected order: " + shortUuid(shopOrderSelectedId);
        String pallet = shopOrderSelectedPalletRef == null || shopOrderSelectedPalletRef.isBlank()
                ? "Selected pallet: none"
                : "Selected pallet: " + shopOrderSelectedPalletRef;
        int summaryY = railY + (statCols == 1 ? 110 : 72);
        graphics.fill(x + 14, summaryY, x + width - 14, summaryY + 36, 0x6618324E);
        graphics.fill(x + 14, summaryY, x + 17, summaryY + 36,
                shopOrderSelectedId == null || shopOrderSelectedId.isBlank() ? ORDER_BOARD_GOLD : ORDER_BOARD_CYAN);
        graphics.drawString(this.font, fitToWidth(selected, Math.max(40, (width - 48) / 2)),
                x + 24, summaryY + 7, 0xFFEAF5FF, false);
        graphics.drawString(this.font, fitToWidth(pallet, Math.max(40, (width - 48) / 2)),
                x + 24, summaryY + 21, 0xFFBBD2EA, false);
        int helperX = x + 24 + Math.max(40, (width - 48) / 2);
        int helperW = Math.max(40, width - (helperX - x) - 24);
        if (helperW >= 120) {
            graphics.drawString(this.font,
                    fitToWidth("Buttons below explain missing selection with toast feedback.", helperW),
                    helperX, summaryY + 14, 0xFF9FB8D2, false);
        }
        int actionCols = width >= 1040 ? 4 : width >= 720 ? 3 : 2;
        int actionRows = (7 + actionCols - 1) / actionCols;
        int actionReserve = (actionRows * 30) + 28;
        int detailY = summaryY + 48;
        if (detailY + 54 < railY + railH - actionReserve) {
            int cardW = Math.max(100, (width - 44) / 3);
            String[][] cards = {
                    {"Pallet source", pallets.isEmpty() ? "No pallets scanned" : pallets.size() + " pallet card(s)", "Use Select pallet for targeted delivery."},
                    {"Recovery", "Clear binding", "Detach a bad route without deleting the order."},
                    {"Courier safety", "Cancel order", "Stops abandoned jobs before they block flow."}
            };
            int[] accents = {ORDER_BOARD_GREEN, ORDER_BOARD_GOLD, ORDER_BOARD_RED};
            for (int i = 0; i < cards.length; i++) {
                int cx = x + 14 + (i * (cardW + 8));
                int cw = i == cards.length - 1 ? x + width - 14 - cx : cardW;
                graphics.fill(cx, detailY, cx + cw, detailY + 46, 0x6618324E);
                graphics.fill(cx, detailY, cx + 3, detailY + 46, accents[i]);
                graphics.drawString(this.font, fitToWidth(cards[i][0], cw - 16), cx + 10, detailY + 7, 0xFFEAF5FF, false);
                graphics.drawString(this.font, fitToWidth(cards[i][1], cw - 16), cx + 10, detailY + 21, accents[i], false);
                graphics.drawString(this.font, fitToWidth(cards[i][2], cw - 16), cx + 10, detailY + 34, 0xFF9FB8D2, false);
            }
        }
    }

    private void drawFigmaOrderColumn(GuiGraphics graphics,
                                      int x,
                                      int y,
                                      int width,
                                      int height,
                                      String title,
                                      List<ShopOrderCardData> orders,
                                      String mode) {
        drawFigmaShopPanel(graphics, x, y, width, height, title, "", ORDER_BOARD_CYAN);
        int rowY = y + 42;
        int drawn = 0;
        for (ShopOrderCardData order : orders == null ? List.<ShopOrderCardData>of() : orders) {
            if (!shopOrderMatchesMode(order, mode)) {
                continue;
            }
            String status = order.status() == null ? "" : order.status().toUpperCase(Locale.ROOT);
            int rowH = 36;
            if (rowY + rowH > y + height - 10) {
                break;
            }
            int accent = status.contains("FAIL") ? ORDER_BOARD_RED : status.contains("ACTIVE") ? 0xFF22C55E : ORDER_BOARD_GOLD;
            graphics.fill(x + 12, rowY, x + width - 12, rowY + rowH, 0x6618324E);
            graphics.fill(x + 12, rowY, x + 15, rowY + rowH, accent);
            graphics.drawString(this.font, fitToWidth(order.itemName() + " x" + order.quantity(), width - 96),
                    x + 22, rowY + 6, 0xFFEAF5FF, false);
            graphics.drawString(this.font, fitToWidth("Reward " + MoneyText.abbreviateWithDollar(BigDecimal.valueOf(order.rewardCents(), 2)),
                    width - 96), x + 22, rowY + 19, 0xFFBBD2EA, false);
            drawFigmaShopPill(graphics, x + width - 78, rowY + 9, 56, status.isBlank() ? "ready" : status, accent);
            visibleShopOrderCards.add(new ShopOrderCardHitbox(x + 12, rowY, width - 24, rowH, order));
            rowY += rowH + 8;
            drawn++;
        }
        if (drawn == 0) {
            graphics.drawString(this.font, "No cards in this lane.", x + 14, rowY + 8, 0xFF9FB8D2, false);
        }
    }

