        graphics.fill(x - 1, y - 1, x + w + 1, y + h + 1, 0xFF3A5E83);
        graphics.fill(x, y, x + w, y + h, 0xFF162B43);
        graphics.fill(x, y, x + w, y + 28, 0xFF244B73);
