        int cardW = Math.max(120, w - 32);
        graphics.fill(x + 16, cardY, x + 16 + cardW, cardY + 32, 0x6618324E);
        graphics.fill(x + 16, cardY, x + 19, cardY + 32,
                shopOrderSelectedItemId == null || shopOrderSelectedItemId.isBlank() ? ORDER_BOARD_RED : 0xFF22C55E);
        String itemLine = shopOrderSelectedItemName == null || shopOrderSelectedItemName.isBlank()
                ? "No shelf item selected"
                : shopOrderSelectedItemName;
        String itemSub = shopOrderSelectedItemId == null || shopOrderSelectedItemId.isBlank()
                ? "Use Pick shelf item to choose real shop-mode stock"
                : shopOrderSelectedItemId;
        graphics.drawString(this.font, fitToWidth(itemLine, cardW - 26), x + 28, cardY + 6, 0xFFEAF5FF, false);
        graphics.drawString(this.font, fitToWidth(itemSub, cardW - 26), x + 28, cardY + 18, 0xFF9FB8D2, false);

        int fieldY = y + 106;
        int innerW = w - 32;
        int gap = 8;
        int fieldW = Math.max(70, (innerW - (gap * 2)) / 3);
        drawShopModalLabel(graphics, x + 16, fieldY, fieldW, "Quantity");
        drawShopModalLabel(graphics, x + 16 + fieldW + gap, fieldY, fieldW, "Courier reward");
        drawShopModalLabel(graphics, x + 16 + ((fieldW + gap) * 2), fieldY, fieldW, "Timeout");

        int routeY = fieldY + 118;
        graphics.fill(x + 16, routeY, x + w - 16, routeY + 34, 0x6618324E);
        graphics.fill(x + 16, routeY, x + 19, routeY + 34, shopOrderUseSpecificPallet ? ORDER_BOARD_GREEN : ORDER_BOARD_CYAN);
        String palletLine = shopOrderUseSpecificPallet
                ? (shopOrderSelectedPalletRef == null || shopOrderSelectedPalletRef.isBlank()
                ? "Specific pallet required but not selected"
                : "Specific pallet: " + shortUuid(shopOrderSelectedPalletRef))
                : "Random available delivery pallet";
        String palletHint = shopOrderUseSpecificPallet
                ? "Use Select pallet to target one labeled pallet."
                : "Courier can use any available labeled pallet.";
