    private void drawFigmaShopHours(GuiGraphics graphics, int x, int y, int width, int height) {
        boolean wide = width >= 820;
        int gap = 12;
        int scheduleW = wide ? Math.max(420, (width * 2) / 3) : width;
        int panelH = wide ? 410 : 398;
        String serverZone = shopHoursServerZoneDescription();
        String localZone = shopHoursLocalZoneDescription();
        drawFigmaShopPanel(graphics, x, y, scheduleW, panelH, "Weekly shop schedule",
                "Authoritative timezone: " + serverZone, ORDER_BOARD_GOLD);
        String activeZoneLine = shopHoursClockView == ShopHoursClockView.SERVER
                ? "Showing server time. Edit buttons change this authoritative schedule."
                : "Showing your local time: " + localZone + ". Editing still uses server time.";
        graphics.drawString(this.font, fitToWidth(activeZoneLine, scheduleW - 28),
                x + 14, y + 44, shopHoursClockView == ShopHoursClockView.SERVER ? 0xFFFFD166 : 0xFF64D8FF, false);
        List<ShopHoursDayData> days = getDisplayedShopHoursDays();
        int rowY = y + 70;
        int editW = 46;
        int editX = x + scheduleW - editW - 14;
        int labelW = Math.min(132, Math.max(92, scheduleW / 6));
        int labelX = Math.max(x + 138, editX - labelW - 8);
        int barX = x + 64;
        int barW = Math.max(90, labelX - barX - 12);
        for (ShopHoursDayData day : days) {
            int dayColor = day.current() ? 0xFFFFD166 : 0xFFEAF5FF;
            graphics.drawString(this.font, day.label(), x + 18, rowY, dayColor, false);
            graphics.fill(barX, rowY + 3, barX + barW, rowY + 9, 0xFF07111F);
            int startRatio = Math.max(0, Math.min(1440, day.openMinute()));
            int endRatio = Math.max(0, Math.min(1440, day.closeMinute()));
            boolean allDay = startRatio == endRatio;
            int start = allDay ? 0 : (barW * startRatio) / 1440;
            int end = allDay ? barW : (barW * endRatio) / 1440;
            if (end < start) {
                graphics.fill(barX + start, rowY + 3, barX + barW, rowY + 9, 0xFF22C55E);
                graphics.fill(barX, rowY + 3, barX + end, rowY + 9, 0xFF22C55E);
            } else {
                graphics.fill(barX + start, rowY + 3, barX + Math.max(start + 3, end), rowY + 9, 0xFF22C55E);
            }
            graphics.drawString(this.font, fitToWidth(day.openLabel() + " - " + day.closeLabel(), labelW),
                    labelX, rowY, 0xFF8DEFA8, false);
            rowY += 28;
        }
        int guideY = rowY + 6;
        drawShopHoursGuide(graphics, barX, guideY, barW);
        graphics.drawString(this.font, fitToWidth("Schedule actions", scheduleW - 28),
                x + 14, y + panelH - 84, 0xFFBBD2EA, false);
        graphics.drawString(this.font, fitToWidth("Closed access controls whether accepted couriers can enter the stockroom while the shop is closed.",
                        scheduleW - 28),
                x + 14, y + panelH - 24, 0xFF9FB8D2, false);
        int sideX = wide ? x + scheduleW + gap : x;
        int sideY = wide ? y : y + panelH + gap;
        int sideW = wide ? width - scheduleW - gap : width;
        drawFigmaShopPanel(graphics, sideX, sideY, sideW, panelH, "Lighting automation",
                "Main floor and stockroom modes can diverge while couriers stay safe.", 0xFF22C55E);
        boolean lightingEnabled = "true".equalsIgnoreCase(formValues.getOrDefault(SHOP_LIGHTING_ENABLED_KEY, "true"));
        boolean excludeStockroom = "true".equalsIgnoreCase(formValues.getOrDefault(SHOP_LIGHTING_EXCLUDE_STOCKROOM_KEY, "false"));
        boolean deliverersAllowed = "true".equalsIgnoreCase(formValues.getOrDefault(SHOP_HOURS_DELIVERER_STOCKROOM_ACCESS_KEY, "false"));
        int lightLevel = parseBoundedInt(formValues.get(SHOP_LIGHTING_LEVEL_KEY), 15, 1, 15);
        String[] cards = {
                "Main floor  " + formatLightingModeLabel(formValues.getOrDefault(SHOP_LIGHTING_MAIN_MODE_KEY, "OPEN_HOURS"), false)
                        + "  " + (lightingEnabled ? "enabled" : "disabled"),
                "Stockroom  " + formatLightingModeLabel(formValues.getOrDefault(SHOP_LIGHTING_STOCKROOM_MODE_KEY, "OPEN_HOURS"), false)
                        + "  " + (excludeStockroom ? "independent" : "follows main"),
                "Light level  " + lightLevel + " / 15  managed light blocks",
                "Closed courier access  " + (deliverersAllowed ? "Allowed" : "Denied") + "  stockroom rule"
        };
        int cardY = sideY + 54;
        for (int i = 0; i < cards.length; i++) {
            int accent = i == 0 && !lightingEnabled ? ORDER_BOARD_RED : i == 3 && !deliverersAllowed ? ORDER_BOARD_GOLD : 0xFF22C55E;
            graphics.fill(sideX + 14, cardY, sideX + sideW - 14, cardY + 42, 0x6618324E);
            graphics.fill(sideX + 14, cardY, sideX + 17, cardY + 42, accent);
            graphics.drawString(this.font, fitToWidth(cards[i], sideW - 36), sideX + 24, cardY + 13, 0xFFEAF5FF, false);
            cardY += 50;
        }
        graphics.drawString(this.font, fitToWidth("Lighting controls", sideW - 28),
                sideX + 14, sideY + 250, 0xFFBBD2EA, false);
    }

    private void drawShopHoursGuide(GuiGraphics graphics, int barX, int y, int barW) {
        graphics.fill(barX, y, barX + barW, y + 1, 0x663A5578);
        for (int hour = 0; hour <= 24; hour++) {
            int hx = barX + (barW * hour) / 24;
            int tickH = hour % 6 == 0 ? 7 : 4;
            graphics.fill(hx, y - tickH, hx + 1, y + tickH, 0x887FB8E8);
            if (hour < 24) {
                String label = formatHourGuideLabel(hour);
                int labelY = y + 9 + ((hour & 1) * 8);
                drawScaledShopText(graphics, label, hx - 7, labelY, 0.48F, 0xFF9FB8D2);
            }
        }
    }

    private String formatHourGuideLabel(int hour24) {
        int safe = Math.floorMod(hour24, 24);
        int hour12 = safe % 12;
        if (hour12 == 0) {
            hour12 = 12;
        }
        return hour12 + (safe >= 12 ? " PM" : " AM");
    }

    private void drawScaledShopText(GuiGraphics graphics, String text, int x, int y, float scale, int color) {
        if (text == null || text.isBlank()) {
            return;
        }
        float safeScale = Math.max(0.35F, Math.min(1.0F, scale));
        graphics.pose().pushPose();
        graphics.pose().scale(safeScale, safeScale, 1.0F);
        graphics.drawString(this.font, text, Math.round(x / safeScale), Math.round(y / safeScale), color, false);
        graphics.pose().popPose();
    }

    private void drawFigmaShopPermissions(GuiGraphics graphics, int x, int y, int width, int height) {
        List<ShopPermissionMemberCardData> members = filterShopPermissionMemberCards(parseShopPermissionMemberCards(ClientOwnerPcData.getActionOutputLines()));
        boolean wide = width >= 820;
        int gap = 12;
        int matrixW = wide ? Math.max(420, (width * 2) / 3) : width;
        int panelH = wide ? Math.max(270, height - 10) : compactShopPermissionsPanelHeight(members.size());
        drawFigmaShopPanel(graphics, x, y, matrixW, panelH, "Permission matrix",
                "Rows are player cards; columns are OWNER, MANAGER, BUILDER, STAFF, and Guest groups.", ORDER_BOARD_CYAN);
        String[] roles = {"Owner", "Manager", "Builder", "Staff", "Guest"};
        int tableX = x + 14;
        int tableY = y + 86;
        int tableW = matrixW - 28;
        graphics.fill(tableX, tableY, tableX + tableW, tableY + 24, 0x6618324E);
        graphics.drawString(this.font, "Player", tableX + 8, tableY + 8, 0xFF9FB8D2, false);
        int roleStartX = tableX + Math.max(100, tableW / 3);
        int roleW = Math.max(36, (tableX + tableW - roleStartX - 8) / roles.length);
        for (int i = 0; i < roles.length; i++) {
            graphics.drawString(this.font, fitToWidth(roles[i], roleW - 2), roleStartX + (i * roleW), tableY + 8, 0xFF9FB8D2, false);
        }
        int rowY = tableY + 34;
        if (members.isEmpty()) {
            graphics.fill(tableX, rowY, tableX + tableW, rowY + 48, 0x6618324E);
            graphics.fill(tableX, rowY, tableX + 3, rowY + 48, ORDER_BOARD_GOLD);
            graphics.drawString(this.font, fitToWidth("No real permission rows loaded.", tableW - 24),
                    tableX + 12, rowY + 10, 0xFFEAF5FF, false);
            graphics.drawString(this.font, fitToWidth("Press Refresh permissions or grant a selected player role.", tableW - 24),
                    tableX + 12, rowY + 26, 0xFF9FB8D2, false);
        }
        int drawnMembers = 0;
        for (int r = 0; r < members.size(); r++) {
            ShopPermissionMemberCardData member = members.get(r);
            if (wide && rowY + 28 > y + panelH - 14) {
                break;
            }
            graphics.fill(tableX, rowY, tableX + tableW, rowY + 28, 0x6618324E);
            graphics.drawString(this.font, fitToWidth(member.playerName().isBlank() ? shortUuid(member.playerId()) : member.playerName(), roleStartX - tableX - 14),
                    tableX + 8, rowY + 6, 0xFFEAF5FF, false);
            for (int i = 0; i < roles.length; i++) {
                boolean active = isPermissionRoleActive(member, roles[i]);
                int bx = roleStartX + (i * roleW) + 8;
                graphics.fill(bx, rowY + 7, bx + 12, rowY + 19, active ? 0xFF22C55E : 0xFF102238);
                graphics.fill(bx, rowY + 7, bx + 12, rowY + 8, 0xFF244B73);
            }
            visibleShopPermissionMemberCards.add(new ShopPermissionMemberCardHitbox(tableX, rowY, tableW, 28, member));
            rowY += 38;
            drawnMembers++;
        }
        if (members.size() > drawnMembers) {
            graphics.drawString(this.font, fitToWidth("Scroll to reveal " + (members.size() - drawnMembers) + " more permission row(s).", tableW),
                    tableX, Math.max(tableY + 34, y + panelH - 18), 0xFFFFD166, false);
        }
        int sideX = wide ? x + matrixW + gap : x;
        int sideY = wide ? y : y + panelH + gap;
        int sideW = wide ? width - matrixW - gap : width;
        drawFigmaShopPanel(graphics, sideX, sideY, sideW, panelH, "Selected player",
                "Selected player cards drive grant/update and removal actions.", 0xFF22C55E);
        String selected = formValues.getOrDefault(SHOP_PERMISSIONS_SELECTED_PLAYER_NAME_KEY, "").trim();
        if (selected.isBlank()) {
            selected = "No player selected";
        }
        graphics.fill(sideX + 14, sideY + 54, sideX + sideW - 14, sideY + 102, 0x6618324E);
        graphics.fill(sideX + 14, sideY + 54, sideX + 17, sideY + 102, 0xFF22C55E);
        graphics.drawString(this.font, fitToWidth(selected, sideW - 40), sideX + 26, sideY + 72, 0xFFEAF5FF, false);
    }

    private boolean isPermissionRoleActive(ShopPermissionMemberCardData member, String roleLabel) {
        if (member == null || roleLabel == null || roleLabel.isBlank()) {
            return false;
        }
        String normalized = roleLabel.trim().toUpperCase(Locale.ROOT);
        if ("OWNER".equals(normalized)) {
            return member.owner();
        }
        if ("GUEST".equals(normalized)) {
            return member.guest();
        }
        String assigned = member.assignedRole() == null ? "" : member.assignedRole().trim().toUpperCase(Locale.ROOT);
        return !assigned.isBlank() && assigned.equals(normalized);
    }

    private void drawFigmaShopCompliance(GuiGraphics graphics, int x, int y, int width, int height) {
        List<String> rawLines = ClientOwnerPcData.getActionOutputLines();
        ShopDashboardSnapshot snapshot = parseShopDashboardSnapshot(rawLines);
        boolean wide = width >= 820;
        int gap = 12;
        int timelineW = wide ? Math.max(420, (width * 2) / 3) : width;
        List<String[]> events = buildShopComplianceEvents(snapshot, rawLines);
        int panelH = wide ? Math.max(270, height - 10) : compactShopCompliancePanelHeight(events.size());
        drawFigmaShopPanel(graphics, x, y, timelineW, panelH, "Shop audit timeline",
                "Warnings explain what to fix before changing or deleting shop infrastructure.", ORDER_BOARD_RED);
        int rowY = y + 56;
        for (String[] event : events) {
            int accent = "green".equals(event[3]) ? 0xFF22C55E : "blue".equals(event[3]) ? ORDER_BOARD_CYAN : ORDER_BOARD_RED;
            graphics.fill(x + 14, rowY, x + timelineW - 14, rowY + 40, 0x6618324E);
            graphics.fill(x + 14, rowY, x + 17, rowY + 40, accent);
            graphics.drawString(this.font, event[0], x + 26, rowY + 8, accent, false);
            graphics.drawString(this.font, fitToWidth(event[1], timelineW - 120), x + 88, rowY + 6, 0xFFEAF5FF, false);
            graphics.drawString(this.font, fitToWidth(event[2], timelineW - 120), x + 88, rowY + 20, 0xFF9FB8D2, false);
            rowY += 54;
        }
        int consoleX = wide ? x + timelineW + gap : x;
        int consoleY = wide ? y : y + panelH + gap;
        int consoleW = wide ? width - timelineW - gap : width;
        drawFigmaShopPanel(graphics, consoleX, consoleY, consoleW, panelH, "Maintenance console",
                "Settings are controlled through focused buttons and confirmation fields.", ORDER_BOARD_GOLD);
        OwnerPcBankAppSummary app = getActiveShopAppSummary();
        String shopId = app == null || app.bankId() == null ? "--------" : shortUuid(app.bankId().toString());
        boolean linked = snapshot != null && snapshot.checkoutTerminalBound();
        String shopTypeLabel = snapshot == null ? "Unknown" : prettifyShopType(snapshot.shopType());
        drawMetricCard(graphics, consoleX + 14, consoleY + 54, Math.max(80, (consoleW - 40) / 3), 48, "Shop type",
                shopTypeLabel, ORDER_BOARD_VIOLET);
        drawMetricCard(graphics, consoleX + 22 + ((consoleW - 40) / 3), consoleY + 54, Math.max(80, (consoleW - 40) / 3), 48, "Terminal",
                linked ? "linked" : "missing", linked ? ORDER_BOARD_CYAN : ORDER_BOARD_RED);
        drawMetricCard(graphics, consoleX + 30 + (((consoleW - 40) / 3) * 2), consoleY + 54, Math.max(80, (consoleW - 40) / 3), 48, "ID",
                shopId, 0xFF93C5FD);
    }

    private List<String[]> buildShopComplianceEvents(ShopDashboardSnapshot snapshot, List<String> rawLines) {
        List<String[]> events = new ArrayList<>();
        if (snapshot == null) {
            events.add(new String[]{"Info", "No live dashboard payload loaded", "Press Refresh to run a real audit.", "blue"});
            return events;
        }
        if (snapshot.claimRegions() <= 0) {
            events.add(new String[]{"Risk", "Shop plot is not claimed", "Use the Claiming panel before relying on checkout readiness.", "red"});
        } else {
            events.add(new String[]{"Ready", "Shop plot claimed", snapshot.claimRegions() + " claimed region(s) protect store operations.", "green"});
        }
        if (!snapshot.checkoutTerminalBound()) {
            events.add(new String[]{"Risk", "No valid checkout terminal", "Use Checkout to bind a payment terminal inside the plot.", "red"});
        } else if (snapshot.linkedCashiers() <= 0) {
            events.add(new String[]{"Risk", "No cashier-terminal link", "Use Staff to link at least one cashier to a terminal.", "red"});
        } else {
            events.add(new String[]{"Ready", "Cashier terminal route linked", snapshot.linkedCashiers() + "/" + Math.max(0, snapshot.cashiers()) + " cashier link(s) online.", "green"});
        }
        if (snapshot.stockroomRegions() <= 0) {
            events.add(new String[]{"Risk", "No stockroom claim", "Inventory restock and webshop delivery recovery need a stockroom.", "red"});
        } else {
            events.add(new String[]{"Ready", "Stockroom claim exists", snapshot.stockroomRegions() + " stockroom region(s) can feed shelves.", "green"});
        }
        if (snapshot.outOfStockSlots() > 0) {
            events.add(new String[]{"Risk", snapshot.outOfStockSlots() + " shelf slot(s) out of stock", "Open Inventory and restock or lower targets.", "red"});
        } else if (snapshot.lowStockSlots() > 0) {
            events.add(new String[]{"Info", snapshot.lowStockSlots() + " low-stock shelf slot(s)", "Restock soon to keep readiness high.", "blue"});
        } else {
            events.add(new String[]{"Ready", "No shelf stock blockers", "Current dashboard reports shelves as healthy.", "green"});
        }
        if (events.size() < 5 && rawLines != null) {
            for (String raw : rawLines) {
                if (events.size() >= 5) {
                    break;
                }
                if (raw == null || raw.isBlank() || raw.trim().startsWith("@")) {
                    continue;
                }
                String line = raw.trim();
                String lower = line.toLowerCase(Locale.ROOT);
                if (lower.contains("compliance") || lower.contains("warning") || lower.contains("risk") || lower.contains("failed")) {
                    events.add(new String[]{"Info", fitToWidth(line, 90), "Server report line; refresh after fixing related blocker.", "blue"});
                }
            }
        }
        return events;
    }

    private int shopSectionAccent(Section section) {
        if (section == null) {
            return 0xFF22C55E;
        }
        return switch (section) {
            case OVERVIEW -> 0xFF22C55E;
            case BRANDING -> ORDER_BOARD_CYAN;
            case LIMITS -> 0xFF22C55E;
            case GOVERNANCE -> ORDER_BOARD_GOLD;
            case STAFFING -> ORDER_BOARD_CYAN;
            case LENDING -> ORDER_BOARD_GREEN;
            case BUSINESS -> ORDER_BOARD_VIOLET;
            case HOURS -> ORDER_BOARD_GOLD;
            case PERMISSIONS -> 0xFF93C5FD;
            case COMPLIANCE -> ORDER_BOARD_RED;
            case ACCOUNTS -> ORDER_BOARD_CYAN;
            case SAFE, PREMISES -> ORDER_BOARD_CYAN;
        };
    }

