    private void drawVerticalScrollbar(GuiGraphics graphics,
                                       ScrollbarTarget target,
                                       boolean rebuildOnDrag,
                                       int x,
                                       int y,
                                       int width,
                                       int height,
                                       int position,
                                       int maxPosition) {
        if (height <= 0 || width <= 0) {
            return;
        }
        graphics.fill(x, y, x + width, y + height, 0x5535475F);
        if (maxPosition <= 0) {
            graphics.fill(x, y, x + width, y + height, 0xAA9FC4E8);
            return;
        }
        int thumbH = Math.max(10, height / 5);
        int travel = Math.max(1, height - thumbH);
        int thumbY = y + (int) (travel * (position / (float) maxPosition));
        graphics.fill(x, thumbY, x + width, thumbY + thumbH, 0xCC9FC4E8);
        registerScrollbar(target, x, y, width, height, position, maxPosition, thumbH, rebuildOnDrag);
    }

    private void registerScrollbar(ScrollbarTarget target,
                                   int x,
                                   int y,
                                   int width,
                                   int height,
                                   int position,
                                   int maxPosition,
                                   int thumbHeight,
                                   boolean rebuildOnDrag) {
        if (target == null || maxPosition <= 0 || width <= 0 || height <= 0) {
            return;
        }
        int safeThumb = Math.max(1, Math.min(height, thumbHeight));
        int safePosition = Math.max(0, Math.min(position, maxPosition));
        visibleScrollbars.put(target, new ScrollbarHitbox(
                target,
                x,
                y,
                width,
                height,
                safePosition,
                maxPosition,
                safeThumb,
                rebuildOnDrag
        ));
    }

    private boolean tryStartScrollbarDrag(double mouseX, double mouseY) {
        if (visibleScrollbars.isEmpty()) {
            return false;
        }
        for (ScrollbarHitbox hitbox : visibleScrollbars.values()) {
            if (hitbox == null || !hitbox.contains(mouseX, mouseY)) {
                continue;
            }
            int targetPosition = getScrollbarPositionFromMouse(hitbox, mouseY);
            if (setScrollbarPosition(hitbox.target(), targetPosition) && hitbox.rebuildOnDrag()) {
                rebuildWidgets();
            }
            activeScrollbarDrag = hitbox.target();
            return true;
        }
        return false;
    }

    private boolean updateScrollbarDrag(double mouseY) {
        if (activeScrollbarDrag == null) {
            return false;
        }
        ScrollbarHitbox hitbox = visibleScrollbars.get(activeScrollbarDrag);
        if (hitbox == null || hitbox.maxPosition() <= 0) {
            return false;
        }
        int targetPosition = getScrollbarPositionFromMouse(hitbox, mouseY);
        if (setScrollbarPosition(hitbox.target(), targetPosition) && hitbox.rebuildOnDrag()) {
            rebuildWidgets();
        }
        return true;
    }

    private int getScrollbarPositionFromMouse(ScrollbarHitbox hitbox, double mouseY) {
        int travel = Math.max(1, hitbox.height() - hitbox.thumbHeight());
        double relative = mouseY - hitbox.y() - (hitbox.thumbHeight() / 2.0D);
        int raw = (int) Math.round((relative / (double) travel) * hitbox.maxPosition());
        return Math.max(0, Math.min(hitbox.maxPosition(), raw));
    }

    private boolean setScrollbarPosition(ScrollbarTarget target, int value) {
        int next = Math.max(0, value);
        return switch (target) {
            case NAV -> {
                int clamped = Math.min(navMaxScroll, next);
                if (clamped == navScroll) {
                    yield false;
                }
                navScroll = clamped;
                yield true;
            }
            case SECTION -> {
                int clamped = Math.min(sectionMaxScroll, next);
                if (clamped == sectionScroll) {
                    yield false;
                }
                sectionScroll = clamped;
                yield true;
            }
            case OUTPUT, LENDING_MARKET -> {
                int clamped = Math.min(computeOutputMaxScroll(), next);
                if (clamped == outputScroll) {
                    yield false;
                }
                outputScroll = clamped;
                yield true;
            }
            case NOTEPAD -> {
                List<String> lines = buildNotepadLayout(Math.max(1, notepadAreaW - 14)).lines();
                int visible = Math.max(1, (notepadAreaH - 8) / LINE_HEIGHT);
                int maxScroll = Math.max(0, lines.size() - visible);
                int clamped = Math.min(maxScroll, next);
                if (clamped == notepadScroll) {
                    yield false;
                }
                notepadScroll = clamped;
                yield true;
            }
            case PAINT_CONTROLS -> {
                int clamped = Math.min(paintControlsMaxScroll, next);
                if (clamped == paintControlsScroll) {
                    yield false;
                }
                paintControlsScroll = clamped;
                yield true;
            }
            case SHOP_MANAGER -> {
                int clamped = Math.min(shopManagerMaxScroll, next);
                if (clamped == shopManagerScroll) {
                    yield false;
                }
                shopManagerScroll = clamped;
                yield true;
            }
            case SYSTEM_MONITOR -> {
                int clamped = Math.min(systemMonitorMaxScroll, next);
                if (clamped == systemMonitorScroll) {
                    yield false;
                }
                systemMonitorScroll = clamped;
                yield true;
            }
            case ORDER_BOARD -> {
                int clamped = Math.min(orderBoardMaxScroll, next);
                if (clamped == orderBoardScroll) {
                    yield false;
                }
                orderBoardScroll = clamped;
                yield true;
            }
            case WEBSHOP -> {
                int clamped = Math.min(webshopMaxScroll, next);
                if (clamped == webshopScroll) {
                    yield false;
                }
                webshopScroll = clamped;
                yield true;
            }
        };
    }

    private void drawOutputPanel(GuiGraphics graphics,
                                 OwnerPcBankDataPayload data,
                                 int x,
                                 int y,
                                 int width,
                                 int height) {
        if (width < 20 || height < 20) {
            return;
        }
        this.outputPanelX = x;
        this.outputPanelY = y;
        this.outputPanelW = width;
        this.outputPanelH = height;

        if (isActiveShopApp()) {
            int accent = shopSectionAccent(activeSection);
            graphics.fill(x - 1, y - 1, x + width + 1, y + height + 1, 0xFF244B73);
            graphics.fill(x, y, x + width, y + height, 0xF00B1C2D);
            graphics.fill(x + 1, y + 1, x + width - 1, y + 2, accent);
            graphics.fill(x + 1, y + 2, x + 3, y + height - 1, 0xAA38BDF8);
        } else {
            graphics.fill(x - 1, y - 1, x + width + 1, y + height + 1, 0xFF2A3F5B);
            graphics.fill(x, y, x + width, y + height, 0xF0132538);
            graphics.fill(x + 1, y + 1, x + width - 1, y + 2, 0x66BFDFFF);
        }
        visibleMarketActions.clear();
        visibleShopEmployeeActions.clear();
        visibleShopOwnerAccountCards.clear();
        visibleShopPermissionMemberCards.clear();
        visibleShopVaultAdjustActions.clear();
        visibleShopInventoryActions.clear();
        visibleShopInventoryShelfCards.clear();
        visibleShopStockroomLocateActions.clear();
        visibleShopOrderCards.clear();
        visibleShopOrderPalletCards.clear();
        visibleShopOrderPickCards.clear();
        visibleShopLevelRoadmapNodes.clear();
        visibleKpiCards.clear();
        marketConfirmAcceptHitbox = null;
        marketConfirmCancelHitbox = null;
        accountProfileCopyIdHitbox = null;
        shopLevelRoadmapScrollbarTrackHitbox = null;
        shopLevelRoadmapScrollbarThumbHitbox = null;
        shopLevelRoadmapModalCloseHitbox = null;
        int bodyX = x + OUTPUT_PANEL_INSET;
        int bodyY = y + OUTPUT_PANEL_INSET;
        int bodyW = Math.max(1, width - (OUTPUT_PANEL_INSET * 2));
        int bodyH = Math.max(1, height - (OUTPUT_PANEL_INSET * 2));

        if (isActiveShopApp()) {
            drawShopOutputPanel(graphics, bodyX, bodyY, bodyW, bodyH);
            return;
        }

        if (activeSection == Section.OVERVIEW
                && overviewDetailOpen
                && isOverviewMetricsAction(overviewDetailAction)
                && data != null) {
            visibleAccountCards.clear();
            int contentHeight = getOverviewDashboardContentHeight(bodyW, bodyH);
            int maxScroll = pixelScrollMax(contentHeight, bodyH);
            outputScroll = Math.max(0, Math.min(outputScroll, maxScroll));
            enableScaledScissor(graphics, bodyX, bodyY, bodyX + bodyW, bodyY + bodyH);
            drawOverviewDashboard(graphics, data, overviewDetailAction, bodyX, bodyY - outputScroll, bodyW, contentHeight);
            graphics.disableScissor();
            drawOutputScrollbar(graphics, x, y, width, height, outputScroll, maxScroll);
            return;
        }

        if (activeSection == Section.OVERVIEW
                && overviewDetailOpen
                && data != null) {
            enableScaledScissor(graphics, bodyX, bodyY, bodyX + bodyW, bodyY + bodyH);
            if ("SHOW_ACCOUNTS".equalsIgnoreCase(overviewDetailAction) && accountProfileOpen && selectedAccountCard != null) {
                visibleAccountCards.clear();
                int contentHeight = getAccountProfileContentHeight(bodyW, bodyH);
                int maxScroll = pixelScrollMax(contentHeight, bodyH);
                outputScroll = Math.max(0, Math.min(outputScroll, maxScroll));
                drawAccountProfilePanel(graphics, selectedAccountCard, bodyX, bodyY - outputScroll, bodyW, contentHeight);
                graphics.disableScissor();
                drawOutputScrollbar(graphics, x, y, width, height, outputScroll, maxScroll);
                return;
            }
            drawOverviewListCards(graphics, overviewDetailAction, bodyX, bodyY, bodyW, bodyH);
            graphics.disableScissor();
            return;
        }

        visibleAccountCards.clear();

        if (activeSection == Section.LENDING && lendingMarketOpen) {
            drawLendingMarketPanel(graphics, bodyX, bodyY, bodyW, bodyH);
            return;
        }

        InputHelp help = getFocusedInputHelp();
        if (help != null && activeSection == Section.LIMITS) {
            int contentHeight = getInputHelpContentHeight(help, bodyW, bodyH);
            int maxScroll = pixelScrollMax(contentHeight, bodyH);
            outputScroll = Math.max(0, Math.min(outputScroll, maxScroll));
            enableScaledScissor(graphics, bodyX, bodyY, bodyX + bodyW, bodyY + bodyH);
            drawInputHelpPanel(graphics, help, bodyX, bodyY - outputScroll, bodyW, contentHeight);
            graphics.disableScissor();
            drawOutputScrollbar(graphics, x, y, width, height, outputScroll, maxScroll);
            return;
        }
        if (help != null && activeSection == Section.LENDING && !lendingMarketOpen) {
            int contentHeight = getInputHelpContentHeight(help, bodyW, bodyH);
            int maxScroll = pixelScrollMax(contentHeight, bodyH);
            outputScroll = Math.max(0, Math.min(outputScroll, maxScroll));
            enableScaledScissor(graphics, bodyX, bodyY, bodyX + bodyW, bodyY + bodyH);
            drawInputHelpPanel(graphics, help, bodyX, bodyY - outputScroll, bodyW, contentHeight);
            graphics.disableScissor();
            drawOutputScrollbar(graphics, x, y, width, height, outputScroll, maxScroll);
            return;
        }

        List<String> lines = getWrappedOutputLines();
        if (lines.isEmpty()) {
            if (activeSection == Section.OVERVIEW && !overviewDetailOpen) {
                lines = wrapLines(
                        List.of(
                                "Select an overview tool above to open details.",
                                "The selected view will load here in full-screen panel mode."
                        ),
                        Math.max(1, width - 14)
                );
            } else if (activeSection == Section.OVERVIEW) {
                lines = wrapLines(
                        List.of(
                                "Loading " + overviewActionLabel(overviewDetailAction) + "...",
                                "Press Refresh if this view does not update."
                        ),
                        Math.max(1, width - 14)
                );
            } else {
                lines = wrapLines(
                        List.of(
                                "Action output appears here.",
                                "Use the controls above to run a command for this section."
                        ),
                        Math.max(1, width - 14)
                );
            }
        }

        int available = Math.max(1, bodyH / LINE_HEIGHT);
        int maxScroll = Math.max(0, lines.size() - available);
        outputScroll = Math.max(0, Math.min(outputScroll, maxScroll));

        enableScaledScissor(graphics, bodyX, bodyY, bodyX + bodyW, bodyY + bodyH);
        int lineY = bodyY;
        for (int i = 0; i < available; i++) {
            int idx = outputScroll + i;
            if (idx >= lines.size()) {
                break;
            }
            graphics.drawString(this.font, lines.get(idx), bodyX, lineY, 0xFFE7F3FF, false);
            lineY += LINE_HEIGHT;
        }
        graphics.disableScissor();

        drawOutputScrollbar(graphics, x, y, width, height, outputScroll, maxScroll);
    }

    private void drawOutputScrollbar(GuiGraphics graphics,
                                     int x,
                                     int y,
                                     int width,
                                     int height,
                                     int position,
                                     int maxPosition) {
        if (maxPosition <= 0) {
            return;
        }
        drawVerticalScrollbar(
                graphics,
                ScrollbarTarget.OUTPUT,
                false,
                x + width - 5,
                y + 3,
                3,
                Math.max(10, height - 6),
                position,
                maxPosition
        );
    }

    private void drawShopBusinessTypePanel(GuiGraphics graphics, int x, int y, int width, int height) {
        visibleShopBusinessActions.clear();
        visibleShopBusinessHelp.clear();
        visibleKpiCards.clear();

        ShopBusinessSnapshot snapshot = parseShopBusinessSnapshot(ClientOwnerPcData.getActionOutputLines());
        OwnerPcShopBusinessPanelLayout.Layout layout = getShopBusinessPanelLayout(snapshot, width, height, 0);
        drawShopBusinessPanelContent(graphics, snapshot, x, y, layout);
    }

    private void drawShopBusinessPanelContent(GuiGraphics graphics,
                                              ShopBusinessSnapshot snapshot,
                                              int x,
                                              int y,
                                              OwnerPcShopBusinessPanelLayout.Layout layout) {
        String type = normalizeBusinessShopType(snapshot.shopType());
        OwnerPcShopBusinessPanelLayout.Rect header = layout.header();
        drawBusinessHeader(graphics, snapshot, x + header.x(), y + header.y(), header.width(),
                header.height(), layout.dimensions().headerControls());
        drawBusinessMetricRow(graphics, snapshot, x, y, layout.metrics());

        OwnerPcShopBusinessPanelLayout.Rect main = layout.main();
        OwnerPcShopBusinessPanelLayout.Rect actions = layout.actions();
        int mainX = x + main.x();
        int mainY = y + main.y();
        int actionX = x + actions.x();
        int actionY = y + actions.y();

        if ("FRANCHISE".equals(type)) {
            drawFranchiseBusinessPanel(graphics, snapshot, mainX, mainY, main.width());
            drawFranchiseActionCenter(graphics, snapshot, actionX, actionY, actions.width(), actions.height());
        } else if ("CORPORATE_RETAIL_CHAIN".equals(type)) {
            drawCorporateBusinessPanel(graphics, snapshot, mainX, mainY, main.width());
            drawCorporateActionCenter(graphics, snapshot, actionX, actionY, actions.width(), actions.height());
        } else {
            drawIndependentBusinessPanel(graphics, snapshot, mainX, mainY, main.width());
            drawIndependentActionCenter(graphics, snapshot, actionX, actionY, actions.width(), actions.height());
        }
    }

    private void drawBusinessMetricRow(GuiGraphics graphics,
                                       ShopBusinessSnapshot snapshot,
                                       int x,
                                       int y,
                                       List<OwnerPcShopBusinessPanelLayout.Rect> cards) {
        String type = normalizeBusinessShopType(snapshot.shopType());
        String[] labels;
        String[] values;
        String[] subtitles;
        int[] accents;
        if ("FRANCHISE".equals(type)) {
            labels = new String[]{"Type", "Due Fees", "License Capacity", "Royalty Cycle"};
            values = new String[]{
                    "Franchise",
                    formatBusinessCents(snapshot.payableCents()),
                    snapshot.franchiseActiveLicenses() + " / " + snapshot.franchiseLicenseCapacity(),
                    formatBusinessCents(Math.max(snapshot.accruedCents(), snapshot.payableCents()))
            };
            subtitles = new String[]{
                    "Brand license model",
                    snapshot.payableCents() > 0L ? "Payment required" : "No overdue royalties",
                    "Next slot at level " + Math.max(1, snapshot.franchiseUnlockLevel()),
                    "Next payout estimate"
            };
            accents = new int[]{0xFF9EC7FF, 0xFFE2A66A, 0xFF7DD6B2, 0xFFC7B8FF};
        } else if ("CORPORATE_RETAIL_CHAIN".equals(type)) {
            labels = new String[]{"Type", "Due Fees", "Branches", "Overhead"};
            values = new String[]{
                    "Corporate",
                    formatBusinessCents(snapshot.payableCents()),
                    snapshot.corporateActiveBranches() + " / " + snapshot.corporateBranchCapacity(),
                    formatBusinessPercent(snapshot.corporateOverheadPercent())
            };
            subtitles = new String[]{
                    "Centralized chain model",
                    snapshot.payableCents() > 0L ? "Payment required" : "No overdue overhead",
                    "Owned branch links",
                    "Gross sales charge"
            };
            accents = new int[]{0xFF82C8FF, 0xFFE2A66A, 0xFF8BE3CF, 0xFFFFB98B};
        } else {
            labels = new String[]{"Type", "Due Fees", "Royalties", "Autonomy"};
            values = new String[]{
                    "Independent",
                    formatBusinessCents(snapshot.payableCents()),
                    "0%",
                    "Full control"
            };
            subtitles = new String[]{
                    "Local operator model",
                    snapshot.payableCents() > 0L ? "Payment required" : "No business fees",
                    "No brand payments",
                    "Pricing and stock"
            };
            accents = new int[]{0xFF78D6A4, 0xFFE2A66A, 0xFF7DD6B2, 0xFF9EC7FF};
        }

        for (int i = 0; i < labels.length; i++) {
            OwnerPcShopBusinessPanelLayout.Rect card = cards.get(i);
            drawBusinessKpiCard(
                    graphics,
                    x + card.x(),
                    y + card.y(),
                    card.width(),
                    card.height(),
                    labels[i],
                    values[i],
                    subtitles[i],
                    accents[i],
                    businessMetricDescription(labels[i], normalizeBusinessShopType(snapshot.shopType()))
            );
        }
    }

    private void drawBusinessHeader(GuiGraphics graphics,
                                    ShopBusinessSnapshot snapshot,
                                    int x,
                                    int y,
                                    int width,
                                    int height,
                                    OwnerPcShopBusinessPanelLayout.HeaderControls controls) {
        String type = normalizeBusinessShopType(snapshot.shopType());
        int accent = businessAccentColor(type);
        drawFigmaShopPanel(
                graphics,
                x,
                y,
                width,
                height,
                "Business type",
                businessTypeSubtitle(type),
                accent
        );

        OwnerPcShopBusinessPanelLayout.Rect summary = controls.typeSummary();
        int summaryX = x + summary.x();
        int summaryY = y + summary.y();
        graphics.fill(summaryX, summaryY, summaryX + summary.width(), summaryY + summary.height(), 0x6618324E);
        graphics.fill(summaryX, summaryY, summaryX + 3, summaryY + summary.height(), accent);
        String typeLabel = prettifyShopType(type);
        String levelLabel = "Level " + Math.max(1, snapshot.level());
        int levelWidth = Math.min(Math.max(38, this.font.width(levelLabel)), Math.max(38, summary.width() / 3));
        graphics.drawString(this.font,
                fitToWidth(typeLabel, Math.max(30, summary.width() - levelWidth - 28)),
                summaryX + 12,
                summaryY + 8,
                ORDER_BOARD_TEXT,
                false);
        graphics.drawString(this.font,
                fitToWidth(levelLabel, levelWidth),
                Math.max(summaryX + 12, summaryX + summary.width() - levelWidth - 10),
                summaryY + 8,
                accent,
                false);
        String status = snapshot.payableCents() > 0L
                ? formatBusinessCents(snapshot.payableCents()) + " due"
                : snapshot.freeReclass() ? "Free type migration available" : "No business fees due";
        graphics.drawString(this.font,
                fitToWidth(status, Math.max(30, summary.width() - 24)),
                summaryX + 12,
                summaryY + 25,
                ORDER_BOARD_MUTED,
                false);

        drawBusinessHeaderButton(graphics, x, y, controls.refresh(), "Refresh", "REFRESH_TYPE", true,
                ORDER_BOARD_CYAN, "");
        drawBusinessHeaderButton(graphics, x, y, controls.payFees(), "Pay fees", "PAY_FEES_MODAL",
                snapshot.payableCents() > 0L, ORDER_BOARD_GOLD, "No shop-type fees are due right now.");
        drawBusinessHeaderButton(graphics, x, y, controls.changeType(), "Change type", "CHANGE_TYPE", true,
                ORDER_BOARD_VIOLET, "");
    }

    private void drawBusinessHeaderButton(GuiGraphics graphics,
                                          int panelX,
                                          int panelY,
                                          OwnerPcShopBusinessPanelLayout.Rect button,
                                          String label,
                                          String action,
                                          boolean enabled,
                                          int accent,
                                          String disabledReason) {
        drawBusinessButton(
                graphics,
                panelX + button.x(),
                panelY + button.y(),
                button.width(),
                button.height(),
                label,
                action,
                enabled,
                accent,
                disabledReason
        );
    }

    private void drawBusinessKpiCard(GuiGraphics graphics,
                                     int x,
                                     int y,
                                     int width,
                                     int height,
                                      String label,
                                      String value,
                                      String subtitle,
                                      int accent,
                                      String tooltipDescription) {
        graphics.fill(x - 1, y - 1, x + width + 1, y + height + 1, 0xFF2E4D6D);
        graphics.fill(x, y, x + width, y + height, 0x8A1A304A);
        graphics.fill(x, y, x + width, y + 2, accent);
        graphics.drawString(this.font, fitToWidth(label, width - 12), x + 6, y + 7, 0xFFC6DEF7, false);
        graphics.drawString(this.font, fitToWidth(value, width - 12), x + 6, y + 22, 0xFFFFFFFF, false);
        graphics.drawString(this.font, fitToWidth(subtitle, width - 12), x + 6, y + 42, 0xFF9FB8D2, false);
        if (tooltipDescription != null && !tooltipDescription.isBlank()) {
            visibleKpiCards.add(new KpiCardHitbox(x, y, width, height, label, value, tooltipDescription));
        }
    }

    private void drawBusinessButton(GuiGraphics graphics,
                                    int x,
                                    int y,
                                    int width,
                                    int height,
                                    String label,
                                    String action,
                                    boolean enabled,
                                    int accent) {
        drawBusinessButton(graphics, x, y, width, height, label, action, enabled, accent, "");
    }

    private void drawBusinessButton(GuiGraphics graphics,
                                    int x,
                                    int y,
                                    int width,
                                    int height,
                                    String label,
                                    String action,
                                    boolean enabled,
                                    int accent,
                                    String disabledReason) {
        int border = enabled ? accent : ORDER_BOARD_BORDER;
        int fill = enabled ? ORDER_BOARD_CARD : 0xFF263344;
        graphics.fill(x, y, x + width, y + height, border);
        graphics.fill(x + 1, y + 1, x + width - 1, y + height - 1, fill);
        graphics.fill(x + 3, y + 4, x + 5, y + height - 4, enabled ? accent : 0xFF8798AA);
        graphics.drawString(
                this.font,
                fitToWidth(label, width - 18),
                x + 11,
                y + Math.max(2, (height - 8) / 2),
                enabled ? ORDER_BOARD_TEXT : 0xFFAAB6C4,
                false
        );
        if (action != null && !action.isBlank()) {
            visibleShopBusinessActions.add(new ShopBusinessActionHitbox(
                    x,
                    y,
                    width,
                    height,
                    action,
                    enabled,
                    enabled ? "" : disabledReason
            ));
        }
        registerShopBusinessHelp(
                x,
                y,
                width,
                height,
                label,
                businessActionHelpDescription(action, label, enabled, disabledReason)
        );
    }

    private void drawBusinessActionCard(GuiGraphics graphics,
                                        int x,
                                        int y,
                                        int width,
                                        int height,
                                        String title,
                                        String subtitle,
                                        String action,
                                        boolean enabled,
                                        int accent) {
        drawBusinessActionCard(graphics, x, y, width, height, title, subtitle, action, enabled, accent, "");
    }

    private void drawBusinessActionCard(GuiGraphics graphics,
                                        int x,
                                        int y,
                                        int width,
                                        int height,
                                        String title,
                                        String subtitle,
                                        String action,
                                        boolean enabled,
                                        int accent,
                                        String disabledReason) {
        int border = enabled ? ORDER_BOARD_BORDER_HI : ORDER_BOARD_BORDER;
        graphics.fill(x, y, x + width, y + height, border);
        graphics.fill(x + 1, y + 1, x + width - 1, y + height - 1, enabled ? ORDER_BOARD_ROW : 0xFF202E3D);
        graphics.fill(x + 1, y + 1, x + 4, y + height - 1, enabled ? accent : 0xFF7B8797);
        graphics.drawString(this.font, fitToWidth(title, width - 18), x + 11, y + 8, enabled ? ORDER_BOARD_TEXT : 0xFFB3BECA, false);
        graphics.drawString(this.font, fitToWidth(subtitle, width - 18), x + 11, y + 22, enabled ? ORDER_BOARD_MUTED : 0xFF8D9BA9, false);
        if (action != null && !action.isBlank()) {
            visibleShopBusinessActions.add(new ShopBusinessActionHitbox(
                    x,
                    y,
                    width,
                    height,
                    action,
                    enabled,
                    enabled ? "" : disabledReason
            ));
        }
        registerShopBusinessHelp(
                x,
                y,
                width,
                height,
                title,
                businessActionHelpDescription(action, title, enabled, disabledReason) + " " + subtitle
        );
    }

    private String businessActionHelpDescription(String action, String label, boolean enabled, String disabledReason) {
        if (!enabled && disabledReason != null && !disabledReason.isBlank()) {
            return disabledReason.trim();
        }
        String normalized = action == null ? "" : action.trim().toUpperCase(Locale.ROOT);
        if (normalized.startsWith("OFFER_DETAILS:")) {
            return "Opens this franchise market offer with full terms and available actions.";
        }
        if (normalized.startsWith("CONTRACT_DATE_DAY:")) {
            return "Selects this day as the final active day of the franchise contract.";
        }
        if (normalized.startsWith("CONTRACT_DATE_QUICK:")) {
            return "Quickly sets the contract end date by this many days from today.";
        }
        return switch (normalized) {
            case "REFRESH_TYPE" -> "Reloads the shop type report from the server, including fees, capacities, offers, and contracts.";
            case "CHANGE_TYPE" -> "Opens the shop settings area where the shop can be reclassified.";
            case "PAY_FEES_MODAL", "PAY_FEES" -> "Opens a confirmation modal for due business-type fees.";
            case "PAY_FEES_CONFIRM" -> "Pays the currently due royalties, marketing fees, overhead, or type fees.";
            case "PUBLISH_MODAL" -> "Opens the franchise offer form for selling your brand rights to another shop.";
            case "PUBLISH_CONFIRM" -> "Publishes the configured franchise offer to the market or direct buyer.";
            case "CONTRACT_DATE_MODAL" -> "Opens the contract end-date picker for this franchise offer.";
            case "CONTRACT_DATE_PREV_MONTH", "CONTRACT_DATE_NEXT_MONTH" -> "Moves the contract date picker to another month.";
            case "CONTRACT_DATE_CLEAR" -> "Makes this offer create an indefinite legacy-style contract with no automatic end date.";
            case "CONTRACT_DATE_SAVE" -> "Keeps the selected contract end date and returns to the publish form.";
            case "CONTRACT_DATE_BACK" -> "Returns to the publish form without changing the selected contract end date.";
            case "ACCEPT_MODAL" -> "Opens the market-offer acceptance form for buying into another franchise brand.";
            case "ACCEPT_CONFIRM" -> "Accepts the entered franchise offer and creates a contract if requirements are met.";
            case "ACCEPT_SELECTED_OFFER" -> "Accepts the selected franchise market offer without retyping its UUID.";
            case "COPY_SELECTED_OFFER_ID" -> "Copies the selected franchise offer UUID to your clipboard.";
            case "CANCEL_MODAL" -> "Opens the cancellation form for one of your own active franchise offers.";
            case "CANCEL_OFFER_CONFIRM" -> "Cancels the entered franchise offer UUID so buyers can no longer accept it.";
            case "BRANCH_MODAL" -> "Opens corporate branch linking controls for owned Corporate Retail Chain shops.";
            case "CORPORATE_ADD_CONFIRM" -> "Links the entered owned shop UUID as a corporate branch.";
            case "CORPORATE_REMOVE_CONFIRM" -> "Removes the entered shop UUID from this corporate branch network.";
            case "MODAL_CLOSE" -> "Closes this modal without sending a business action.";
            default -> label == null || label.isBlank()
                    ? "Business type control."
                    : "Runs the " + label + " business type control.";
        };
    }

    private String businessCardHelpDescription(String title) {
        String normalized = title == null ? "" : title.trim().toLowerCase(Locale.ROOT);
        return switch (normalized) {
            case "franchise brand" -> "Brand-owner area for publishing offers, monitoring royalty flow, and tracking franchise license capacity.";
            case "franchisee licenses" -> "Shows shops that bought or accepted your franchise rights. More license slots unlock through leveling.";
            case "franchise market offers" -> "Shows available franchise offers you can accept when buying into another brand.";
            case "corporate hq control" -> "Corporate control area for branch capacity, overhead, and centralized chain reporting.";
            case "branch network" -> "Shows owned shops linked into this Corporate Retail Chain.";
            case "independent operator" -> "Independent shops keep pricing and stocking autonomy without royalties or corporate overhead.";
            case "growth roadmap" -> "Summarizes how this shop can grow or switch into a more networked business type.";
            case "action center" -> "Contains only the actions that apply to the currently selected shop business type.";
            default -> "Business type panel section.";
        };
    }

    private void drawBusinessMiniCard(GuiGraphics graphics,
                                      int x,
                                      int y,
                                      int width,
                                      int height,
                                      String title,
                                      String subtitle,
                                      int accent) {
        graphics.fill(x, y, x + width, y + height, ORDER_BOARD_BORDER_HI);
        graphics.fill(x + 1, y + 1, x + width - 1, y + height - 1, ORDER_BOARD_ROW);
        graphics.fill(x + 1, y + 1, x + 4, y + height - 1, accent);
        graphics.drawString(this.font, fitToWidth(title, width - 18), x + 10, y + 8, ORDER_BOARD_TEXT, false);
        graphics.drawString(this.font, fitToWidth(subtitle, width - 18), x + 10, y + 22, ORDER_BOARD_MUTED, false);
    }

    private void drawBusinessLabeledProgress(GuiGraphics graphics,
                                             int x,
                                             int y,
                                             int width,
                                             String label,
                                             String value,
                                             double ratio,
                                             int accent) {
        double clamped = Math.max(0.0D, Math.min(1.0D, ratio));
        graphics.drawString(this.font, fitToWidth(label, Math.max(40, width / 2)), x, y, ORDER_BOARD_MUTED, false);
        graphics.drawString(this.font, fitToWidth(value, Math.max(40, width / 2)), x + Math.max(0, width - this.font.width(fitToWidth(value, Math.max(40, width / 2)))), y, ORDER_BOARD_TEXT, false);
        int barY = y + 15;
        graphics.fill(x, barY, x + width, barY + 5, ORDER_BOARD_BORDER);
        graphics.fill(x + 1, barY + 1, x + width - 1, barY + 4, ORDER_BOARD_BG);
        int fillW = (int) Math.round((width - 2) * clamped);
        if (fillW > 0) {
            graphics.fill(x + 1, barY + 1, x + 1 + fillW, barY + 4, accent);
        }
    }

    private boolean hasDirectFranchiseOffer(ShopBusinessSnapshot snapshot) {
        if (snapshot == null || snapshot.franchiseOffers() == null) {
            return false;
        }
        for (ShopFranchiseOfferData offer : snapshot.franchiseOffers()) {
            if (offer != null && offer.visibility() != null
                    && offer.visibility().toUpperCase(Locale.ROOT).contains("DIRECT")) {
                return true;
            }
        }
        return false;
    }

    private boolean hasAcceptedFranchiseContract(ShopBusinessSnapshot snapshot) {
        return snapshot != null
                && ((snapshot.acceptedBrand() != null && !snapshot.acceptedBrand().isBlank())
                || (snapshot.acceptedRequirements() != null && !snapshot.acceptedRequirements().isEmpty()));
    }

    private String firstFranchiseRules(ShopBusinessSnapshot snapshot) {
        if (snapshot != null && snapshot.franchiseOffers() != null) {
            for (ShopFranchiseOfferData offer : snapshot.franchiseOffers()) {
                if (offer != null && offer.rules() != null && !offer.rules().isBlank()) {
                    return offer.rules().trim();
                }
            }
        }
        return "Approved shelf layout / local pricing allowed";
    }

    private void drawFranchiseBusinessPanel(GuiGraphics graphics, ShopBusinessSnapshot snapshot, int x, int y, int width) {
        int cursorY = y;
        int brandH = getFranchiseBrandSectionHeight(width);
        drawBusinessCard(graphics, x, cursorY, width, brandH, "Franchise Brand", 0xFFE1A84E);
        drawWrappedBusinessText(graphics, List.of(
                "Brand owner view: publish offers, track fees, and watch royalty health."
        ), x + 12, cursorY + 25, width - 24, 0xFFAAC7DE, 2);
        int progressY = cursorY + 48;
        int progressW = Math.max(80, Math.min(width - 24, width >= 560 ? (width - 48) / 2 : width - 24));
        double licenseRatio = snapshot.franchiseLicenseCapacity() <= 0
                ? 0.0D
                : snapshot.franchiseActiveLicenses() / (double) Math.max(1, snapshot.franchiseLicenseCapacity());
        drawBusinessLabeledProgress(graphics,
                x + 12,
                progressY,
                progressW,
                "License slots",
                snapshot.franchiseActiveLicenses() + " used / " + snapshot.franchiseLicenseCapacity() + " total",
                licenseRatio,
                0xFFE1A84E);
        progressY += 28;
        long royaltyCycleCents = Math.max(snapshot.accruedCents(), snapshot.payableCents());
        drawBusinessLabeledProgress(graphics,
                x + 12,
                progressY,
                progressW,
                "Royalty flow",
                formatBusinessCents(royaltyCycleCents) + " next cycle",
                royaltyCycleCents <= 0L ? 0.0D : 0.58D,
                0xFF72DCA5);
        int infoY = cursorY + 104;
        int infoGap = 8;
        if (width >= 520) {
            int cardW = Math.max(90, (width - 24 - (infoGap * 2)) / 3);
            drawBusinessMiniCard(graphics, x + 12, infoY, cardW, 42,
                    snapshot.franchiseOffers().isEmpty() ? "Open offer: none" : "Open offer: " + snapshot.franchiseOffers().get(0).brand(),
                    snapshot.franchiseOffers().isEmpty() ? "Publish from action center" : formatBusinessCents(snapshot.franchiseOffers().get(0).upfrontCents())
                            + " upfront / " + formatBusinessPercent(snapshot.franchiseOffers().get(0).royaltyPercent()) + " royalty",
                    0xFFE1A84E);
            drawBusinessMiniCard(graphics, x + 12 + cardW + infoGap, infoY, cardW, 42,
                    "Direct invite",
                    hasDirectFranchiseOffer(snapshot) ? "Target buyer UUID attached" : "No direct buyer attached",
                    0xFFC7B8FF);
            drawBusinessMiniCard(graphics, x + 12 + ((cardW + infoGap) * 2), infoY, cardW, 42,
                    "Brand rules",
                    firstFranchiseRules(snapshot),
                    0xFF7CC8F5);
        } else {
            int stackW = width - 24;
            drawBusinessMiniCard(graphics, x + 12, infoY, stackW, 32,
                    snapshot.franchiseOffers().isEmpty() ? "Open offer: none" : "Open offer: " + snapshot.franchiseOffers().get(0).brand(),
                    snapshot.franchiseOffers().isEmpty() ? "Publish from action center" : formatBusinessCents(snapshot.franchiseOffers().get(0).upfrontCents())
                            + " upfront / " + formatBusinessPercent(snapshot.franchiseOffers().get(0).royaltyPercent()) + " royalty",
                    0xFFE1A84E);
            drawBusinessMiniCard(graphics, x + 12, infoY + 38, stackW, 32,
                    "Direct invite",
                    hasDirectFranchiseOffer(snapshot) ? "Target buyer UUID attached" : "No direct buyer attached",
                    0xFFC7B8FF);
            drawBusinessMiniCard(graphics, x + 12, infoY + 76, stackW, 32,
                    "Brand rules",
                    firstFranchiseRules(snapshot),
                    0xFF7CC8F5);
        }
        cursorY += brandH + 10;

        if (hasAcceptedFranchiseContract(snapshot)) {
            int acceptedH = getFranchiseAcceptedContractSectionHeight(width, snapshot.acceptedRequirements().size());
            drawBusinessCard(graphics, x, cursorY, width, acceptedH, "My Brand Contract", 0xFF7DD6B2);
            String brand = snapshot.acceptedBrand() == null || snapshot.acceptedBrand().isBlank()
                    ? "Accepted franchise"
                    : snapshot.acceptedBrand().trim();
            drawWrappedBusinessText(graphics, List.of(
                    brand + " | Royalty " + formatBusinessPercent(snapshot.acceptedRoyaltyPercent())
                            + " | Marketing " + formatBusinessPercent(snapshot.acceptedMarketingPercent()),
                    "Ends: " + formatFranchiseContractExpiry(snapshot.acceptedContractExpiresAtMillis()),
                    snapshot.acceptedRequirementsCompliant()
                            ? "Brand shelf rules are currently satisfied."
                            : "Missing shelf rules can add a " + formatBusinessPercent(snapshot.acceptedNonCompliancePenaltyPercent()) + " penalty on sales."
            ), x + 12, cursorY + 25, width - 24, 0xFFCBE2F7, 3);
            drawFranchiseRequirementProgressCards(
                    graphics,
                    snapshot.acceptedRequirements(),
                    x + 12,
                    cursorY + 57,
                    width - 24,
                    Math.max(34, acceptedH - 65),
                    snapshot.acceptedRequirementsCompliant(),
                    snapshot.acceptedMissingSummary(),
                    snapshot.acceptedNonCompliancePenaltyPercent()
            );
            cursorY += acceptedH + 10;
        }

        int networkH = getBusinessListSectionHeight(width, Math.max(1, snapshot.franchiseContracts().size()), 62);
        drawBusinessCard(graphics, x, cursorY, width, networkH, "Franchisee Licenses", 0xFFC7B8FF);
        drawWrappedBusinessText(graphics, List.of(
                "Player franchisees, market buyers, direct invites, and future capacity appear here."
        ), x + 12, cursorY + 25, width - 24, 0xFFAAC7DE, 2);
        if (snapshot.franchiseContracts().isEmpty()) {
            drawWrappedBusinessText(graphics, List.of(
                    "No active franchisees yet.",
                    "When other shops accept your offer, their contracts appear here as horizontal cards."
            ), x + 12, cursorY + 47, width - 24, 0xFFCBE2F7, 4);
        } else {
            drawFranchiseContractCards(graphics, snapshot.franchiseContracts(), x + 12, cursorY + 47, width - 24);
        }
        cursorY += networkH + 10;

        int marketH = getFranchiseMarketSectionHeight(width, snapshot.franchiseOffers().size(), width >= 360 && !snapshot.franchiseOffers().isEmpty());
        drawBusinessCard(graphics, x, cursorY, width, marketH, "Franchise Market Offers", 0xFF7DD6B2);
        drawWrappedBusinessText(graphics, List.of(
                "Accepting another brand is separate from publishing your own offer."
        ), x + 12, cursorY + 25, width - 24, 0xFFAAC7DE, 2);
        if (snapshot.franchiseOffers().isEmpty()) {
            drawWrappedBusinessText(graphics, List.of(
                    "No market offers are visible right now.",
                    "Refresh the type system after another franchisor publishes an offer."
            ), x + 12, cursorY + 47, width - 24, 0xFFCBE2F7, 4);
        } else {
            drawFranchiseOfferCards(graphics, snapshot.franchiseOffers(), x + 12, cursorY + 47, width - 24);
            if (width >= 360) {
                drawBusinessButton(graphics,
                        x + width - 158,
                        cursorY + marketH - 34,
                        146,
                        23,
                        "Open accept offer",
                        "ACCEPT_MODAL",
                        true,
                        0xFF69C6FF);
            }
        }
    }

