    private void drawShopBusinessModalInputLabels(GuiGraphics graphics, int modalX, int modalY, int modalW) {
        if (!isShopBusinessActionModalOpen()
                || shopBusinessActionModal == ShopBusinessActionModal.PAY_SHOP_TYPE_FEES
                || shopBusinessActionModal == ShopBusinessActionModal.FRANCHISE_MARKET_OFFER
                || shopBusinessActionModal == ShopBusinessActionModal.FRANCHISE_CONTRACT_DATE) {
            return;
        }
        int innerX = modalX + 12;
        int innerW = Math.max(80, modalW - 24);
        int gap = 8;
        if (shopBusinessActionModal == ShopBusinessActionModal.PUBLISH_FRANCHISE_OFFER) {
            int fieldY = modalY + 48;
            drawShopBusinessModalInputLabel(graphics, innerX, fieldY, innerW, "Brand name",
                    "Name buyers see on franchise offers and contracts.");
            fieldY += 34;
            int third = Math.max(60, (innerW - (gap * 2)) / 3);
            drawShopBusinessModalInputLabel(graphics, innerX, fieldY, third, "Upfront fee",
                    "One-time amount the buyer pays when accepting this franchise offer.");
            drawShopBusinessModalInputLabel(graphics, innerX + third + gap, fieldY, third, "Royalty %",
                    "Recurring percentage charged from franchisee revenue.");
            drawShopBusinessModalInputLabel(graphics, innerX + ((third + gap) * 2), fieldY, third, "Marketing %",
                    "Extra recurring brand or marketing percentage charged to franchisees.");
            fieldY += 34;
            drawShopBusinessModalInputLabel(graphics, innerX, fieldY, innerW, "Brand rules",
                    "Operating notes or rules shown to buyers before they accept your offer.");
            fieldY += 34;
            drawShopBusinessModalInputLabel(graphics, innerX, fieldY, innerW, "Direct buyer UUID",
                    "Optional buyer UUID. Leave blank for a public market offer.");
            return;
        }
        int fieldY = modalY + 56;
        if (shopBusinessActionModal == ShopBusinessActionModal.ACCEPT_FRANCHISE_OFFER) {
            drawShopBusinessModalInputLabel(graphics, innerX, fieldY, innerW, "Franchise offer UUID",
                    "Offer ID from the market list. Accepting it buys into another brand.");
        } else if (shopBusinessActionModal == ShopBusinessActionModal.CANCEL_FRANCHISE_OFFER) {
            drawShopBusinessModalInputLabel(graphics, innerX, fieldY, innerW, "Your offer UUID",
                    "Offer ID from one of your own active franchise offers.");
        } else if (shopBusinessActionModal == ShopBusinessActionModal.CORPORATE_BRANCH) {
            drawShopBusinessModalInputLabel(graphics, innerX, fieldY, innerW, "Owned branch shop UUID",
                    "Shop ID for an owned Corporate Retail Chain shop to add or remove as a branch.");
        }
    }

