    private int getFranchiseBrandSectionHeight(int width) {
        return width >= 520 ? 156 : 222;
    }

    private int getFranchiseAcceptedContractSectionHeight(int width, int requirementCount) {
        int visibleRequirements = Math.max(1, Math.min(3, Math.max(0, requirementCount)));
        return 68 + (visibleRequirements * 40);
    }

    private int getBusinessListSectionHeight(int width, int count, int cardHeight) {
        int cols = width >= 760 ? 3 : width >= 520 ? 2 : 1;
        int rows = Math.max(1, (Math.max(1, count) + cols - 1) / cols);
        return 48 + (rows * cardHeight) + (Math.max(0, rows - 1) * 8) + 14;
    }

    private int getFranchiseMarketSectionHeight(int width, int count, boolean includeActionButton) {
        return getBusinessListSectionHeight(width, Math.max(1, count), 64) + (includeActionButton ? 34 : 0);
    }

    private int getShopBusinessActionCenterMinHeight(String type) {
        return switch (normalizeBusinessShopType(type)) {
            case "FRANCHISE" -> 320;
            case "CORPORATE_RETAIL_CHAIN" -> 222;
            default -> 222;
        };
    }

    private int getShopBusinessTypeSpecificHeight(ShopBusinessSnapshot snapshot, int width) {
        String type = normalizeBusinessShopType(snapshot == null ? null : snapshot.shopType());
        ShopBusinessSnapshot safe = snapshot == null
                ? parseShopBusinessSnapshot(ClientOwnerPcData.getActionOutputLines())
                : snapshot;
        if ("FRANCHISE".equals(type)) {
            return getFranchiseBrandSectionHeight(width)
                    + 10
                    + (hasAcceptedFranchiseContract(safe)
                    ? getFranchiseAcceptedContractSectionHeight(width, safe.acceptedRequirements().size()) + 10
                    : 0)
                    + getBusinessListSectionHeight(width, Math.max(1, safe.franchiseContracts().size()), 62)
                    + 10
                    + getFranchiseMarketSectionHeight(width, Math.max(1, safe.franchiseOffers().size()), width >= 360 && !safe.franchiseOffers().isEmpty());
        }
        if ("CORPORATE_RETAIL_CHAIN".equals(type)) {
            return 100
                    + getBusinessListSectionHeight(width, Math.max(1, safe.corporateBranches().size()), 58);
        }
        return 114 + 150 + 10;
    }

    private int getShopBusinessPanelContentHeight(ShopBusinessSnapshot snapshot, int width) {
        ShopBusinessSnapshot safe = snapshot == null
                ? parseShopBusinessSnapshot(ClientOwnerPcData.getActionOutputLines())
                : snapshot;
        return getShopBusinessPanelLayout(safe, width, 0, 0).contentHeight();
    }

    private OwnerPcShopBusinessPanelLayout.Layout getShopBusinessPanelLayout(ShopBusinessSnapshot snapshot,
                                                                              int width,
                                                                              int viewportHeight,
                                                                              int requestedScroll) {
        ShopBusinessSnapshot safe = snapshot == null
                ? parseShopBusinessSnapshot(ClientOwnerPcData.getActionOutputLines())
                : snapshot;
        OwnerPcShopBusinessPanelLayout.Dimensions dimensions = OwnerPcShopBusinessPanelLayout.dimensions(width);
        int mainHeight = getShopBusinessTypeSpecificHeight(safe, dimensions.mainWidth());
        int actionHeight = dimensions.wide()
                ? Math.max(mainHeight, getShopBusinessActionCenterMinHeight(safe.shopType()))
                : getShopBusinessActionCenterMinHeight(safe.shopType());
        return OwnerPcShopBusinessPanelLayout.layout(
                width,
                viewportHeight,
                mainHeight,
                actionHeight,
                requestedScroll
        );
    }

    private int getOverviewDashboardContentHeight(int width, int viewportHeight) {
        int cardGap = 6;
        int cardH = 42;
        int cardCols = width >= 560 ? 4 : width >= 360 ? 2 : 1;
        int cardRows = (4 + cardCols - 1) / cardCols;
        int cardsBlock = (cardRows * cardH) + (Math.max(0, cardRows - 1) * cardGap);
        boolean compactCharts = width < 420;
        int chartsBlock = compactCharts ? (62 + 8 + 62 + 10) : (64 + 10);
        int listBlock = 56;
        int estimated = 4 + cardsBlock + 4 + chartsBlock + listBlock + 8;
        return Math.max(viewportHeight, estimated);
    }

    private int getAccountProfileContentHeight(int width, int viewportHeight) {
        int cardGap = 8;
        int cardCols = width >= 420 ? 2 : 1;
        int cardH = 42;
        int cardsBlock = cardCols > 1 ? cardH : ((cardH * 2) + cardGap);
        int estimated = 38 + cardsBlock + 10 + 40 + 8 + 70 + 8;
        return Math.max(viewportHeight, estimated);
    }

    private int getInputHelpContentHeight(InputHelp help, int width, int viewportHeight) {
        int summaryWidth = Math.max(80, width - 16);
        List<String> summaryLines = wrapLines(List.of(help.summary()), summaryWidth);
        int estimated = 36 + 14 + (summaryLines.size() * LINE_HEIGHT) + 22 + 8;
        return Math.max(viewportHeight, estimated);
    }

    private void initShopOverviewCommandCenter(int innerX, int y, int innerWidth, int gap) {
        String[][] actions = {
                {"Scan shelves", "SHELVES", "Open shop-mode shelf data, low-stock cards, and stockroom restock controls."},
                {"Open level roadmap", "ROADMAP", "Open the shop level roadmap with type-specific unlocks."},
                {"Create delivery order", "ORDERS", "Jump to the courier order builder and pallet targeting workflow."},
                {"Set checkout terminal", "TERMINAL", "Bind the nearest payment terminal to this shop checkout."}
        };
        int[] accents = {ORDER_BOARD_CYAN, ORDER_BOARD_VIOLET, ORDER_BOARD_GOLD, ORDER_BOARD_CYAN};
        int buttonW = Math.max(72, innerWidth);
        int buttonH = 22;
        for (int i = 0; i < actions.length; i++) {
            String label = actions[i][0];
            String action = actions[i][1];
            String description = actions[i][2];
            DesktopButton button = addSectionPcButton(
                    innerX,
                    y + (i * (buttonH + 10)),
                    buttonW,
                    buttonH,
                    fitToWidth(label, Math.max(20, buttonW - 12)),
                    accents[Math.min(i, accents.length - 1)],
                    btn -> runShopOverviewCommand(action)
            ).setLabelOffset(6, 1);
            registerShopOperationsHelp(button, label, description);
        }
    }

    private void runShopOverviewCommand(String action) {
        String normalized = action == null ? "" : action.trim().toUpperCase(Locale.ROOT);
        switch (normalized) {
            case "REFRESH" -> sendShopDesktopAction("SHOP_OVERVIEW", "");
            case "ROADMAP" -> {
                shopLevelRoadmapOpen = true;
                shopLevelRoadmapSelectedNode = null;
                shopLevelRoadmapScrollX = 0;
                shopLevelRoadmapMaxScrollX = 0;
                shopLevelRoadmapScrollbarDragging = false;
                outputScroll = 0;
                sectionScroll = 0;
                sendShopDesktopAction("SHOP_LEVEL_ROADMAP", "");
                rebuildWidgets();
            }
            case "TERMINAL" -> sendShopDesktopAction("SHOP_SET_CHECKOUT_TERMINAL", "");
            case "SHELVES" -> {
                activeSection = Section.LIMITS;
                shopStockroomViewOpen = false;
                outputScroll = 0;
                sectionScroll = 0;
                sendShopDesktopAction("SHOP_SCAN", "");
                rebuildWidgets();
            }
            case "RESTOCK" -> sendShopDesktopAction("SHOP_RESTOCK_LOW", "");
            case "CASHIERS" -> {
                activeSection = Section.STAFFING;
                outputScroll = 0;
                sectionScroll = 0;
                sendShopDesktopAction("SHOP_SCAN_CASHIERS", "");
                rebuildWidgets();
            }
            case "ORDERS" -> {
                activeSection = Section.GOVERNANCE;
                shopOrderPickerOpen = false;
                shopOrderPalletPickerOpen = false;
                outputScroll = 0;
                sectionScroll = 0;
                sendShopDesktopAction("SHOP_ORDER_REPORT", "");
                rebuildWidgets();
            }
            case "FINANCE" -> {
                activeSection = Section.LENDING;
                outputScroll = 0;
                sectionScroll = 0;
                sendShopDesktopAction("SHOP_FINANCE_REPORT", "");
                rebuildWidgets();
            }
            case "CLAIM_PLOT" -> startShopClaimToolAndClose(false);
            case "CLAIM_STOCKROOM" -> startShopClaimToolAndClose(true);
            case "CLAIM_PALLETS" -> startShopPalletClaimToolAndClose();
            default -> sendShopDesktopAction("SHOP_OVERVIEW", "");
        }
    }

