        drawOrderBoardCard(graphics, x, y, width, height, accent, false);
        graphics.drawString(this.font, fitToWidth(label.toUpperCase(Locale.ROOT), width - 18), x + 12, y + 10, ORDER_BOARD_MUTED, false);
        graphics.drawString(this.font, fitToWidth(value, width - 18), x + 12, y + 26, ORDER_BOARD_TEXT, false);
        graphics.drawString(this.font, fitToWidth(subtext, width - 18), x + 12, y + 42, ORDER_BOARD_MUTED, false);
