    private void drawOrderBoardRouteBoard(GuiGraphics graphics, List<OrderBoardCardData> cards, int x, int y, int width, int height) {
        drawOrderBoardPanel(graphics, x, y, width, height, ORDER_BOARD_CYAN);
        graphics.drawString(this.font, "Route board", x + 16, y + 16, ORDER_BOARD_TEXT, false);
        graphics.drawString(this.font, "Open routes and accepted work are shown as compact route rows.", x + 16, y + 30, ORDER_BOARD_MUTED, false);
        List<OrderBoardCardData> routeCards = cards == null ? List.of() : cards.stream()
                .filter(card -> card != null && (isOpenOrder(card) || isCurrentOrder(card)))
                .limit(8)
                .toList();
        int rowY = y + 62;
        int rowH = 46;
        if (routeCards.isEmpty()) {
            drawOrderBoardEmptyState(graphics, x + 16, rowY, width - 32, 58, "No route cards are visible right now.", "Refresh when shops create delivery jobs.");
            return;
        }
        for (OrderBoardCardData card : routeCards) {
            if (rowY + rowH > y + height - 16) {
                break;
            }
            drawOrderBoardRouteRow(graphics, card, x + 16, rowY, width - 32, rowH);
            rowY += rowH + 8;
        }
    }

    private void drawOrderBoardRouteRow(GuiGraphics graphics, OrderBoardCardData card, int x, int y, int width, int height) {
        int accent = orderBoardStatusAccent(card);
        boolean selected = card.orderId() != null && card.orderId().equalsIgnoreCase(orderBoardSelectedOrderId);
        drawOrderBoardCard(graphics, x, y, width, height, accent, selected);
        String title = orderBoardCardTitle(card);
        graphics.drawString(this.font, fitToWidth(title, width - 150), x + 14, y + 9, ORDER_BOARD_TEXT, false);
        graphics.drawString(this.font, fitToWidth(orderBoardReward(card) + " | " + orderBoardTarget(card), width - 150), x + 14, y + 25, ORDER_BOARD_MUTED, false);
        String status = orderBoardStatus(card);
        drawOrderBoardPill(graphics, x + width - 106, y + 14, 92, status, accent);
        visibleOrderBoardCards.add(new OrderBoardCardHitbox(x, y, width, height, card, OrderBoardAction.DETAILS));
    }

    private void drawOrderBoardCourierPulse(GuiGraphics graphics,
                                            OrderBoardSummary summary,
                                            int x,
                                            int y,
                                            int width,
                                            int height,
                                            String rank,
                                            int success,
                                            long streak) {
        drawOrderBoardPanel(graphics, x, y, width, height, ORDER_BOARD_VIOLET);
        graphics.drawString(this.font, "Courier pulse", x + 16, y + 16, ORDER_BOARD_TEXT, false);
        graphics.drawString(this.font, "Rank badge, streak glow, and payout pressure.", x + 16, y + 30, ORDER_BOARD_MUTED, false);
        int circleR = Math.min(92, Math.max(50, Math.min(width - 44, height - 166) / 2));
        int cx = x + width / 2;
        int cy = y + 76 + circleR;
        drawOrderBoardBadgeCircle(graphics, cx, cy, circleR, ORDER_BOARD_VIOLET, ORDER_BOARD_CYAN);
        graphics.drawCenteredString(this.font, fitToWidth(rank.toUpperCase(Locale.ROOT), Math.max(70, circleR * 2 - 20)), cx, cy - 8, ORDER_BOARD_TEXT);
        graphics.drawCenteredString(this.font, streak + " streak", cx, cy + 8, streak >= 3 ? ORDER_BOARD_GREEN : ORDER_BOARD_MUTED);
        int statsY = Math.min(y + height - 112, cy + circleR + 22);
        drawOrderBoardProgress(graphics, x + 18, statsY, width - 36, "Success", success + "%", success / 100.0F, ORDER_BOARD_GREEN);
        String completed = summary == null ? "0" : String.valueOf(Math.max(0L, summary.completedTotal()));
        String nextRank = summary == null ? "10" : (summary.nextRankAt() <= 0 ? "max" : String.valueOf(summary.nextRankAt()));
        graphics.drawString(this.font, fitToWidth("Completed " + completed + " | Next rank " + nextRank, width - 36), x + 18, statsY + 44, ORDER_BOARD_MUTED, false);
        int bonusY = Math.min(y + height - 52, statsY + 62);
        drawOrderBoardToast(graphics, x + 18, bonusY, width - 36, 36,
                streak >= 3 ? "Streak bonus active for this courier." : "Bonus unlocks as the streak grows.",
                ORDER_BOARD_GREEN);
    }

    private void drawOrderBoardOpenOrders(GuiGraphics graphics, List<OrderBoardCardData> cards, int x, int y, int width, int viewY, int viewH) {
        int cols = width >= 760 ? 2 : 1;
        int gap = 14;
        int cardH = 124;
        int toolbarEnd = width >= 620 ? 104 : 138;
        int rows = Math.max(1, (cards.size() + cols - 1) / cols);
        int sectionH = toolbarEnd + rows * cardH + Math.max(0, rows - 1) * gap + 20;
        drawOrderBoardPanel(graphics, x, y, width, Math.max(240, sectionH), ORDER_BOARD_CYAN);
        graphics.drawString(this.font, "Open orders", x + 16, y + 16, ORDER_BOARD_TEXT, false);
        graphics.drawString(this.font, "Accept jobs from shops that need shelf items delivered to a pallet.", x + 16, y + 30, ORDER_BOARD_MUTED, false);
        int inputY = y + 56;
        int startY;
        if (width >= 620) {
            drawOrderBoardInputChrome(graphics, x + 16, inputY, Math.max(120, width - 284), 28);
            drawOrderBoardSmallButton(graphics, x + width - 252, inputY, 116, 28, "Sort: " + orderBoardSort.label(), ORDER_BOARD_GOLD, null, null);
            drawOrderBoardSmallButton(graphics, x + width - 126, inputY, 110, 28, "Filter: " + orderBoardOpenFilter.label(), ORDER_BOARD_CYAN, null, null);
            startY = y + 104;
        } else {
            drawOrderBoardInputChrome(graphics, x + 16, inputY, width - 32, 28);
            int btnW = Math.max(90, (width - 42) / 2);
            drawOrderBoardSmallButton(graphics, x + 16, inputY + 36, btnW, 26, "Sort: " + orderBoardSort.label(), ORDER_BOARD_GOLD, null, null);
            drawOrderBoardSmallButton(graphics, x + 26 + btnW, inputY + 36, btnW, 26, "Filter: " + orderBoardOpenFilter.label(), ORDER_BOARD_CYAN, null, null);
            startY = y + 138;
        }
        if (cards.isEmpty()) {
            drawOrderBoardEmptyState(graphics, x + 16, startY, width - 32, 72, "No open delivery orders right now.", "Refresh after a shop creates a delivery order.");
            return;
        }
        int cardW = Math.max(220, (width - 32 - gap * (cols - 1)) / cols);
        for (int i = 0; i < cards.size(); i++) {
            int cardX = x + 16 + (i % cols) * (cardW + gap);
            int cardY = startY + (i / cols) * (cardH + gap);
            if (cardY > viewY + viewH || cardY + cardH < viewY) {
                continue;
            }
            drawOrderBoardJobCard(graphics, cards.get(i), cardX, cardY, cardW, cardH, true);
        }
    }

    private void drawOrderBoardCurrentOrders(GuiGraphics graphics, List<OrderBoardCardData> cards, int x, int y, int width) {
        OrderBoardCardData current = selectVisibleOrder(cards);
        int routeH = 360;
        drawOrderBoardPanel(graphics, x, y, width, routeH, ORDER_BOARD_GREEN);
        graphics.drawString(this.font, "Current route", x + 18, y + 18, ORDER_BOARD_TEXT, false);
        graphics.drawString(this.font, "Accepted by you; cancellation resets streak and returns order to open pool.", x + 18, y + 34, ORDER_BOARD_MUTED, false);
        if (current == null) {
            drawOrderBoardEmptyState(graphics, x + 18, y + 76, width - 36, 104,
                    "No active orders are visible for you right now.",
                    "Accept an open route to populate this panel.");
        } else {
            drawOrderBoardCurrentRouteCard(graphics, current, x + 24, y + 78, width - 48, 128);
            int btnY = y + 242;
            int btnW = Math.max(150, Math.min(210, (width - 72) / 2));
            drawOrderBoardSmallButton(graphics, x + 24, btnY, btnW, 28, "Trace pallet", ORDER_BOARD_CYAN, current, OrderBoardAction.TRACE);
            drawOrderBoardSmallButton(graphics, x + 34 + btnW, btnY, btnW, 28, "Cancel mine", ORDER_BOARD_RED, current, OrderBoardAction.CANCEL_PROMPT);
        }

        int checklistY = y + routeH + 22;
        int checklistH = 230;
        drawOrderBoardPanel(graphics, x, checklistY, width, checklistH, ORDER_BOARD_CYAN);
        graphics.drawString(this.font, "Route checklist", x + 18, checklistY + 18, ORDER_BOARD_TEXT, false);
        graphics.drawString(this.font, "The app tells couriers what must happen to finish the route.", x + 18, checklistY + 34, ORDER_BOARD_MUTED, false);
        drawOrderBoardChecklistRow(graphics, x + 18, checklistY + 72, width - 36,
                "Pick up assigned boxes", "Order items must be in cardboard boxes.", current == null ? "Waiting" : "Done", current != null);
        drawOrderBoardChecklistRow(graphics, x + 18, checklistY + 126, width - 36,
                "Deliver to target pallet", "Only the assigned pallet completes this order.", current == null ? "Waiting" : "Pending", false);
    }

    private void drawOrderBoardFinishedOrders(GuiGraphics graphics, List<OrderBoardCardData> cards, int x, int y, int width, int viewY, int viewH) {
        int filterH = width >= 620 ? 112 : 146;
        drawOrderBoardPanel(graphics, x, y, width, filterH, ORDER_BOARD_CYAN);
        graphics.drawString(this.font, "History filters", x + 16, y + 16, ORDER_BOARD_TEXT, false);
        graphics.drawString(this.font, "Search completed, canceled, expired, and failed courier rows.", x + 16, y + 32, ORDER_BOARD_MUTED, false);
        int inputY = y + 62;
        if (width >= 620) {
            int buttonW = 116;
            drawOrderBoardInputChrome(graphics, x + 16, inputY, Math.max(120, width - 48 - buttonW * 2), 28);
            drawOrderBoardSmallButton(graphics, x + width - 24 - buttonW * 2, inputY, buttonW, 28, "Status: " + orderBoardHistoryFilter.label(), ORDER_BOARD_CYAN, null, null);
            drawOrderBoardSmallButton(graphics, x + width - 16 - buttonW, inputY, buttonW, 28, "Copy rows", ORDER_BOARD_GOLD, null, null);
        } else {
            drawOrderBoardInputChrome(graphics, x + 16, inputY, width - 32, 28);
            int btnW = Math.max(90, (width - 42) / 2);
            drawOrderBoardSmallButton(graphics, x + 16, inputY + 36, btnW, 26, "Status: " + orderBoardHistoryFilter.label(), ORDER_BOARD_CYAN, null, null);
            drawOrderBoardSmallButton(graphics, x + 26 + btnW, inputY + 36, btnW, 26, "Copy rows", ORDER_BOARD_GOLD, null, null);
        }

        int listY = y + filterH + 16;
        int listH = Math.max(360, 82 + Math.max(1, cards.size()) * 58);
        drawOrderBoardPanel(graphics, x, listY, width, listH, ORDER_BOARD_GREEN);
        graphics.drawString(this.font, "Completed orders", x + 16, listY + 16, ORDER_BOARD_TEXT, false);
        graphics.drawString(this.font, "Finished and failed delivery history exposed by the current board payload.", x + 16, listY + 32, ORDER_BOARD_MUTED, false);
        int rowY = listY + 68;
        int rowH = 46;
        if (cards.isEmpty()) {
            drawOrderBoardEmptyState(graphics, x + 16, rowY, width - 32, 72, "No finished order rows are exposed by the current board payload.", "Use Refresh after shops create or update delivery orders.");
            return;
        }
        for (OrderBoardCardData card : cards) {
            if (rowY > viewY + viewH || rowY + rowH < viewY) {
                rowY += rowH + 8;
                continue;
            }
            drawOrderBoardHistoryRow(graphics, card, x + 16, rowY, width - 32, rowH);
            rowY += rowH + 8;
        }
    }

    private void drawOrderBoardJobCard(GuiGraphics graphics, OrderBoardCardData card, int x, int y, int width, int height, boolean acceptAction) {
        int accent = orderBoardStatusAccent(card);
        boolean selected = card.orderId() != null && card.orderId().equalsIgnoreCase(orderBoardSelectedOrderId);
        drawOrderBoardCard(graphics, x, y, width, height, accent, selected);
        visibleOrderBoardCards.add(new OrderBoardCardHitbox(x, y, width, height, card, OrderBoardAction.SELECT));
        graphics.drawString(this.font, fitToWidth(orderBoardCardTitle(card), width - 132), x + 14, y + 12, ORDER_BOARD_TEXT, false);
        graphics.drawString(this.font, orderBoardReward(card), x + width - Math.min(94, this.font.width(orderBoardReward(card)) + 10), y + 12, ORDER_BOARD_GOLD, false);
        graphics.drawString(this.font, fitToWidth("Pickup shelf item | " + orderBoardTarget(card), width - 28), x + 14, y + 34, ORDER_BOARD_MUTED, false);
        graphics.drawString(this.font, fitToWidth("Created " + formatRelativeTime(card.createdAtMillis()) + " | " + orderBoardRouteMetric(card), width - 28), x + 14, y + 52, ORDER_BOARD_MUTED, false);
        graphics.drawString(this.font, fitToWidth("Order " + shortUuid(card.orderId()) + " | Shop " + shortUuid(card.shopId()), width - 28), x + 14, y + 70, ORDER_BOARD_MUTED, false);
        drawOrderBoardPill(graphics, x + width - 110, y + 38, 92, orderBoardStatus(card), accent);
        int btnY = y + height - 30;
        int btnW = Math.max(86, (width - 36) / 2);
        drawOrderBoardSmallButton(graphics, x + 14, btnY, btnW, 20, "Details", ORDER_BOARD_CYAN, card, OrderBoardAction.DETAILS);
        drawOrderBoardSmallButton(graphics, x + width - 14 - btnW, btnY, btnW, 20, acceptAction ? "Accept" : "Select", acceptAction ? ORDER_BOARD_GREEN : ORDER_BOARD_CYAN, card, acceptAction ? OrderBoardAction.ACCEPT : OrderBoardAction.SELECT);
    }

