    private void drawOrderBoardLeaderboardRow(GuiGraphics graphics,
                                              int x,
                                              int y,
                                              int width,
                                              int height,
                                              String title,
                                              String subtitle,
                                              String badge,
                                              int accent) {
        if (width <= 0 || height <= 0) {
            return;
        }
        String safeBadge = badge == null || badge.isBlank() ? "-" : badge;
        graphics.fill(x, y, x + width, y + height, ORDER_BOARD_BORDER);
        graphics.fill(x + 1, y + 1, x + width - 1, y + height - 1, ORDER_BOARD_ROW);
        graphics.fill(x, y, x + 4, y + height, accent);
        int badgeW = width >= 270 ? Math.min(110, Math.max(56, this.font.width(safeBadge) + 16)) : 0;
        int textW = Math.max(42, width - badgeW - 30);
        graphics.drawString(this.font, fitToWidth(title, textW), x + 14, y + 8, ORDER_BOARD_TEXT, false);
        graphics.drawString(this.font, fitToWidth(subtitle, textW), x + 14, y + 26, ORDER_BOARD_MUTED, false);
        if (badgeW > 0) {
            graphics.drawString(this.font, fitToWidth(safeBadge, badgeW),
                    x + width - badgeW - 12,
                    y + Math.max(8, (height - 8) / 2),
                    accent,
                    false);
        }
    }

    private int orderBoardRankAccent(int index) {
        return switch (Math.max(0, index)) {
            case 0 -> ORDER_BOARD_GOLD;
            case 1 -> ORDER_BOARD_CYAN;
            case 2 -> ORDER_BOARD_VIOLET;
            default -> ORDER_BOARD_GREEN;
        };
    }

    private String orderBoardRankCourierName(OrderBoardRankRow row) {
        if (row == null) {
            return "-";
        }
        String name = row.courierName() == null ? "" : row.courierName().trim();
        if (!name.isBlank() && !"-".equals(name)) {
            return name;
        }
        return shortUuid(row.courierId());
    }

    private String orderBoardRankSubtitle(OrderBoardRankRow row) {
        if (row == null) {
            return "-";
        }
        String primary = row.primary() == null || row.primary().isBlank() ? "-" : row.primary().trim();
        String secondary = row.secondary() == null || row.secondary().isBlank() ? "" : row.secondary().trim();
        return secondary.isBlank() ? primary : primary + " | " + secondary;
    }

    private void drawOrderBoardMiniStat(GuiGraphics graphics, int x, int y, int width, String label, String value, int accent) {
        drawOrderBoardCard(graphics, x, y, width, 46, accent, false);
        graphics.drawString(this.font, fitToWidth(label.toUpperCase(Locale.ROOT), width - 18), x + 12, y + 8, ORDER_BOARD_MUTED, false);
        graphics.drawString(this.font, fitToWidth(value, width - 18), x + 12, y + 24, ORDER_BOARD_TEXT, false);
    }

    private void drawOrderBoardProgress(GuiGraphics graphics, int x, int y, int width, String label, String value, float progress, int accent) {
        float clamped = Math.max(0.0F, Math.min(1.0F, progress));
        graphics.drawString(this.font, fitToWidth(label, width / 2), x, y, ORDER_BOARD_MUTED, false);
        graphics.drawString(this.font, fitToWidth(value, width / 2), x + width - Math.min(width / 2, this.font.width(value)), y, ORDER_BOARD_TEXT, false);
        int barY = y + 20;
        graphics.fill(x, barY, x + width, barY + 8, ORDER_BOARD_ROW);
        graphics.fill(x, barY, x + Math.max(3, (int) (width * clamped)), barY + 8, accent);
    }

    private float routeTimeProgress(OrderBoardCardData card) {
        if (card == null || card.timeoutMinutes() <= 0) {
            return 0.0F;
        }
        long totalSeconds = Math.max(1L, (long) card.timeoutMinutes() * 60L);
        long remaining = Math.max(0L, Math.min(totalSeconds, card.remainingSeconds()));
        return remaining / (float) totalSeconds;
    }

    private void drawOrderBoardPill(GuiGraphics graphics, int x, int y, int width, String label, int accent) {
        graphics.fill(x, y, x + width, y + 18, 0x6607111E);
        graphics.fill(x, y, x + width, y + 1, accent);
        graphics.drawCenteredString(this.font, fitToWidth(label.toUpperCase(Locale.ROOT), width - 8), x + width / 2, y + 5, accent);
    }

