    private String cleanWebshopOrderError(String raw) {
        if (raw == null) {
            return "";
        }
        String clean = raw.trim();
        if (clean.isBlank() || "-".equals(clean)) {
            return "";
        }
        return clean;
    }

    private boolean isBlankWebshopOrderError(String raw) {
        return cleanWebshopOrderError(raw).isBlank();
    }

    private String formatWebshopBoxSlotCount(int requiredBoxes) {
        int count = Math.max(0, requiredBoxes);
        return count + " cardboard box slot" + (count == 1 ? "" : "s");
    }

    private String webshopOrderFixHint(String reason, int requiredBoxes) {
        String clean = cleanWebshopOrderError(reason);
        String slotNeed = formatWebshopBoxSlotCount(requiredBoxes);
        return switch (clean) {
            case "Delivery context unavailable." ->
                    "Retry after the server finishes loading, or ask an admin to check the bank/shop data.";
            case "Order has no deliverable items." ->
                    "Add catalog items to the cart and place a new order.";
            case "Delivery dimension is unavailable." ->
                    "Place a new order after selecting a valid delivery shop.";
            case "Missing shop binding for pallet delivery." ->
                    "Select a shop in Retail Webshop > Delivery before checkout, then place a new order.";
            case "Linked shop no longer exists." ->
                    "Recreate/select a shop, then place a new order.";
            case "No assigned delivery pallets available." ->
                    "Open Bank Owner PC > Retail Shop > Order Manager > Delivery Pallets, use the Delivery Pallet Claim Tool on a pallet inside the shop claim, then Paper=Save.";
            case "Specific pallet is no longer assigned." ->
                    "Reassign that pallet in Delivery Pallets, or choose another pallet in Retail Webshop > Delivery.";
            case "Specific pallet is currently missing.", "Target pallet is not loaded.", "Target pallet data is unavailable." ->
                    "Place/load the assigned pallet inside the shop claim, keep that chunk loaded, or select another live pallet.";
            case "All assigned delivery pallets are full.", "Target pallet does not have enough free space.", "Pallet became full during delivery." ->
                    "Clear assigned delivery pallet space or assign more pallets. This order needs " + slotNeed + ".";
            case "Pallet dimension is unavailable." ->
                    "Load the dimension containing the assigned pallet, or reassign a pallet in a loaded dimension.";
            default ->
                    "Check Retail Webshop > Delivery and Bank Owner PC > Retail Shop > Order Manager > Delivery Pallets. This order needs " + slotNeed + ".";
        };
    }

    private WebshopSummary parseWebshopSummary(List<String> lines) {
        // Token map keys are produced by ShopService.webshopReport.
        Map<String, String> values = parseAtTokenMap(lines);
        if (!values.containsKey("webshop.summary.catalog_count")
                && !values.containsKey("webshop.summary.cart_lines")
                && !values.containsKey("webshop.summary.total_cents")) {
            return null;
        }
        String dim = "minecraft:overworld";
        int x = 0;
        int y = 0;
        int z = 0;
        boolean expedite = "1".equals(values.get("webshop.selected.expedite"))
                || "true".equalsIgnoreCase(values.getOrDefault("webshop.selected.expedite", ""));
        return new WebshopSummary(
                Math.max(0L, parseLongMetricToken(values.get("webshop.summary.catalog_count"))),
                Math.max(0L, parseLongMetricToken(values.get("webshop.summary.cart_lines"))),
                Math.max(0L, parseLongMetricToken(values.get("webshop.summary.cart_units"))),
                Math.max(0L, parseLongMetricToken(values.get("webshop.summary.subtotal_cents"))),
                Math.max(0L, parseLongMetricToken(values.get("webshop.summary.surcharge_cents"))),
                Math.max(0L, parseLongMetricToken(values.get("webshop.summary.total_cents"))),
                Math.max(0L, parseLongMetricToken(values.get("webshop.summary.queued_orders"))),
                Math.max(1L, parseLongMetricToken(values.get("webshop.summary.max_active_orders"))),
                Math.max(0L, parseLongMetricToken(values.get("webshop.delivery.required_boxes"))),
                Math.max(0L, parseLongMetricToken(values.get("webshop.delivery.free_slots"))),
                Math.max(0L, parseLongMetricToken(values.get("webshop.delivery.assigned_pallets"))),
                values.getOrDefault("webshop.selected.account_id", ""),
                values.getOrDefault("webshop.selected.mode", "PALLET_RANDOM"),
                values.getOrDefault("webshop.selected.shop_id", ""),
                values.getOrDefault("webshop.selected.pallet_id", ""),
                expedite,
                dim,
                x,
                y,
                z
        );
    }

    private List<WebshopCatalogCardData> parseWebshopCatalogCards(List<String> lines) {
        if (lines == null || lines.isEmpty()) {
            return List.of();
        }
        List<WebshopCatalogCardData> out = new ArrayList<>();
        for (String raw : lines) {
            if (raw == null) {
                continue;
            }
            String line = raw.trim();
            if (!line.startsWith("@webshop_catalog=")) {
                continue;
            }
            String payload = line.substring("@webshop_catalog=".length()).trim();
            if (payload.isBlank()) {
                continue;
            }
            String[] parts = payload.split("\\|", -1);
            if (parts.length < 6) {
                continue;
            }
            int index = parseIntMetricToken(parts[0]);
            if (index <= 0) {
                index = out.size() + 1;
            }
            String itemId = parts[1].trim();
            if (itemId.isBlank()) {
                continue;
            }
            String itemName = parts[2].trim().isBlank() ? itemId : parts[2].trim();
            out.add(new WebshopCatalogCardData(
                    index,
                    itemId,
                    itemName,
                    parts[3].trim(),
                    Math.max(0L, parseLongMetricToken(parts[4])),
                    parts[5].trim()
            ));
        }
        out.sort(Comparator.comparingInt(WebshopCatalogCardData::index));
        return out;
    }

